      albumStreams,
      compileSongs,
      updateChartRecords,
      settleAudience,
      applyAudienceEvent,
      updateCareerWorld,
      closeFinances,
      clamp,
      finishCareerWeek,
      scanAchievements,
      catalogReport,
      weeklyNews,
      log,
      compact,
      fmt,
