openTour=function(step=0){if(!saveReady||saveConflict)return;if($('modal').open)$('modal').close();if(tourStep<0)tourOrigin={tab,careerTab,industryTab,chartKind,chartMine};titleVisible=false;tourStep=Math.max(0,Math.min(V080_GAMEPLAY_TOUR.length-1,step));renderTitle();const t=V080_GAMEPLAY_TOUR[tourStep];if(t.page==='Industry'){industryTab=t.section;if(t.section==='Charts'){chartKind='Songs';chartMine=false}}if(t.page==='Career')careerTab=t.section;tab=t.page;render();renderGameplayTour()};
renderGameplayTour=function(){const panel=$('gameplay-tour');if(!panel)return;clearTourTarget();panel.hidden=tourStep<0;document.body?.classList[tourStep>=0?'add':'remove']('tour-running');for(const el of document.querySelectorAll?.('main,nav,.weekbar')||[])el.inert=tourStep>=0;if(tourStep<0)return;const t=V080_GAMEPLAY_TOUR[tourStep];panel.innerHTML=`<div class="coach-inner"><div class="coach-top"><span>GAMEPLAY TOUR · ${tourStep+1} / ${V080_GAMEPLAY_TOUR.length}</span><button class="text-button" onclick="endTour()">Skip tour</button></div><h2 id="coach-title">${esc(t.title)}</h2><p>${esc(t.text)}</p><div class="coach-controls"><button class="secondary" onclick="${tourStep===0?'endTour()':'openTour(tourStep-1)'}">Back</button><span>${esc(t.page)}${t.section?' · '+esc(t.section):''}</span><button class="primary" onclick="${tourStep===V080_GAMEPLAY_TOUR.length-1?'endTour()':'openTour(tourStep+1)'}">${tourStep===V080_GAMEPLAY_TOUR.length-1?'Finish tour':'Next'}</button></div></div>`;const target=document.querySelector?.(t.target);if(target){tourTarget=target;target.classList?.add('tour-target');if(target.style)target.style.scrollMarginTop=((panel.getBoundingClientRect?.().height||220)+18)+'px';target.scrollIntoView?.({behavior:'auto',block:'start'})}panel.querySelector?.('h2')?.setAttribute('tabindex','-1');panel.querySelector?.('h2')?.focus({preventScroll:true})};

