currentDrops=function(){const items=wealthItems.filter(x=>!marketInstrument(x.id)),month=s.empire.month,count=Math.min(10,Math.max(1,items.length));return Array.from({length:count},(_,i)=>{const item=items[(month*7+i*5+i*i)%items.length],limited=i<4,edition=editionNames[(month+i*2)%editionNames.length];return {id:month+'-'+i,month,item:item.id,name:item.name+' · '+edition,price:cents(item.price*(limited?1.08+(i%3)*.045:1+(i%4)*.018)),edition,limited}})};
