validatePresentationState=function(){if(s.onboarding&&(s.onboarding.version!==1||typeof s.onboarding.seen!=='boolean'))throw Error('Invalid onboarding');if(s.collection&&(!Array.isArray(s.collection.purchased)||s.collection.purchased.length>180||new Set(s.collection.purchased).size!==s.collection.purchased.length||s.collection.purchased.some(id=>typeof id!=='string'||!/^\d+-(?:[0-9]|1[01])$/.test(id))))throw Error('Invalid collection');for(const m of s.empire.merch)if(m.look!==undefined&&(!Number.isInteger(m.look)||m.look<0||m.look>=V080_merchLooks.length))throw Error('Invalid merchandise artwork');for(const a of s.empire.assets)if(a.editionId!==undefined&&(typeof a.editionId!=='string'||!/^\d+-(?:[0-9]|1[01])$/.test(a.editionId)||typeof a.edition!=='string'))throw Error('Invalid edition');if(s.v080){if(s.v080.version!==V080_SCHEMA||!Array.isArray(s.v080.commercial?.offers)||!Array.isArray(s.v080.catalog?.holdings))throw Error('Invalid 0.8 state');for(const h of s.v080.catalog.holdings)if(!Number.isInteger(h.id)||!Number.isInteger(h.artist)||!Number.isFinite(h.share)||h.share<=0||h.share>1||!Number.isFinite(h.basis)||h.basis<0)throw Error('Invalid catalog holding')}};


