  z.events.unshift({artist:a.id,week:s.week,title,body,tone});z.events=z.events.slice(0,180);c.lastHeadlineWeek=s.week;
  if(typeof V082_pushHeadline==='function')V082_pushHeadline(a,title,body,tone)
