  z.lastSpawnWeek=s.week;
  const active=s.world.filter(a=>a.aiCareer?.status!=='retired').length,count=active<32?2:1,out=[];
  for(let i=0;i<count&&s.world.length<AI_WORLD_MAX;i++){const a=aiCreateArtist();if(a)out.push(a)}
