composePulse=function(){if(!labelActive()||s.social.posts.filter(p=>p.week===s.week).length>=3)return;modal(`<h2>Create a PULSE post</h2><p>This is part of your simulated career. Posts do not go to real social platforms.</p><form class="form" onsubmit="publishPulse(event)"><label>Format<select name="format">${pulseFormats.map(f=>`<option value="${f.id}">${f.name} · ${f.energy} energy</option>`).join('')}</select></label><label>Caption<textarea name="caption" maxlength="220" required placeholder="What do you want your audience to hear?"></textarea></label><label>Song link <span class="fine">(optional)</span><select name="song"><option value="">No song link</option>${s.songs.filter(x=>x.released).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></label><p class="fine">Normal posts never require a song. Only the Release Announcement format requires you to choose a released track.</p><details><summary>How formats work</summary>${pulseFormats.map(f=>`<p><strong>${f.name}:</strong> ${f.note}</p>`).join('')}</details><p class="fine">Results depend on your skills, format and audience response. Repeating one format this week reduces reach. Linked posts can add up to 20% social reach to that song at week close. Maximum three posts per week.</p><button class="primary">Publish in-game post</button></form>`)};

V081_settleSports=function(){migrateV083();const sports=s.v081.sports;if(sports.lastSettledMonth===s.empire.month)return 0;sports.lastSettledMonth=s.empire.month;let payouts=0;const finished=[];for(const t of sports.teams){const remaining=Math.max(0,82-t.games),gamesThisMonth=Math.min(remaining,(s.empire.month%6===5?6:7));for(let i=0;i<gamesThisMonth;i++){const win=Math.random()<clamp(.24+t.rating/190,.27,.80);if(win)t.wins++;else t.losses++;t.games++}const pct=t.games?t.wins/t.games:.5,performance=(pct-.5)*.035,marketBias=(t.value/8200000000)*.003,move=.002+marketBias+performance+rand(-.012,.012);t.value=cents(Math.max(500000000,t.value*(1+move)));t.history.push({month:s.empire.month,value:t.value});t.history=t.history.slice(-36);if(t.games>=82)finished.push(t)}if(finished.length===sports.teams.length){const champion=finished.slice().sort((a,b)=>(b.wins/82)-(a.wins/82)||b.rating-a.rating)[0];for(const t of finished){const pct=t.wins/82;t.lastSeason={season:t.season,wins:t.wins,losses:t.losses,champion:t.id===champion.id};if(t.id===champion.id){t.titles++;t.value=cents(t.value*1.04)}t.rating=clamp(Math.round(t.rating+(pct-.5)*14+(t.id===champion.id?3:0)+rand(-3,3)),40,98);t.season++;t.wins=0;t.losses=0;t.games=0}}for(const h of sports.holdings){const t=sports.teams.find(x=>x.id===h.team);if(!t)continue;const distribution=cents(t.value*h.share*.00035);if(distribution>0){changeCash(distribution);recordIncome('investment',distribution);h.payouts=cents((h.payouts||0)+distribution);payouts+=distribution}h.history??=[];h.history.push({month:s.empire.month,value:t.value*h.share});h.history=h.history.slice(-36)}return payouts};

