personPhoto=function(key,name,large=false){const gender=V083_nameGender(name);let h=2166136261;for(const c of String(name||key))h=Math.imul(h^c.charCodeAt(0),16777619)>>>0;const skin=['#5b3527','#754734','#925c42','#b97958','#d19a73','#e4b990','#8d5a45','#c98b68'][h%8],hair=['#151218','#2a1a16','#3a2820','#5d3a24','#10151c','#6a4a2c'][Math.floor(h/8)%6],shirt=['#264653','#5b2a50','#33415c','#7a4b2f','#1f4d3b','#493657','#2f4858','#673c4f'][Math.floor(h/48)%8],bg=['#d7b56d','#8fb8b2','#b894c4','#a4b7d3','#d49b82','#87a57a','#c5a27a','#7aa7bd'][Math.floor(h/384)%8];const female=[`<path d="M18 47q0-35 32-35t32 35v19q-5-13-12-22-3 12-20 12T30 44q-8 9-12 22z" fill="${hair}"/>`,`<path d="M20 46q1-33 30-33 26 0 31 31l-10-11q-3 14-21 14-16 0-22-13l-8 12v20H16z" fill="${hair}"/>`,`<path d="M21 43q4-31 29-31 28 0 31 34l-12-12-12 7-13-7-23 12z" fill="${hair}"/><path d="M22 42q-2 23 5 37M78 42q2 23-5 37" stroke="${hair}" stroke-width="8" stroke-linecap="round"/>`],male=[`<path d="M23 36q6-23 27-23 23 0 28 25-10-9-18-8-3 8-14 8-12 0-23-2z" fill="${hair}"/>`,`<path d="M22 38q3-25 28-25 14 0 25 12l-7 11-12-7-12 5-22 4z" fill="${hair}"/>`,`<path d="M26 31q8-19 25-19 18 0 24 22l-11-7-12 4-10-5-16 5z" fill="${hair}"/>`],neutral=[`<path d="M22 40q2-27 28-27t29 28q-8-11-18-10-4 8-13 8-14 0-26 1z" fill="${hair}"/>`,`<path d="M20 43q2-30 30-30 25 0 30 29l-12-9-10 6-12-7-26 11z" fill="${hair}"/>`],styles=gender==='female'?female:gender==='male'?male:neutral,hairPath=styles[Math.floor(h/3072)%styles.length],earring=gender==='female'&&Math.floor(h/15360)%2===0;const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" rx="16" fill="${bg}"/><circle cx="50" cy="43" r="24" fill="${skin}"/>${hairPath}<path d="M18 100q4-31 32-31t32 31" fill="${shirt}"/><path d="M37 41q5-3 10 0M53 41q5-3 10 0" fill="none" stroke="#2a1a18" stroke-width="1.7" stroke-linecap="round"/><circle cx="42" cy="45" r="2" fill="#151515"/><circle cx="58" cy="45" r="2" fill="#151515"/><path d="M49 47l-2 7h5" fill="none" stroke="rgba(70,40,35,.55)" stroke-width="1.2"/><path d="M44 58q6 4 12 0" fill="none" stroke="#6b353d" stroke-width="2" stroke-linecap="round"/>${earring?'<circle cx="74" cy="52" r="2.2" fill="#f5df9a"/>':''}<path d="M10 83h80" stroke="rgba(255,255,255,.22)"/></svg>`;return `<span class="person-photo v083-person ${large?'portrait-large':''}" role="img" aria-label="Stylized fictional ${gender==='neutral'?'person':gender} portrait of ${esc(name)}" style="background-image:url(&quot;data:image/svg+xml,${encodeURIComponent(svg)}&quot;)"></span>`};

/* Canonical week-close owner. Phase order is part of the save/economy contract.
   Monthly hooks close the outgoing month before weekly royalties, preserving beta accounting.
   Weekly release/chart/audience/finance order lives in core.advanceWeek.
   Annual tax reconciliation is part of that finance close, not a second debit.
   Player actions (studio, PULSE, live shows, offers) are event-driven.
*/
let V083_transitionAdvancing=false;
const MONTH_END_HOOKS=[
 ['industry-life',()=>{migrateIndustryLife();settleIndustryLife()}],
 ['team',()=>settleTeam()],
 ['assets',()=>settleAssets()],['commerce',()=>settleCommerce()],
 ['depth-business',()=>V081_settleMonth(s.lastReport||{})]
];
function isAnnualClosing(week=s.week){return week%52===0}
function V083_isMonthClosing(week=s.week){return calendarMonthAtWeek(week+1)!==calendarMonthAtWeek(week)}
function V083_settleMonthEnd(){for(const [name,settle] of MONTH_END_HOOKS)settle();}
function V083_accumulateWeek(completed,beforeCash){const r=s.lastReport||{},a=s.v083.monthAccumulator;a.streams+=r.streams||0;a.fans+=r.fans||0;a.royalties=cents(a.royalties+(r.royalties||0));a.taxes=cents(a.taxes+(r.finance?.taxReserve||0));a.cashChange=cents(a.cashChange+(s.cash-beforeCash));if(V083_isMonthClosing(completed)){s.empire.lastSettled=completed;s.empire.catalogHistory.unshift({week:s.week,value:catalogValue()});s.empire.catalogHistory=s.empire.catalogHistory.slice(0,36);s.empire.lastMonth={monthIndex:a.monthIndex,start:a.startWeek,end:completed,streams:a.streams,fans:a.fans,royalties:a.royalties,taxes:a.taxes,cashChange:a.cashChange};const next=calendarMonthAtWeek(s.week);s.empire.month=next;s.v083.monthAccumulator={monthIndex:next,startWeek:s.week,streams:0,fans:0,royalties:0,taxes:0,cashChange:0};generateCommercialOffers080?.();rollThreat?.()}else s.empire.month=calendarMonthAtWeek(s.week)}
advance=function(confirmed=false){
 if(!labelActive()||monthlyAdvancing)return;
 migrateV083();
 const closing=V083_isMonthClosing(s.week),risk=typeof V080_offerRiskCount==='function'?V080_offerRiskCount(1):0;
 if(!confirmed){modal(`<h2>Finish ${esc(V083_weekDate(s.week))}?</h2><p>One chart week will resolve. Your unused ${s.energy}/200 energy will be replaced by 200. Songs, charts, contracts, royalties and weekly label activity update every week.</p><p>${closing?'<strong>This also closes '+esc(careerDate())+'.</strong> Monthly assets, rent, catalogs, commercial payments, sports and industry-life systems will settle once.':''} ${risk?'<strong>'+risk+' reviewed offer'+(risk===1?'':'s')+' may expire after this week.</strong>':'Unreviewed offers remain protected until you open them.'}</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep playing</button><button class="primary" onclick="$('modal').close();advance(true)">Advance one week</button></div>`);return}
 backupCareer(false);
 V083_transitionAdvancing=true;
 let tx=null;
 try{
  tx=ENCORE_WEEK_TRANSACTION.run(s,{
   isMonthClosing:()=>closing,
   settleMonthEnd:()=>V083_settleMonthEnd(),
   settleWeek:()=>advanceWeek(true),
   accumulate:({completed,beforeCash})=>V083_accumulateWeek(completed,beforeCash)
  });
  if(!tx.ok){s=tx.state;throw tx.error}
  queueSave();render()
 }catch(error){
  if(tx?.state&&tx.ok===false)s=tx.state;
  try{$('modal').close()}catch{}
  toast('The week could not finish. Your career was restored; please report this issue.');console.error(error)
 }finally{
  V083_transitionAdvancing=false;
  if(saveReady&&$('week'))$('week').textContent=V083_weekDate()
 }
};

/* ENCORE 0.8.4 portrait quality hotfix.
   Keep Safari-safe real <img> rendering, but use ENCORE's illustrated WebP cast sheet
   instead of the temporary procedural SVG faces. The sheet is 4 columns x 2 rows. */
function V084_portraitIndex(key,name){
  const fixed=typeof V083_CAST!=='undefined'?V083_CAST[key]:undefined;
  if(fixed!==undefined)return fixed;
  const gender=V083_nameGender(name);
  const pool=gender==='female'?V083_FEMALE_PORTRAITS:gender==='male'?V083_MALE_PORTRAITS:V083_NEUTRAL_PORTRAITS;
  return pool[V083_nameHash(name)%pool.length];
}
function V084_portraitData(key,name){
  const index=V084_portraitIndex(key,name),col=index%4,row=index<4?0:1,gender=V083_nameGender(name);
  return {index,col,row,gender};
}
personPhoto=function(key,name,large=false){
  const p=V084_portraitData(key,name);
  const left=-(p.col*100),top=-(p.row*100);
  const label=`Illustrated fictional ${p.gender==='neutral'?'person':p.gender} portrait of ${esc(name)}`;
  return `<span class="person-photo v084-person ${large?'portrait-large':''}" role="img" aria-label="${label}" style="overflow:hidden;position:relative;background:#24384b"><img class="v084-person-img" src="${CAST_ART}" alt="" aria-hidden="true" decoding="async" style="position:absolute;display:block;max-width:none;width:400%;height:200%;left:${left}%;top:${top}%;object-fit:fill"></span>`;
};

/* ENCORE 0.8.4 roster + weekly-label polish.
   Keep 18 discoverable artists in the starting industry view, but only render one card per
   illustrated portrait at a time so the screen never shows duplicate faces. The featured
   selection rotates with the career week. Also keep the persistent advance control synced
   with the weekly pacing engine. */
const V084_DISCOVERABLE_ARTISTS=18;
function V084_activeIndustryRoster(world=s.world){return (Array.isArray(world)?world:[]).slice(0,V084_DISCOVERABLE_ARTISTS)}
function V084_filteredIndustryRoster(world=V084_activeIndustryRoster()){
  return world.filter(a=>(filter==='All'||tierNames[tier(a.fans)]===filter)&&(genreFilter==='All'||a.genre===genreFilter));
}
function V084_featuredIndustryRoster(world=V084_activeIndustryRoster()){
  const eligible=V084_filteredIndustryRoster(world);if(!eligible.length)return [];
  const offset=(Math.max(1,s.week)-1)%eligible.length,rotated=eligible.slice(offset).concat(eligible.slice(0,offset));
  const used=new Set(),featured=[];
  for(const a of rotated){const index=V084_portraitIndex('artist-'+(a.directoryKey??a.id),a.name);if(used.has(index))continue;used.add(index);featured.push(a);if(featured.length>=8)break}
  return featured;
}
