/* ENCORE living career foundation: current heat, geography and regional audience. */
const careerStates=['Drought','Cooling','Stable','Rising','Hot','Peak','Breakout','Comeback','Legacy'];
const cityStatusNames=['Unknown','Local Buzz','Hometown Favorite','City Star','City Icon','Cultural Institution'];
const regionalMarkets=[
{id:'austin',city:'Austin',state:'Texas',region:'South',genres:['Rock','Country','Indie folk']},
{id:'atlanta',city:'Atlanta',state:'Georgia',region:'South',genres:['Hip-hop','R&B']},
{id:'la',city:'Los Angeles',state:'California',region:'West',genres:['Pop','Hip-hop','Electronic']},
{id:'nyc',city:'New York',state:'New York',region:'Northeast',genres:['Hip-hop','Jazz','Pop']},
{id:'nashville',city:'Nashville',state:'Tennessee',region:'South',genres:['Country','Rock']},
{id:'miami',city:'Miami',state:'Florida',region:'South',genres:['Latin','Electronic','Pop']},
{id:'chicago',city:'Chicago',state:'Illinois',region:'Midwest',genres:['R&B','Jazz','Electronic']},
{id:'seattle',city:'Seattle',state:'Washington',region:'West',genres:['Rock','Indie folk','Electronic']},
{id:'houston',city:'Houston',state:'Texas',region:'South',genres:['Hip-hop','R&B']},
{id:'dallas',city:'Dallas',state:'Texas',region:'South',genres:['Hip-hop','Country','R&B']},
{id:'detroit',city:'Detroit',state:'Michigan',region:'Midwest',genres:['Hip-hop','R&B','Rock']},
{id:'neworleans',city:'New Orleans',state:'Louisiana',region:'South',genres:['Hip-hop','R&B','Jazz']}
];
function marketTemplate(m,home){const homeBoost=home?18:0;return {id:m.id,city:m.city,state:m.state,region:m.region,streams:0,weeklyStreams:0,previousStreams:0,fans:0,awareness:home?20:0,loyalty:home?30:10,demand:home?18:0,culturalConnection:home?20:0,legacy:0,status:0,growth:0}}
function migrateCareerWorld(){migrateIndustryLife?.();const home=s.scene?.city||'austin';if(!s.careerWorld){s.careerWorld={version:1,hometown:home,currentCity:home,momentum:18,publicInterest:12,fanLoyalty:clamp(s.loyalty||20),industryInfluence:clamp((s.reputation||0)*.7),culturalRelevance:8,recognition:clamp(Math.log10(Math.max(1,s.fans||1))*10),tourDemand:10,state:'Stable',stateSince:s.week||1,comeback:false,lastTotalStreams:s.total||0,lastFans:s.fans||0,lastWeek:s.week||1,markets:{},history:[]}}const w=s.careerWorld;w.version=1;w.hometown=w.hometown||home;w.currentCity=s.scene?.city||w.currentCity||home;for(const m of regionalMarkets)if(!w.markets[m.id])w.markets[m.id]=marketTemplate(m,m.id===w.hometown);for(const key of ['momentum','publicInterest','fanLoyalty','industryInfluence','culturalRelevance','recognition','tourDemand'])w[key]=clamp(Number.isFinite(w[key])?w[key]:0);w.history=Array.isArray(w.history)?w.history:[];reconcileRegionalAudience(w);return w}
function careerWorldMarket(id){const w=migrateCareerWorld();return w.markets[id]||w.markets[w.currentCity]||Object.values(w.markets)[0]}
function careerWorldState(score,previous,w=migrateCareerWorld()){
 const released=s.songs.filter(x=>x.released).sort((a,b)=>a.released-b.released),first=released[0]?.released??s.week,last=released.at(-1)?.released??0,careerAge=Math.max(0,s.week-first);
 const recent=released.filter(x=>s.week-x.released<26),recentPeak=recent.some(x=>x.peak&&x.peak<=10),wasCold=['Drought','Cooling'].includes(previous);
 if(wasCold&&score>=55&&(w.momentum||0)>=52)return 'Comeback';
 if(careerAge<78&&recentPeak&&score>=66)return 'Breakout';
 if(careerAge>=520&&(w.recognition||0)>=72&&score<58&&s.week-last>26)return 'Legacy';
 if(score<25)return 'Drought';
 if(score<43)return 'Cooling';
 if(score<58)return 'Stable';
 if(score<70)return 'Rising';
 if(score<84)return 'Hot';
 return 'Peak'
}
function regionalWeights(track){const w=migrateCareerWorld(),genre=track?.genre||s.genre,totalFans=Math.max(1,Object.values(w.markets).reduce((n,m)=>n+m.fans,0));let weights=regionalMarkets.map(m=>{const x=w.markets[m.id],genreFit=m.genres.includes(genre)?1.35:1,home=m.id===w.hometown?1.65:1,base=.25+x.awareness/55+x.fans/totalFans*4+x.culturalConnection/100;return {id:m.id,weight:Math.max(.05,base*genreFit*home)}});const sum=weights.reduce((n,x)=>n+x.weight,0);return weights.map(x=>({...x,share:x.weight/sum}))}
function recordRegionalStreams(track,streams){if(!streams||streams<1)return;const w=migrateCareerWorld(),weights=regionalWeights(track);let assigned=0;for(let i=0;i<weights.length;i++){const x=weights[i],m=w.markets[x.id],n=i===weights.length-1?Math.max(0,streams-assigned):Math.max(0,Math.floor(streams*x.share));assigned+=n;m.weeklyStreams+=n;m.streams+=n;if(track){track.regionalStreams=track.regionalStreams||{};track.regionalStreams[x.id]=(track.regionalStreams[x.id]||0)+n}}}
function updateRegionalMarkets(){const w=migrateCareerWorld(),weeklyTotal=Object.values(w.markets).reduce((n,m)=>n+m.weeklyStreams,0);for(const m of Object.values(w.markets)){const share=weeklyTotal?m.weeklyStreams/weeklyTotal:0;m.growth=m.previousStreams?Math.round((m.weeklyStreams-m.previousStreams)/Math.max(1,m.previousStreams)*100):m.weeklyStreams?null:0;m.awareness=clamp(m.awareness+Math.min(4,Math.log10(1+m.weeklyStreams)*.45)-(m.weeklyStreams?0:.12));m.loyalty=clamp(m.loyalty+(m.weeklyStreams>m.previousStreams?0.25:-0.05)+(m.id===w.hometown?.08:0));m.demand=clamp(m.awareness*.34+m.loyalty*.22+Math.min(44,Math.log10(1+m.weeklyStreams)*7));if(m.id===w.hometown){m.culturalConnection=clamp(m.culturalConnection+.04+(m.weeklyStreams?Math.min(.3,m.weeklyStreams/500000):0));m.legacy=clamp(m.legacy+Math.min(.12,(s.week||1)/5200)+Math.min(.2,m.streams/2e9))}const cityScore=m.awareness*.25+m.loyalty*.2+m.culturalConnection*.3+m.legacy*.25;m.status=cityScore>=85?5:cityScore>=70?4:cityScore>=53?3:cityScore>=36?2:cityScore>=18?1:0;m.previousStreams=m.weeklyStreams;m.weeklyStreams=0}}
function updateCareerWorld(){
 const w=migrateCareerWorld(),released=s.songs.filter(x=>x.released),recent=released.filter(x=>s.week-x.released<8),streamGain=Math.max(0,(s.total||0)-(w.lastTotalStreams||0)),fanGain=(s.fans||0)-(w.lastFans||0);
 const recentScore=Math.min(100,Math.log10(1+streamGain)*13),chartScore=Math.min(100,recent.reduce((n,x)=>n+(x.peak?Math.max(0,101-x.peak):0),0)/Math.max(1,recent.length));
 const activity=recent.length?70:Math.max(0,55-Math.max(0,s.week-(Math.max(0,...released.map(x=>x.released))||0))*2);
 const latest=[...released].sort((a,b)=>b.released-a.released).slice(0,5),quality=latest.length?latest.reduce((n,x)=>n+(Number(x.quality)||50),0)/latest.length:55;
 const weakRun=latest.length>=3?latest.filter(x=>(Number(x.quality)||50)<55).length:0,oversaturation=Math.max(0,recent.length-3);
 const qualitySignal=clamp((quality-45)*1.35,0,55),droughtPressure=clamp(weakRun*8+oversaturation*7+(streamGain===0&&recent.length?10:0),0,42);
 const targetMomentum=clamp(recentScore*.34+chartScore*.20+activity*.15+qualitySignal*.21+Math.min(10,Math.max(0,fanGain)/Math.max(1,s.fans)*650)-droughtPressure);
 w.releaseForm=Math.round(quality);w.droughtPressure=Math.round(droughtPressure);w.momentum=clamp(w.momentum*.76+targetMomentum*.24);
 w.publicInterest=clamp(w.publicInterest*.82+(w.momentum*.50+Math.min(100,Math.log10(1+s.fans)*13)*.38+qualitySignal*.12)*.18);
 w.fanLoyalty=clamp((s.loyalty||20)*.65+w.fanLoyalty*.35);w.industryInfluence=clamp((s.reputation||0)*.45+Math.min(100,tier(s.fans)*15)*.35+w.culturalRelevance*.2);
 w.culturalRelevance=clamp(w.culturalRelevance*.88+(w.momentum*.42+w.industryInfluence*.28+chartScore*.2+qualitySignal*.1)*.12);
 w.recognition=clamp(Math.max(w.recognition*.995,Math.log10(1+s.fans)*14+Math.min(16,tier(s.fans)*2)));
 const regionalDemand=Object.values(w.markets).reduce((n,m)=>n+m.demand,0)/Object.keys(w.markets).length;w.tourDemand=clamp(w.momentum*.35+w.publicInterest*.25+w.fanLoyalty*.15+regionalDemand*.25);
 const heat=clamp(w.momentum*.43+w.publicInterest*.29+w.culturalRelevance*.18+qualitySignal*.10-droughtPressure*.18),next=careerWorldState(heat,w.state,w);
 if(next!==w.state&&s.week-(w.stateSince||0)>=4){w.history.push({week:s.week,from:w.state,to:next,heat:Math.round(heat),releaseForm:w.releaseForm,droughtPressure:w.droughtPressure});w.history=w.history.slice(-100);w.comeback=next==='Comeback';w.state=next;w.stateSince=s.week}
 updateRegionalMarkets();w.currentCity=s.scene?.city||w.currentCity;w.lastTotalStreams=s.total||0;w.lastFans=s.fans||0;w.lastWeek=s.week
}
function careerPulseCard(){const w=migrateCareerWorld(),markets=Object.values(w.markets),strong=[...markets].sort((a,b)=>b.demand-a.demand).slice(0,3),growing=[...markets].sort((a,b)=>b.growth-a.growth)[0],home=w.markets[w.hometown];return `<section class="card career-pulse"><span class="eyebrow">CAREER PULSE</span><h2>${tierNames[tier(s.fans)]} · ${esc(w.state)}${w.state==='Hot'||w.state==='Dominant'?' 🔥':w.state==='Cold'||w.state==='Slump'?' 🧊':''}</h2>${profileRows([['Momentum',Math.round(w.momentum)+'/100'],['Release form',(w.releaseForm??55)+'/100'],['Drought pressure',(w.droughtPressure??0)+'/100'],['Public interest',Math.round(w.publicInterest)+'/100'],['Cultural relevance',Math.round(w.culturalRelevance)+'/100'],['Industry influence',Math.round(w.industryInfluence)+'/100'],['Recognition',Math.round(w.recognition)+'/100'],['Tour demand',Math.round(w.tourDemand)+'/100']])}<h3>Strongest markets</h3>${strong.map((m,i)=>`<p><strong>${i+1}. ${esc(m.city)}, ${esc(m.state)}</strong> · Demand ${Math.round(m.demand)} · ${compact(m.streams)} career streams</p>`).join('')}<p><strong>Fastest growing:</strong> ${esc(growing.city)} ${regionalGrowthLabel(growing)}</p><p><strong>Hometown:</strong> ${esc(home.city)} · ${cityStatusNames[home.status]} · Connection ${Math.round(home.culturalConnection)}/100</p></section>`}
function regionalAudiencePage(){const w=migrateCareerWorld(),rows=Object.values(w.markets).sort((a,b)=>b.streams-a.streams);return head('See where your career lives','Regional audience.')+`<section class="card"><h2>Market map</h2><p>Regional fans sum to your global audience. Older careers use historical stream shares where available, otherwise an estimated genre spread. Your hometown gets an early cultural advantage, but every market has to be earned.</p>${rows.map(m=>`<div class="row"><div><strong>${esc(m.city)}, ${esc(m.state)}</strong><small>${esc(m.region)} · ${m.id===w.hometown?'Hometown · ':''}${cityStatusNames[m.status]}</small></div><div class="right"><strong>${compact(m.streams)}</strong><small>${compact(m.fans)} fans · Demand ${Math.round(m.demand)} · ${regionalGrowthLabel(m)}</small></div></div>`).join('')}</section>`}

// Regions attribute one global audience; they never mint a second population.
// Largest-remainder allocation conserves every fan, including small audiences.
function reconcileRegionalAudience(w=s.careerWorld){
 if(!w?.markets)return;
 const markets=Object.values(w.markets),target=Math.max(0,Math.floor(s.fans||0));
 const migrating=w.audienceVersion!==1;
 let weights=markets.map(m=>Math.max(0,Number(m.fans)||0));
 if(migrating){
  const observed=markets.map(m=>Math.max(0,Number(m.streams)||0));
  weights=observed.some(Boolean)?observed:markets.map(m=>regionalMarkets.find(x=>x.id===m.id)?.genres.includes(s.genre)?1.35:1);
  w.audienceAttribution=observed.some(Boolean)?'historical-streams':'estimated-genre-spread';
 }
 if(!weights.some(Boolean))weights=markets.map(()=>1);
 const sum=weights.reduce((a,b)=>a+b,0),rows=markets.map((m,i)=>{const exact=target*weights[i]/sum;return {m,value:Math.floor(exact),remainder:exact-Math.floor(exact),i}});
 let left=target-rows.reduce((n,r)=>n+r.value,0);
 rows.sort((a,b)=>b.remainder-a.remainder||a.i-b.i);
 for(const r of rows){r.m.fans=r.value+(left-->0?1:0)}
 w.audienceVersion=1;
}
function regionalGrowthLabel(m){return m.growth===null?'NEW · First tracked week':(m.growth>=0?'+':'')+m.growth+'%'}

/* Persistent geographic identities and slow scene cycles. No invented past events. */
function migrateLivingWorld(){
 const w=migrateCareerWorld();
 for(const m of Object.values(w.markets)){m.sceneHeat??=50;m.sentiment??=50;m.tourFatigue??=0}
 for(const a of s.world){a.hometown??=regionalMarkets[a.id%regionalMarkets.length].id;a.currentCity??=a.hometown}
 w.sceneLastWeek??=s.week-1;
 return w;
}
function settleLivingWorld(){
 const w=migrateLivingWorld();if(w.sceneLastWeek===s.week)return;w.sceneLastWeek=s.week;
 for(const [i,m] of Object.values(w.markets).entries()){
  const cycle=50+25*Math.sin((s.week+i*19)/52),releases=s.world.filter(a=>a.currentCity===m.id).reduce((n,a)=>n+a.catalog.filter(t=>t.week>=s.week-4).length,0);
  m.sceneHeat=clamp(m.sceneHeat*.96+(cycle+Math.min(15,releases*2))*.04);
  m.tourFatigue=Math.max(0,m.tourFatigue-2);
  m.sentiment=clamp(m.sentiment*.99+(m.loyalty*.6+20)*.01);
 }
}

/* Bind legacy ENCORE to the shared renderer-independent Audience Engine. */
applyAudienceEvent=function(source,delta,options={}){
 return ENCORE_AUDIENCE.apply(s,source,delta,options,{
  ensureWorld:()=>migrateCareerWorld(),
  reconcile:()=>reconcileRegionalAudience()
 });
};

/* Player-facing navigation bridge for the Living Career engine.
   V080 replaces the original navigation destination list after navigation.js loads,
   so this late overlay patches the final list that menuResults actually renders. */
function installCareerWorldNavigation(){
 if(typeof V080_destinations==='undefined'||!Array.isArray(V080_destinations))return;
 const additions=[
  ['Career Pulse','Career','CareerPulse','Momentum, demand and career temperature',2],
  ['Audience & Markets','Career','Audience','Regional fans, streams and hometown status',3]
 ];
 const existing=new Set(V080_destinations.map(d=>d[0]));
 const at=V080_destinations.findIndex(d=>d[2]==='ArtistFile');
 const rows=additions.filter(d=>!existing.has(d[0]));
 if(!rows.length)return;
 V080_destinations.splice(at>=0?at:V080_destinations.length,0,...rows)
}
installCareerWorldNavigation();

/* Route the Living Career destinations to their actual player-facing screens.
   These routes are installed late because the 0.8 presentation layers own the final Career renderer. */
const CAREER_WORLD_ROUTE_IDS=new Set(['CareerPulse','Audience']);
function careerWorldPage(id){
 if(id==='CareerPulse')return head('Know where your career stands','Career Pulse.')+careerPulseCard();
 if(id==='Audience')return regionalAudiencePage();
 return '';
}
const careerWorldBaseOpenDestination=openDestination;
openDestination=function(id){
 if(CAREER_WORLD_ROUTE_IDS.has(id)){
  careerTab=id;
  tab='Career';
  render();
  window.scrollTo?.(0,0);
  return;
 }
 return careerWorldBaseOpenDestination(id);
};
const careerWorldBaseCareer=career;
career=function(){
 if(CAREER_WORLD_ROUTE_IDS.has(careerTab))return careerWorldPage(careerTab);
 return careerWorldBaseCareer();
};

/* ENCORE 0.9 — creative studio identity layer.
   A deeper creative brief plus song identity. Designed to feel like making a record, not filling out a web form. */
const CREATIVE_MOODS=['Reflective','Hungry','Romantic','Defiant','Celebratory','Dark','Hopeful','Nostalgic'];
const CREATIVE_THEMES=['Personal story','Love & relationships','Ambition','Loss & recovery','Nightlife','Social commentary','Victory lap','Escapism'];
const CREATIVE_TEMPOS=['Slow burn','Mid-tempo','Up-tempo'];
const CREATIVE_INTENTS=['Art first','Balanced','Hit-minded'];
const CREATIVE_TEXTURES=['Raw & intimate','Warm & soulful','Clean & modern','Dark & atmospheric','Live & organic','Left-field'];
const CREATIVE_HOOKS=['Verse-driven','Big chorus','Melodic refrain','Minimal hook','No obvious hook'];

function ensureStudioIdeaSchema(idea=s.studioIdea){
 const current=idea&&typeof idea==='object'?idea:{};
 return {
  title:typeof current.title==='string'?current.title:'',
  mood:typeof current.mood==='string'?current.mood:'',
  package:typeof current.package==='string'?current.package:'',
  ...current
 };
}

function setCreativeDirection(key,value){
 s.studioIdea={...ensureStudioIdeaSchema(),[key]:value};
}

function creativeProfile(d){
 const p=d?.creative||{}, brief=d?.sessionPlan?.brief||p.brief||'story', intent=p.intent||'Balanced', texture=p.texture||'Warm & soulful', hook=p.hook||'Melodic refrain';
 let writing=level('writing'), recording=level('recording'), producing=level('producing'), charisma=level('charisma'), market=level('marketability'), viral=level('viralAbility');
 let depth=42+writing*.42+(brief==='story'?10:brief==='experiment'?5:-3);
 let production=40+producing*.44+(d?.productionBonus||0)*1.5;
 let performance=40+recording*.34+charisma*.18;
 let catchiness=40+market*.22+viral*.18+(brief==='anthem'?10:0)+(intent==='Hit-minded'?8:0);
 let originality=43+writing*.18+producing*.2+(brief==='experiment'?16:0)+(intent==='Art first'?6:0);
 let commercial=38+market*.34+viral*.2+(intent==='Hit-minded'?14:intent==='Art first'?-8:3)+(brief==='anthem'?7:0);
 if(texture==='Raw & intimate'){depth+=4;performance+=3;production-=2}
 if(texture==='Clean & modern'){production+=5;commercial+=3;originality-=2}
 if(texture==='Dark & atmospheric'){originality+=4;production+=3;commercial-=1}
 if(texture==='Live & organic'){performance+=5;originality+=2;commercial-=2}
 if(texture==='Left-field'){originality+=9;commercial-=5}
 if(hook==='Big chorus'){catchiness+=7;commercial+=5}
 if(hook==='Melodic refrain'){catchiness+=4;commercial+=2}
 if(hook==='Verse-driven'){depth+=4;catchiness-=2}
 if(hook==='Minimal hook'){originality+=3;commercial-=2}
 if(hook==='No obvious hook'){originality+=6;depth+=3;commercial-=6}
 const mood=p.mood||d?.mood||'';
 if(['Dark','Reflective','Nostalgic'].includes(mood)){depth+=4;commercial-=2}
 if(['Celebratory','Hopeful'].includes(mood)){catchiness+=3;commercial+=2}
 const values={depth,production,performance,catchiness,originality,commercial};
 Object.keys(values).forEach(k=>values[k]=Math.round(clamp(values[k])));
 return values;
}

function creativeIdentityMarkup(d){
 const x=creativeProfile(d), rows=[['Lyrical depth',x.depth],['Production',x.production],['Performance',x.performance],['Catchiness',x.catchiness],['Originality',x.originality],['Commercial appeal',x.commercial]];
 const p=d.creative||{};
 return `<section class="card creative-identity"><div class="studio-tape-label"><span>ENCORE STUDIOS</span><small>WORKING MASTER</small></div><div class="eyebrow">SONG IDENTITY</div><h3>${esc(d.title)}</h3><p class="fine">Theme: ${esc(p.theme||'Personal story')} · ${esc(p.tempo||'Mid-tempo')} · ${esc(p.texture||'Warm & soulful')}</p><p class="fine">This describes the record you are shaping. It does not guarantee chart success.</p><div class="identity-grid">${rows.map(([n,v])=>`<div><span>${n}</span><strong>${v}</strong><i style="--score:${v}%"></i></div>`).join('')}</div></section>`;
}

function creativeDirectionMarkup(){
 const idea=ensureStudioIdeaSchema();
 const options=(items,current)=>items.map(x=>`<option ${x===current?'selected':''}>${x}</option>`).join('');
 return `<section class="card studio-creative-brief"><div class="studio-tape-label"><span>SESSION 01</span><small>CREATIVE BRIEF</small></div><div class="eyebrow">CREATIVE DIRECTION</div><h3>Decide what this record is trying to be.</h3><p class="fine">There is no universally correct combination. Your choices trade depth, originality, accessibility and commercial upside against each other.</p><div class="creative-grid">
 <label>Theme<select onchange="setCreativeDirection('theme',this.value)">${options(CREATIVE_THEMES,idea.theme||'Personal story')}</select></label>
 <label>Tempo<select onchange="setCreativeDirection('tempo',this.value)">${options(CREATIVE_TEMPOS,idea.tempo||'Mid-tempo')}</select></label>
 <label>Intent<select onchange="setCreativeDirection('intent',this.value)">${options(CREATIVE_INTENTS,idea.intent||'Balanced')}</select></label>
 <label>Texture<select onchange="setCreativeDirection('texture',this.value)">${options(CREATIVE_TEXTURES,idea.texture||'Warm & soulful')}</select></label>
 <label>Hook approach<select onchange="setCreativeDirection('hook',this.value)">${options(CREATIVE_HOOKS,idea.hook||'Melodic refrain')}</select></label>
 </div></section>`;
}

