const V100_settleIndustryCompetitionOld=settleIndustryLife;
settleIndustryLife=function(){
 const result=V100_settleIndustryCompetitionOld();V100_generateInbound();
 const c=V100_labelCompetition();
 for(const o of c.inbound)if(o.status==='open'&&o.expires<s.week)o.status='expired';
 for(const k of Object.keys(c.bids))if(c.bids[k].expires<s.week&&c.bids[k].status==='active')c.bids[k].status='expired';
 return result;
};

/* ENCORE 1.0 Touring 2.1: venue identity, promoter confidence and city availability. */
const V100_VENUE_CLASSES={
 4:{className:'DIY / Bar',crew:.55,production:.45,security:.45,logistics:.55,prestige:4,risk:.9,access:0,availability:1},
 0:{className:'Small Club',crew:.7,production:.65,security:.55,logistics:.65,prestige:8,risk:.92,access:0,availability:1},
 5:{className:'Large Club',crew:.82,production:.78,security:.65,logistics:.75,prestige:13,risk:.95,access:5,availability:.98},
 1:{className:'Small Theater',crew:.95,production:.95,security:.78,logistics:.9,prestige:20,risk:1,access:12,availability:.94},
 6:{className:'Music Hall',crew:1.05,production:1.08,security:.88,logistics:1,prestige:28,risk:1.03,access:18,availability:.9},
 7:{className:'Amphitheater',crew:1.16,production:1.18,security:1.02,logistics:1.15,prestige:38,risk:1.12,access:28,availability:.78},
 8:{className:'Small Arena',crew:1.28,production:1.35,security:1.2,logistics:1.3,prestige:48,risk:1.08,access:36,availability:.72},
 2:{className:'Major Arena',crew:1.45,production:1.55,security:1.38,logistics:1.5,prestige:60,risk:1.1,access:48,availability:.65},
 9:{className:'Small Stadium',crew:1.7,production:1.9,security:1.65,logistics:1.8,prestige:72,risk:1.18,access:62,availability:.5},
 3:{className:'Major Stadium',crew:1.95,production:2.2,security:1.9,logistics:2.1,prestige:84,risk:1.22,access:76,availability:.38},
 10:{className:'Major Stadium+',crew:2.15,production:2.5,security:2.1,logistics:2.35,prestige:91,risk:1.28,access:86,availability:.3},
 11:{className:'Mega Stadium',crew:2.5,production:3,security:2.45,logistics:2.75,prestige:100,risk:1.35,access:94,availability:.18}
};
function V100_venueProfile(index){return V100_VENUE_CLASSES[index]||V100_VENUE_CLASSES[0]}
function V100_promoterConfidence(r){
 const p=V100_venueProfile(r.venue),m=careerWorldMarket(r.city),w=s.careerWorld||{};
 const regional=Math.min(30,Math.log10(1+Math.max(0,m.fans||0))*5),career=Math.min(28,(w.tourDemand||0)*.22),recognition=Math.min(22,(w.recognition||0)*.22),history=Math.min(14,(s.careerRecords?.tours?.length||0)*2),loyalty=Number.isFinite(Number(m.loyalty))?Number(m.loyalty):50,relation=Math.max(-8,Math.min(8,(loyalty-50)*.16)),scalePenalty=p.access*.45;
 /* Access is a difficulty curve, not a second 0–100 score to subtract outright. The old subtraction made Mega Stadium mathematically impossible even for a maxed global career. */
 return Math.round(clamp(regional+career+recognition+history+relation-scalePenalty,0,100));
}
function V100_venueAvailable(r){
 const p=V100_venueProfile(r.venue),confidence=V100_promoterConfidence(r),m=careerWorldMarket(r.city),heat=(m.sceneHeat??50)/100;
 if(r.venue===11&&confidence<22)return {available:false,confidence,reason:'Mega-stadium promoters will not currently underwrite this booking. Build tour demand, recognition and regional audience first.'};
 if(p.access>=62&&confidence<10)return {available:false,confidence,reason:'Local promoters will not currently approve this stadium-scale booking.'};
 const citySupply=clamp(p.availability+heat*.18,0,1);return {available:true,confidence,reason:confidence>=55?'Promoters view this as a strong booking.':confidence>=25?'Promoters see meaningful risk but will book it.':'Promoters consider this a speculative booking. You carry the downside.',citySupply};
}
function V100_venueIdentity(index){
 const p=V100_venueProfile(index),v=liveVenues[index];return `${p.className} · ${fmt(v.seats)} seats · prestige ${p.prestige}/100 · promoter threshold ${p.access}/100`;
}
const V100_tourStopEstimateOld=tourStopEstimate;
tourStopEstimate=function(r,route=tourRoute()){
 const n=V100_tourStopEstimateOld(r,route),p=V100_venueProfile(r.venue),booking=V100_venueAvailable(r),v=liveVenues[r.venue];
 const baseCrew=n.crew,baseProduction=n.production,baseSecurity=n.security,baseTravel=n.travel,baseLodging=n.lodging;
 n.crew=cents(baseCrew*p.crew);n.production=cents(baseProduction*p.production);n.security=cents(baseSecurity*p.security);n.travel=cents(baseTravel*p.logistics);n.lodging=cents(baseLodging*(.8+p.logistics*.2));
 n.fixed=cents(n.crew+n.production+n.security+n.travel+n.lodging+n.openerFee);n.cost=cents(n.fixed+n.variable);n.net=cents(n.gross-n.cost);
 const scale=Math.log10(Math.max(10,v.seats))/5,underwrite=(100-booking.confidence)/100;
 n.incidentRisk=clamp(n.incidentRisk*p.risk+scale*.018+underwrite*.025,.005,.32);n.promoterConfidence=booking.confidence;n.bookingReason=booking.reason;n.venuePrestige=p.prestige;n.venueClass=p.className;n.citySupply=booking.citySupply??0;n.available=booking.available;
 n.overreach=n.overreach||booking.confidence<20;return n;
};
function V100_venueForecast(r,route=tourRoute()){
 const n=tourStopEstimate(r,route);return `<section class="card"><span class="eyebrow">TOURING 2.1 · VENUE REALITY</span><h3>${esc(V100_venueIdentity(r.venue))}</h3>${profileRows([['Promoter confidence',n.promoterConfidence+'/100'],['Venue prestige',n.venuePrestige+'/100'],['Projected sell-through',Math.round(n.tickets/Math.max(1,n.capacity)*100)+'%'],['Incident exposure',Math.round(n.incidentRisk*1000)/10+'%'],['Crew',money(n.crew)],['Production',money(n.production)],['Security',money(n.security)],['Travel / logistics',money(n.travel)]])}<p>${esc(n.bookingReason)}</p></section>`;
}
const V100_editTourStopOld=editTourStop;
editTourStop=function(id=null){V100_editTourStopOld(id);const route=tourRoute(),r=route.find(x=>x.id===id);if(id!==null&&r&&$('modal')?.open)$('modal').innerHTML+=V100_venueForecast(r,route)};
const V100_saveTourStopOld=saveTourStop;
saveTourStop=function(e,id=null){
 const f=new FormData(e.target),r={id:id??s.touring.nextStop,city:String(f.get('city')),week:Number(f.get('week')),venue:Number(f.get('venue')),price:Number(f.get('price')),vip:Number(f.get('vip')),production:Number(f.get('production')),security:Number(f.get('security')),opener:f.get('opener')===''||f.get('opener')===null?null:Number(f.get('opener')),status:'scheduled'},booking=V100_venueAvailable(r),activeEdit=id!==null&&s.liveTour&&!s.liveTour.cancelled&&!s.liveTour.finished;
 /* Active-tour edits must still pass through the legacy upgrade confirmation/payment flow. Promoter gating applies to new draft bookings; it must not silently bypass a paid-tour confirmation path. */
 if(!booking.available&&!activeEdit){e.preventDefault();toast(booking.reason);return}
 if(!booking.available&&activeEdit)r.promoterWarning=booking.reason;
 return V100_saveTourStopOld(e,id)
};
const V100_tourRouteCardsOld=tourRouteCards;
tourRouteCards=function(route){return V100_tourRouteCardsOld(route).replace(/<section class="card"><span class="eyebrow">WEEK ([\s\S]*?)<\/section>/g,m=>m)};
const V100_tourPageOld=tourPage;
tourPage=function(){return V100_tourPageOld().replace('Regional fans, recent streams, local loyalty, city heat, ticket resistance and repeat visits shape demand.','Regional fans, recent streams, local loyalty, city heat, ticket resistance and repeat visits shape demand. Venue class now also changes promoter confidence, crew, production, security, logistics, prestige and incident exposure.')};

/* ENCORE 1.0 Career Parity: one season vocabulary and consequence model for player + NPC careers. */
const V100_CAREER_SEASONS=['Drought','Cooling','Stable','Rising','Hot','Peak','Breakout','Comeback','Legacy'];
function V100_seasonBand(score,{early=false,breakout=false,legacy=false,wasCold=false,momentum=score}={}){
 if(wasCold&&score>=55&&momentum>=52)return 'Comeback';
 if(early&&breakout&&score>=66)return 'Breakout';
 if(legacy&&score<58)return 'Legacy';
 if(score<25)return 'Drought';if(score<43)return 'Cooling';if(score<58)return 'Stable';if(score<70)return 'Rising';if(score<84)return 'Hot';return 'Peak';
}
function V100_seasonOpportunityFactor(state){return {Drought:.68,Cooling:.84,Stable:1,Rising:1.08,Hot:1.18,Peak:1.28,Breakout:1.22,Comeback:1.16,Legacy:.88}[state]||1}
function V100_seasonAudienceFactor(state){return {Drought:.78,Cooling:.9,Stable:1,Rising:1.05,Hot:1.1,Peak:1.14,Breakout:1.12,Comeback:1.09,Legacy:.94}[state]||1}
function V100_qualityDimensions(q,commercial=null){
 q=clamp(Number(q)||50);const appeal=clamp(commercial??q*.72+rand(-12,16)),artistic=clamp(q*.88+rand(-9,12)),audience=clamp(q*.55+appeal*.45+rand(-8,8)),longevity=clamp(q*.48+artistic*.32+audience*.2);
 return {technical:Math.round(q),commercial:Math.round(appeal),artistic:Math.round(artistic),audience:Math.round(audience),longevity:Math.round(longevity)};
}
function V100_playerSeason(){return migrateCareerWorld().state||'Stable'}
function V100_aiSeasonScore(a){
 const c=a.aiCareer||{},peak=Math.max(1,c.peakFans||a.fans||1),ratio=clamp((a.fans||0)/peak*100),weekly=Math.min(100,Math.log10(1+(a.weekly||0))*12),latest=(a.catalog||[]).slice(-4),release=latest.length?latest.reduce((n,x)=>n+clamp((x.factor||1)*50),0)/latest.length:45,activity=s.week-(latest.at(-1)?.week??0)<26?65:30;
 return clamp(ratio*.28+weekly*.31+release*.25+activity*.16);
}
function V100_aiSeason(a){
 const c=a.aiCareer||{},score=V100_aiSeasonScore(a),age=aiCareerAge(a,c),latest=(a.catalog||[]).slice(-6),breakout=latest.some(x=>(x.factor||0)>=1.65),wasCold=['Drought','Cooling'].includes(c.season),legacy=c.status==='retired'||(age>=520&&s.week-(latest.at(-1)?.week??0)>26&&score<58);
 return V100_seasonBand(score,{early:age<156,breakout,legacy,wasCold,momentum:score});
}
function V100_syncAiSeason(a){
 const c=a.aiCareer;if(!c)return;const prior=c.season||'Stable',next=V100_aiSeason(a);c.seasonScore=Math.round(V100_aiSeasonScore(a));c.season=next;c.seasonSince??=s.week;c.seasonHistory??=[];
 if(next!==prior&&s.week-c.seasonSince>=4){c.seasonHistory.push({week:s.week,from:prior,to:next,score:c.seasonScore});c.seasonHistory=c.seasonHistory.slice(-60);c.seasonSince=s.week;if(['Breakout','Comeback','Peak'].includes(next)&&s.week-(c.lastHeadlineWeek||-999)>=13)aiHeadline(a,next+' season',a.name+' has moved from '+prior.toLowerCase()+' into '+next.toLowerCase()+'.',next==='Peak'||next==='Breakout'?'up':'news')}
}
const V100_aiReleaseStageLiftOld=aiReleaseStageLift;
aiReleaseStageLift=function(stage){
 const artist=s.world.find(a=>a.aiCareer?.stage===stage&&a.aiCareer?.status!=='retired'),season=artist?.aiCareer?.season;
 return V100_aiReleaseStageLiftOld(stage)*(season?V100_seasonAudienceFactor(season):1);
};
const V100_aiAfterReleaseOld=aiAfterRelease;
aiAfterRelease=function(a,newItems){
 V100_syncAiSeason(a);const season=V100_seasonAudienceFactor(a.aiCareer.season);for(const x of newItems){x.qualityDimensions=V100_qualityDimensions(clamp((a.skill||50)+(x.factor||1)*12+rand(-14,10)));x.careerSeason=a.aiCareer.season}
 V100_aiAfterReleaseOld(a,newItems);for(const x of newItems){x.streams=Math.max(1,Math.round(x.streams*season));x.total=Math.max(x.streams,Math.round(x.total*season));x.careerSeason=a.aiCareer.season}a.weekly=a.catalog.reduce((n,x)=>n+(x.streams||0),0);V100_syncAiSeason(a);
};
const V100_aiSettleLifecycleOld=aiSettleLifecycle;
aiSettleLifecycle=function(){const z=V100_aiSettleLifecycleOld();for(const a of s.world)V100_syncAiSeason(a);return z};
function V100_playerOpportunityContext(){const w=migrateCareerWorld(),state=w.state,factor=V100_seasonOpportunityFactor(state);return {state,factor,summary:state==='Drought'?'Industry demand is soft. Strong music or a smart collaboration can still trigger a comeback.':state==='Cooling'?'Your leverage is slipping; weaker offers and smaller guarantees are more likely.':state==='Peak'?'Industry demand is at its highest, but weak releases can still break the run.':state==='Breakout'?'The industry is reacting quickly to your rise.':state==='Comeback'?'Attention is returning after a cold period.':'Opportunity flow reflects your current career temperature.'}}
const V100_negotiationMetersParityOld=negotiationMeters;
negotiationMeters=function(o){const n=V100_negotiationMetersParityOld(o);if(!n.v100SeasonAdjusted){const x=V100_playerOpportunityContext();n.interest=Math.round(clamp(n.interest+(x.factor-1)*24,0,100));n.leverage=Math.round(clamp(n.leverage+(x.factor-1)*20,0,100));n.v100SeasonAdjusted=x.state}return n};
function V100_careerConsequences(){
 const x=V100_playerOpportunityContext(),w=migrateCareerWorld();return `<section class="card"><span class="eyebrow">CAREER SEASON · ${esc(x.state.toUpperCase())}</span><h3>${Math.round(w.momentum)}/100 momentum · ${Math.round(w.publicInterest)}/100 public interest</h3><p>${esc(x.summary)}</p>${profileRows([['Industry opportunity multiplier',Math.round(x.factor*100)+'%'],['Tour demand',Math.round(w.tourDemand)+'/100'],['Release form',(w.releaseForm??55)+'/100'],['Drought pressure',(w.droughtPressure??0)+'/100']])}<p class="fine">Fame creates a floor, not guaranteed success. Release quality, current consumption, audience response and career temperature still determine what happens next.</p></section>`}
const V100_careerPulseCardParityOld=careerPulseCard;
careerPulseCard=function(){return V100_careerPulseCardParityOld()+V100_careerConsequences()};
const V100_profileParityOld=profile;
profile=function(id){V100_profileParityOld(id);const a=s.world[id],el=$('modal');if(!a?.aiCareer||!el?.open)return;V100_syncAiSeason(a);el.innerHTML+=`<section class="card"><span class="eyebrow">CAREER SEASON · SHARED ENGINE</span>${profileRows([['Current season',a.aiCareer.season],['Career temperature',a.aiCareer.seasonScore+'/100'],['Peak audience',compact(a.aiCareer.peakFans||a.fans)],['Current audience',compact(a.fans)]])}<p class="fine">NPC careers use the same Drought → Cooling → Stable → Rising → Hot → Peak / Breakout / Comeback / Legacy vocabulary as the player.</p></section>`};

/* ENCORE 1.0 sandbox entry hotfix.
   Sandbox data remains isolated behind /sandbox and /api/sandbox/save.
   This only restores a visible route from the normal title screen; it never creates,
   resets, migrates, or overwrites a sandbox save. */
(function(){
 const previousRenderTitle=renderTitle;
 renderTitle=function(){
  previousRenderTitle();
  if(SANDBOX||!titleVisible)return;
  const shell=document.querySelector?.('#title-screen .intro-shell');
  if(!shell||shell.querySelector('[data-sandbox-entry]'))return;
  const footer=shell.querySelector('.intro-footer');
  const button=document.createElement('button');
  button.className='intro-secondary';
  button.dataset.sandboxEntry='true';
  button.textContent='Open Sandbox';
  button.onclick=()=>{globalThis.location.href='/sandbox'};
  if(footer)shell.insertBefore(button,footer);else shell.appendChild(button);
 };
})();

/* ENCORE 1.0.1 — immersive paper contract execution presentation. */
let V101_contractPage=0;
let V101_signatureStrokes=[];
let V101_signaturePointer=null;
let V101_signatureObserver=null;
function V101_contractPartyMark(label){return String(label||'ENCORE').split(/\s+/).map(x=>x[0]).join('').slice(0,3).toUpperCase()}
function V101_contractPagesForArtist(t,label,artistName=s.name){return V100_contractPages(t,label).map(([title,body])=>[title,String(body||'').replaceAll(String(s.name||''),String(artistName||s.name||''))])}
function V101_signaturePoint(e,canvas){const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/Math.max(1,r.width))),y:Math.max(0,Math.min(1,(e.clientY-r.top)/Math.max(1,r.height))),p:Math.max(.15,Math.min(1,Number(e.pressure)||.5))}}
function V101_signaturePayload(){return V101_signatureStrokes.filter(x=>Array.isArray(x)&&x.length).map(stroke=>stroke.map(p=>[Number(p.x.toFixed(4)),Number(p.y.toFixed(4)),Number(p.p.toFixed(2))]))}
function V101_signatureHasInk(){const pts=V101_signatureStrokes.flat().filter(Boolean);if(pts.length<3)return false;const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),span=Math.hypot(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys));return span>=.035}
function V101_signatureStatus(text){const el=$('v101-signature-status');if(el)el.textContent=text|| (V101_signatureHasInk()?'Signature captured':'Draw your signature above')}
function V101_paintSignature(){const canvas=$('v101-signature-pad');if(!canvas?.getContext)return;const r=canvas.getBoundingClientRect(),w=Math.max(280,Math.round(r.width||640)),h=Math.max(150,Math.round(r.height||190)),dpr=Math.min(3,Math.max(1,Number(globalThis.devicePixelRatio)||1)),pw=Math.round(w*dpr),ph=Math.round(h*dpr);if(canvas.width!==pw||canvas.height!==ph){canvas.width=pw;canvas.height=ph}const ctx=canvas.getContext('2d');if(!ctx)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#f4d487';ctx.fillStyle='#f4d487';for(const stroke of V101_signatureStrokes){if(!stroke?.length)continue;if(stroke.length===1){ctx.beginPath();ctx.arc(stroke[0].x*w,stroke[0].y*h,1.5,0,Math.PI*2);ctx.fill();continue}ctx.beginPath();for(let i=0;i<stroke.length;i++){const p=stroke[i],x=p.x*w,y=p.y*h;ctx.lineWidth=2.1+Math.min(1,p.p||.5)*1.4;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke()}V101_signatureStatus()}
function V101_signatureStart(e){if(e.pointerType==='mouse'&&e.button!==0)return;const canvas=$('v101-signature-pad');if(!canvas)return;e.preventDefault();V101_signaturePointer=e.pointerId;canvas.setPointerCapture?.(e.pointerId);V101_signatureStrokes.push([V101_signaturePoint(e,canvas)]);V101_paintSignature()}
function V101_signatureMove(e){if(e.pointerId!==V101_signaturePointer)return;const canvas=$('v101-signature-pad'),stroke=V101_signatureStrokes.at(-1);if(!canvas||!stroke)return;e.preventDefault();const p=V101_signaturePoint(e,canvas),last=stroke.at(-1);if(!last||Math.hypot(p.x-last.x,p.y-last.y)>.0025)stroke.push(p);V101_paintSignature()}
function V101_signatureEnd(e){if(e.pointerId!==V101_signaturePointer)return;e.preventDefault();const canvas=$('v101-signature-pad');canvas?.releasePointerCapture?.(e.pointerId);V101_signaturePointer=null;V101_signatureStatus()}
function V101_clearSignature(){V101_signatureStrokes=[];V101_signaturePointer=null;V101_paintSignature();V101_signatureStatus('Signature cleared — draw again when ready.')}
function V101_wireSignaturePad(){const canvas=$('v101-signature-pad');if(!canvas||canvas.dataset.v101Wired)return;canvas.dataset.v101Wired='1';canvas.addEventListener('pointerdown',V101_signatureStart,{passive:false});canvas.addEventListener('pointermove',V101_signatureMove,{passive:false});canvas.addEventListener('pointerup',V101_signatureEnd,{passive:false});canvas.addEventListener('pointercancel',V101_signatureEnd,{passive:false});V101_signatureObserver?.disconnect?.();if(typeof ResizeObserver==='function'){V101_signatureObserver=new ResizeObserver(()=>V101_paintSignature());V101_signatureObserver.observe(canvas)}V101_paintSignature()}
function V101_signaturePadMarkup(artistName=s.name){return `<div class="legal-signature-field"><div class="legal-signature-field-head"><span>Artist signature</span><button type="button" class="text-button" onclick="V101_clearSignature()">Clear</button></div><canvas id="v101-signature-pad" class="legal-signature-pad" width="640" height="190" aria-label="Draw your signature with a finger or stylus"></canvas><div class="legal-signature-caption"><strong>${esc(artistName)}</strong><small id="v101-signature-status">Draw your signature above</small></div></div>`}
function V101_contractPaper(t,label,page=0,artistName=s.name){const pages=V101_contractPagesForArtist(t,label,artistName),review=V100_attorneyReview(t),c=V100_contractClauses(t),i=Math.max(0,Math.min(pages.length-1,page)),entry=pages[i],material=[2,3,4,5].includes(i),warnings=review.warnings||[];return `<div class="legal-desk"><div class="legal-folder-tab">${esc(label)} · LEGAL AFFAIRS</div><article class="legal-sheet ${material&&warnings.length?'legal-sheet-flagged':''}"><header class="legal-letterhead"><div class="legal-seal">${esc(V101_contractPartyMark(label))}</div><div><strong>${esc(label)}</strong><small>RECORDING & ENTERTAINMENT AGREEMENT</small></div><span>CONFIDENTIAL</span></header><div class="legal-rule"></div><div class="legal-doc-meta"><span>AGREEMENT NO. ${String(s.week).padStart(4,'0')}-${String(t.weeks||1).padStart(3,'0')}</span><span>PAGE ${i+1} OF ${pages.length}</span></div><h2>${esc(entry[0].replace(/^\d+\s*·\s*/,''))}</h2><p class="legal-recital">This Agreement is entered into by and between <b>${esc(label)}</b> (the “Company”) and <b>${esc(artistName)}</b> (the “Artist”). The parties agree as follows:</p><section class="legal-clause"><span>${String(i+1).padStart(2,'0')}.</span><p>${esc(entry[1])}</p></section>${i===1?`<div class="legal-terms-grid"><div><small>ADVANCE</small><b>${money(t.advance||0)}</b></div><div><small>ARTIST SHARE</small><b>${((1-Number(t.share||0))*100).toFixed(1)}%</b></div><div><small>COMPANY SHARE</small><b>${(Number(t.share||0)*100).toFixed(1)}%</b></div></div>`:''}${i===4?`<div class="legal-material-box"><b>MATERIAL TERMS</b><p>${c.recoupment?'Recoupable advance':'Non-recoupable advance'} · ${c.options||0} company option${c.options===1?'':'s'} · ${c.autoExtension?'Automatic extension':'No automatic extension'} · ${c.crossCollateral?'Cross-collateralized':'Not cross-collateralized'}</p></div>`:''}${material&&warnings.length?`<aside class="legal-counsel-note"><b>${review.attorney?esc(review.attorney.name):'COUNSEL NOTE'}</b><span>${review.attorney?'Attorney review · '+review.confidence+'/100':'Review recommended'}</span><p>${esc(warnings[Math.min(warnings.length-1,Math.max(0,i-2))]?.text||review.recommendation)}</p></aside>`:''}${i===pages.length-1?`<div class="legal-signatures"><div><span>ARTIST</span><div class="signature-line">${esc(artistName)}</div><small>Drawn signature required below to execute</small></div><div><span>COMPANY</span><div class="signature-line legal-counter-sign">${esc(label)} Authorized Representative</div><small>Authorized counterparty</small></div></div>`:`<div class="legal-initial-line"><span>ARTIST INITIALS</span><i></i></div>`}<footer><span>ENCORE CONTRACT VAULT · ${esc(String(t.type||'agreement').toUpperCase())}</span><span>${i+1} / ${pages.length}</span></footer></article></div>`}
function V101_renderContractPage(){const host=$('v101-paper-host');if(!host||!globalThis.V101_activeContract)return;host.classList.remove('page-turning');void host.offsetWidth;host.classList.add('page-turning');host.innerHTML=V101_contractPaper(V101_activeContract.terms,V101_activeContract.label,V101_contractPage,V101_activeContract.artistName||s.name);const total=V101_contractPagesForArtist(V101_activeContract.terms,V101_activeContract.label,V101_activeContract.artistName||s.name).length,back=$('v101-paper-back'),next=$('v101-paper-next');if(back)back.disabled=V101_contractPage<=0;if(next){next.disabled=V101_contractPage>=total-1;next.textContent=V101_contractPage>=total-1?'Execution page':'Next page →'}const count=$('v101-paper-count');if(count)count.textContent=`${V101_contractPage+1} of ${total}`}
function V101_turnContract(delta){if(!globalThis.V101_activeContract)return;const total=V101_contractPagesForArtist(V101_activeContract.terms,V101_activeContract.label,V101_activeContract.artistName||s.name).length;V101_contractPage=Math.max(0,Math.min(total-1,V101_contractPage+delta));V101_renderContractPage()}
function V101_clearContractReadingState(){if(typeof document!=='undefined'){document.documentElement?.classList?.remove?.('contract-reading');document.body?.classList?.remove?.('contract-reading')}V101_signatureObserver?.disconnect?.();V101_signatureObserver=null;V101_signaturePointer=null;globalThis.V101_activeContract=null}
function V101_closeContract(){if(typeof document==='undefined'){V101_clearContractReadingState();return}const shell=document.querySelector?.('#v101-contract-shell');if(!shell?.classList){V101_clearContractReadingState();return}shell.classList.add('contract-exit');setTimeout(()=>{shell.remove?.();V101_clearContractReadingState()},260)}
function V101_canRenderContract(){return typeof document!=='undefined'&&document.documentElement?.classList&&document.body?.classList&&typeof document.createElement==='function'&&typeof document.body.appendChild==='function'&&typeof document.querySelector==='function'}
function V101_commitContractExecution(id,initials){const o=s.labelBusiness?.offers?.find(x=>x.id===id&&!x.used&&x.expires>=s.week);if(!o)return false;const cleanInitials=String(initials||'').trim();if(!cleanInitials||cleanInitials.length>6){toast('Initial the material-terms page before signing.');return false}if(!V101_signatureHasInk()){toast('Draw your signature in the signature pad before signing.');return false}const proposal=ensureLabelProposal(o),t={...proposal,rights:V090_contractRights(proposal.type,proposal.rights)},label=labelDeals[o.label].name,signature={kind:'drawn',format:'normalized-strokes-v1',signer:String(s.name||''),strokes:V101_signaturePayload()};const beforeContract=s.expansion?.contract,beforeUsed=!!o.used,result=V101_signNegotiatedOfferOld(id,true),executed=(!beforeUsed&&!!o.used)||s.expansion?.contract!==beforeContract||result===true;if(!executed)return false;t.initials=cleanInitials;V100_storeContract(t,label);const stored=V100_contractVault()[0];if(stored){stored.initials=cleanInitials;stored.signature=signature}queueSave?.();return true}
function V101_executeContract(e,id){e.preventDefault();const initials=String(new FormData(e.target).get('initials')||'');if(V101_commitContractExecution(id,initials))V101_closeContract()}
function V101_mountContractRoom({id,label,terms,artistName=s.name,mode='artist',buyout=0}){if(!V101_canRenderContract())return false;globalThis.V101_activeContract={id,label,terms,artistName,mode,buyout};V101_contractPage=0;V101_signatureStrokes=[];V101_signaturePointer=null;document.documentElement.classList.add('contract-reading');document.body.classList.add('contract-reading');document.querySelector('#v101-contract-shell')?.remove?.();try{$('modal')?.close?.()}catch{}const pages=V101_contractPagesForArtist(terms,label,artistName).length,roster=mode==='roster';const execution=roster?`<section class="contract-room-advisory"><h3>Final signing cost</h3>${profileRows([['Advance',money(terms.advance||0)],['Current-label buyout',money(buyout||0)],['Your label share',Math.round(Number(terms.share||0)*100)+'%'],['Artist share',Math.round((1-Number(terms.share||0))*100)+'%'],['Term',(terms.weeks||0)+' weeks'],['Rights',terms.type==='360'?'Recording + live + merchandise':terms.type==='distribution'?'Distribution':'Recording']])}<p class="fine">Signing uses 10 energy and pays the advance plus any buyout immediately.</p><button class="primary" type="button" onclick="V101_executeRosterContract()">Execute & sign ${esc(artistName)}</button></section>`:`<section class="contract-room-advisory"><h3>Deal summary & counsel</h3>${V100_contractRightsSummary(terms)}${V100_attorneyPanel(terms)}</section><form class="form legal-execution-form" onsubmit="V101_executeContract(event,'${id}')"><span class="eyebrow">EXECUTION</span><h3>Execute this agreement</h3><p>Review all ${pages} pages. Initial the material terms, then draw your signature with your finger or stylus.</p><label>Artist initials<input name="initials" maxlength="6" autocomplete="off" placeholder="Initials" required></label>${V101_signaturePadMarkup(artistName)}<p class="fine">The drawn signature is saved with this agreement in your Contract Vault. This agreement completes immediately when executed and does not transfer ownership of your existing masters, publishing or catalog.</p><button class="primary">Sign & execute agreement</button></form>`;const shell=document.createElement('section');shell.id='v101-contract-shell';shell.className='contract-reading-room';shell.innerHTML=`<div class="contract-room-ambient"></div><div class="contract-room"><header class="contract-room-header"><div><span class="contract-room-kicker">PRIVATE LEGAL REVIEW</span><h1>${esc(label)}</h1><p>${roster?'Artist Recording Agreement':'Recording & Entertainment Agreement'}</p></div><button class="contract-room-close" type="button" onclick="V101_closeContract()" aria-label="Return to ENCORE"><span>×</span><small>RETURN TO ENCORE</small></button></header><main class="paper-contract-viewer"><div class="contract-folder-intro"><span>${esc(V101_contractPartyMark(label))}</span><div><small>${roster?'LABEL COPY':'ARTIST COPY'}</small><strong>${esc(artistName)}</strong></div><em>CONFIDENTIAL</em></div><div id="v101-paper-host"></div><div class="paper-pagination"><button id="v101-paper-back" class="contract-paper-button" type="button" onclick="V101_turnContract(-1)">← Previous</button><strong id="v101-paper-count"></strong><button id="v101-paper-next" class="contract-paper-button" type="button" onclick="V101_turnContract(1)">Next page →</button></div>${execution}</main></div>`;document.body.appendChild(shell);const enter=()=>{shell.classList.add('contract-entered');V101_renderContractPage();if(!roster)V101_wireSignaturePad()};if(typeof requestAnimationFrame==='function')requestAnimationFrame(enter);else enter();return true}
function V101_openContract(id){const o=s.labelBusiness?.offers?.find(x=>x.id===id&&!x.used&&x.expires>=s.week);if(!o)return;const t=ensureLabelProposal(o),label=labelDeals[o.label].name;return V101_mountContractRoom({id,label,terms:t,artistName:s.name,mode:'artist'})}
function V101_openRosterContract(){const t=pendingRosterOffer,a=t?s.world[t.artist]:null;if(!t||!a||!s.labelBusiness?.company)return;const terms={...t};return V101_mountContractRoom({id:'roster-'+t.artist,label:s.labelBusiness.company.name,terms,artistName:a.name,mode:'roster',buyout:t.buyout||npcBuyout(t.artist)})}
function V101_executeRosterContract(){const active=globalThis.V101_activeContract;if(!active||active.mode!=='roster'||!pendingRosterOffer)return;confirmRosterOffer();V101_closeContract()}
const V101_signNegotiatedOfferOld=signNegotiatedOffer;
signNegotiatedOffer=function(id,confirmed=false){if(confirmed){const result=V101_signNegotiatedOfferOld(id,true);V101_closeContract();return result}return V101_openContract(id)};
/* v100 roster forms call V100_reviewRosterOffer directly, not reviewRosterOffer. Intercept the function actually used by the live form. */
const V101_V100_reviewRosterOfferOld=V100_reviewRosterOffer;
V100_reviewRosterOffer=function(e,id){const result=V101_V100_reviewRosterOfferOld(e,id);if(pendingRosterOffer?.artist===id&&V100_rosterNegotiation(id)?.status==='active')V101_openRosterContract();return result};
reviewRosterOffer=V100_reviewRosterOffer;

/* Bridge legacy ENCORE negotiation helpers to the shared renderer-independent engine. */
(function(){
'use strict';
if(!globalThis.ENCORE_ROSTER_NEGOTIATION)return;
const engine=globalThis.ENCORE_ROSTER_NEGOTIATION;
rosterTerms=function(a,type,share,weeks){return engine.terms(s,a.id,type,share,weeks)};
V100_rosterNegotiation=function(id){return engine.ensure(s,id)};
V100_rosterOfferPressure=function(a,t,r,n){return engine.pressure(s,a.id,t,r,n)};
V100_biddingWar=function(id){return engine.biddingWar(s,id,Math.random)};
npcBuyout=function(id){return engine.buyout(s,id)};
})();

/* ENCORE 1.0.2 — hard gate player-label roster execution behind the paper contract room. */
const V102_confirmRosterOfferOld=confirmRosterOffer;
confirmRosterOffer=function(){
 const t=pendingRosterOffer;
 const active=globalThis.V101_activeContract;
 if(t&&(!active||active.mode!=='roster'||active.id!=='roster-'+t.artist)){
  if(typeof V101_openRosterContract==='function'&&V101_openRosterContract()!==false)return;
 }
 return V102_confirmRosterOfferOld();
};

/* ENCORE 1.0.2 — dedicated player-label negotiation environment. */
function V102_canRender(){return typeof document!=='undefined'&&document.body&&typeof document.createElement==='function'}
function V102_clearNegotiationState(){if(typeof document!=='undefined'){document.documentElement?.classList?.remove?.('negotiation-reading');document.body?.classList?.remove?.('negotiation-reading')}globalThis.V102_activeNegotiation=null}
function V102_closeNegotiation(){if(typeof document==='undefined'){V102_clearNegotiationState();return}const shell=document.querySelector?.('#v102-negotiation-shell');if(!shell){V102_clearNegotiationState();return}shell.classList.add('negotiation-exit');setTimeout(()=>{shell.remove?.();V102_clearNegotiationState()},240)}
function V102_terms(id){const a=s.world[id];return {type:'record',share:.1,weeks:26,advance:rosterTerms(a,'record',.1,26).minimum}}
function V102_renderNegotiation(id,terms){if(!V102_canRender())return false;const a=s.world[id],n=V100_rosterNegotiation(id);if(!a||!n||!s.labelBusiness?.company)return false;globalThis.V102_activeNegotiation={artist:id,terms:{...terms}};document.querySelector?.('#v102-negotiation-shell')?.remove?.();try{$('modal')?.close?.()}catch{}document.documentElement.classList.add('negotiation-reading');document.body.classList.add('negotiation-reading');const shell=document.createElement('section');shell.id='v102-negotiation-shell';shell.className='negotiation-room-shell';shell.innerHTML=`<div class="negotiation-room-bg"></div><div class="negotiation-room"><header class="negotiation-room-header"><div><span class="negotiation-room-kicker">PRIVATE NEGOTIATION · ROUND ${Math.max(1,(n.rounds||0)+1)}</span><h1>${esc(a.name)}</h1><p>${esc(s.labelBusiness.company.name)} · Artist acquisition meeting</p></div><button class="negotiation-room-close" type="button" onclick="V102_closeNegotiation()" aria-label="Leave negotiations"><span>×</span><small>LEAVE TALKS</small></button></header><main class="negotiation-table"><section class="negotiation-counterparty"><div class="negotiation-avatar">${esc((a.name||'?').split(/\s+/).map(x=>x[0]).join('').slice(0,2))}</div><div><small>ACROSS THE TABLE</small><h2>${esc(a.name)}</h2><p>${esc(n.response||'The artist is willing to hear your offer.')}</p></div></section><section class="negotiation-room-meters">${negotiationBar('Artist interest',n.interest,'How strongly the artist currently wants to join your company.')}${negotiationBar('Artist patience',n.patience,'How much more bargaining they will tolerate before ending talks.')}${negotiationBar('Your leverage',n.leverage,'Your label reputation, staff support and relationship advantage.')}</section><section class="negotiation-offer-sheet"><div class="negotiation-offer-heading"><span class="negotiation-room-kicker">YOUR PROPOSAL</span><h2>Put the deal on the table.</h2><p>Broader rights, a larger label share and longer control increase what the artist expects in return.</p></div><form class="form" oninput="previewRosterTerms(this,${id})" onsubmit="V102_submitRosterOffer(event,${id})">${contractFields(terms)}<div class="negotiation-preview" id="roster-preview">Requested advance ${money(terms.advance)} · Reputation ${s.reputation}/${rosterTerms(a,terms.type,terms.share,terms.weeks).reputation}</div><div class="negotiation-room-actions"><button class="secondary" type="button" onclick="V102_closeNegotiation()">Walk away</button><button class="primary">Present offer</button></div></form></section></main></div>`;document.body.appendChild(shell);const enter=()=>shell.classList.add('negotiation-entered');if(typeof requestAnimationFrame==='function')requestAnimationFrame(enter);else enter();return true}
function V102_openRosterNegotiation(id){const a=s.world[id];if(!labelActive()||!s.labelBusiness.company||!a||ownerContracts().some(c=>c.artist===id)||ownerContracts().length>=labelCapacity())return;const n=V100_rosterNegotiation(id);if(n.status==='walked'&&s.week<(n.walkedUntil||0)){toast(a.name+' is not ready to reopen talks yet.');return}if(n.status==='walked'){n.status='active';n.patience=Math.max(35,n.patience);n.interest=Math.max(30,n.interest)}return V102_renderNegotiation(id,V102_terms(id))}
function V102_submitRosterOffer(e,id){e.preventDefault();const a=s.world[id],n=V100_rosterNegotiation(id);if(!a||!n||n.status!=='active')return;try{const t=readRosterTerms(e.target),r=rosterTerms(a,t.type,t.share,t.weeks);globalThis.V102_activeNegotiation={artist:id,terms:{...t}};if(a.relation<=-40||s.reputation<r.reputation){n.interest=Math.round(clamp(n.interest-8,0,100));n.response='They are not willing to sign while the relationship or your label reputation is this weak.';render();V102_renderNegotiation(id,t);return}const pressure=V100_rosterOfferPressure(a,t,r,n);n.patience=Math.round(clamp(n.patience-pressure,0,100));n.rounds++;const value=t.advance/Math.max(1,r.minimum),appeal=(value-1)*24+(1-t.share)*8+(t.type==='distribution'?4:t.type==='360'?-5:0);n.interest=Math.round(clamp(n.interest+appeal-pressure*.35,0,100));if(n.patience<=4||n.interest<=7){n.status='walked';n.walkedUntil=s.week+8;n.response='Talks ended. The artist will not reopen negotiations for eight weeks.';V102_closeNegotiation();render();toast(a.name+' walked away from negotiations.');return}if(t.advance<r.minimum||n.interest<34){const ask=Math.max(r.minimum,Math.round(r.minimum*(1+(34-n.interest)*.008)));n.response='Counteroffer: '+money(ask)+' advance for the current rights, split and term. Interest '+n.interest+'/100 · patience '+n.patience+'/100.';render();V102_renderNegotiation(id,t);return}pendingRosterOffer={...t,artist:id,buyout:npcBuyout(id)};n.response='The artist accepted the business terms. Legal is preparing the agreement.';const shell=document.querySelector?.('#v102-negotiation-shell');if(shell)shell.classList.add('negotiation-to-contract');setTimeout(()=>{V102_clearNegotiationState();shell?.remove?.();V101_openRosterContract()},260)}catch(err){toast(err.message)}}
/* Replace the old modal entry point. All existing Start Negotiations buttons call rosterOfferForm. */
rosterOfferForm=V102_openRosterNegotiation;
V100_rosterOfferForm=V102_openRosterNegotiation;

/* Bind legacy ENCORE Studio actions to engine/studio.js.
   Presentation remains legacy here; simulation mutations are shared with UI2. */
scoreSong=function(d){return ENCORE_STUDIO.score(d)};
newSong=function(e){
 e?.preventDefault?.();if(!saveReady||saveConflict||s.draft)return;
 const f=new FormData(e.target),idea=typeof ensureStudioIdeaSchema==='function'?ensureStudioIdeaSchema():s.studioIdea||{};
 try{
  const d=ENCORE_STUDIO.start(s,{
   title:String(f.get('songtitle')||'').trim()||generate('song'),
   mood:String(f.get('mood')||idea.mood||ENCORE_STUDIO.directions[0].id),
   packageIndex:Number(f.get('package')||idea.package||0),
   brief:String(f.get('brief')||idea.brief||'story'),
   creative:{theme:idea.theme,tempo:idea.tempo,intent:idea.intent,texture:idea.texture,hook:idea.hook}
  });
  log('Started writing “'+d.title+'”.');queueSave();render();
 }catch(error){toast(error.message||'The writing session could not start.')}
};
progressSong=function(){
 if(!saveReady||saveConflict)return;
 try{const result=ENCORE_STUDIO.progress(s);log((result.stage==='record'?'Recording':'Mixing')+' complete for “'+result.draft.title+'”.');queueSave();render()}
 catch(error){toast(error.message||'That studio stage could not be completed.')}
};
/* Historical compatibility for old cached controls only. Current song creation
   uses progressSong() and does not present selectable recording/mix sessions. */
performSession=function(id){
 if(!saveReady||saveConflict)return;
 try{const result=id?ENCORE_STUDIO.perform(s,id):ENCORE_STUDIO.progress(s);log((result.stage==='record'?'Recording':'Mixing')+' complete.');queueSave();render()}
 catch(error){toast(error.message||'That studio stage could not be completed.')}
};
finishSong=function(release,confirmed=false){
 const d=s.draft;if(!d||d.steps!==3||!saveReady||saveConflict)return;
 if(release&&!confirmed){modal(`<h2>Publish this single?</h2><p>“${esc(d.title)}” will enter your released catalog. You cannot edit the finished recording afterward. Results arrive when you advance the week.</p><p>$20 · 5 energy</p><div class="controls"><button class="secondary" onclick="$(${JSON.stringify('modal')}).close()">Keep in studio</button><button class="primary" onclick="$(${JSON.stringify('modal')}).close();finishSong(true,true)">Release single</button></div>`);return}
 try{const song=ENCORE_STUDIO.finish(s,{release:!!release});log('“'+song.title+'” '+(release?'is out. Results arrive at the end of this week.':'is ready for your album.'));queueSave();render();toast(release?'Single released. Advance the week for results.':'Finished track saved.')}
 catch(error){toast(error.message||'The master could not be finished.')}
};
releaseShelf=function(id,confirmed=false){
 const x=s.songs.find(x=>x.id===id);if(!x||x.released||!saveReady||saveConflict)return;
 if(!confirmed){modal(`<h2>Release “${esc(x.title)}”?</h2><p>This publishes the finished recording. Pay $20 and 5 energy. Results arrive at week close.</p><button class="primary" onclick="releaseShelf(${JSON.stringify(id)},true)">Publish single</button>`);return}
 try{$('modal').close();const song=ENCORE_STUDIO.releaseShelf(s,id);log('“'+song.title+'” is out.');queueSave();render()}
 catch(error){toast(error.message||'The master could not be released.')}
};

/* ENCORE 1.0.3 — Visual System 2.0: Home command center. */
function V103_homeSignals(){
 const latest=s.songs.filter(x=>x.released).at(-1),w=typeof migrateCareerWorld==='function'?migrateCareerWorld():null,briefings=s.achievements?.briefings?.filter(x=>!x.read&&!x.id.startsWith('cert:')).length||0,priority=typeof V096_priorityRaw==='function'?V096_priorityRaw():[],chart=latest&&typeof chartPosition==='function'?chartPosition(latest):null;
 const signals=[];
 if(priority.length)signals.push({k:priority[0].category||'Opportunity',v:priority[0].title||'New industry opportunity',route:priority[0].route||'Inbox'});
 if(latest)signals.push({k:chart?'Chart movement':'Latest release',v:chart?`${latest.title} is #${chart}`:`${latest.title} · ${compact(latest.total||0)} streams`,route:'Career'});
 if(briefings)signals.push({k:'Career desk',v:`${briefings} unread ${briefings===1?'briefing':'briefings'}`,route:'Inbox'});
 if(w)signals.push({k:'Career state',v:`${w.state} · momentum ${Math.round(w.momentum)}/100`,route:'Career'});
 return signals.slice(0,4)
}
function V103_home(){
 const latest=s.songs.filter(x=>x.released).at(-1),w=typeof migrateCareerWorld==='function'?migrateCareerWorld():null,signals=V103_homeSignals(),tierName=tierNames[tier(s.fans)],identity=s.labelBusiness?.company?`Founder · ${s.labelBusiness.company.name}`:s.expansion?.contract?s.expansion.contract.name:'Independent artist',chart=latest&&typeof chartPosition==='function'?chartPosition(latest):null;
 const chapter=s.draft?{over:'SESSION IN PROGRESS',title:'Finish what you started.',copy:`${s.draft.title} is waiting in the studio.`,action:'Continue session',go:"go('Create')"}:latest?{over:'CURRENT ERA',title:'Your music is moving.',copy:`${latest.title} is in the world. Build the next moment around it.`,action:'Open career',go:"openArtistFile()"}:{over:'CHAPTER ONE',title:'Build the first record.',copy:'Your career is unwritten. Make the first move count.',action:s.started?'Enter studio':'Create artist',go:s.started?"go('Create')":'setup()'};
 return `<section class="v103-home"><header class="v103-mast"><button class="v103-wordmark" onclick="go('Menu')" aria-label="Open menu"><span class="encore-wordmark">ENC<i aria-hidden="true"></i><span class="encore-sr-only">O</span>RE</span><small>${careerDate()}</small></button><div class="v103-mast-status"><button onclick="statDetail('cash')"><small>CASH</small><strong>${money(s.cash)}</strong></button><button onclick="statDetail('energy')"><small>ENERGY</small><strong>${s.energy}<i>/200</i></strong></button></div></header><section class="v103-hero"><img src="${ENCORE_ART.backstage}" alt="" class="v103-hero-art"><div class="v103-hero-shade"></div><button class="v103-identity" onclick="openArtistFile()">${personPhoto('player-'+s.name,s.name)}<span><small>${esc(identity)}</small><strong>${esc(s.name)}</strong><em>${esc(s.genre)} · ${esc(tierName)}</em></span><b>↗</b></button><div class="v103-chapter"><span>${chapter.over}</span><h1>${chapter.title}</h1><p>${esc(chapter.copy)}</p><button class="primary" onclick="${chapter.go}">${chapter.action} <b>→</b></button></div></section><section class="v103-scoreboard" aria-label="Career scoreboard"><button onclick="statDetail('fans')"><span>TRUE FANS</span><strong>${compact(s.fans)}</strong><small>${w?`${Math.round(w.publicInterest)}/100 public interest`:'Career audience'}</small></button><button onclick="openArtistFile()"><span>LIFETIME STREAMS</span><strong>${compact(s.total||0)}</strong><small>${latest?`Latest · ${esc(latest.title)}`:'Catalog begins here'}</small></button><button onclick="careerTab='Profile';go('Career')"><span>CAREER STATE</span><strong>${esc(w?.state||tierName)}</strong><small>${w?`Momentum ${Math.round(w.momentum)}/100`:'Your current tier'}</small></button></section>${latest?`<button class="v103-release" onclick="releaseDetails('songs',${latest.id})"><span class="record-sleeve" aria-hidden="true"><i></i></span><span><small>LATEST RELEASE</small><strong>${esc(latest.title)}</strong><em>${compact(latest.total||0)} lifetime streams${chart?` · #${chart} chart`:''}</em></span><b>↗</b></button>`:''}${encoreNextMove()}<section class="v103-desk"><div class="v103-section-title"><div><span>CAREER DESK</span><h2>What needs your attention.</h2></div><button onclick="openDestination('Inbox')">Inbox →</button></div>${signals.length?`<div class="v103-signal-list">${signals.map(x=>`<button onclick="${x.route==='Career'?"openArtistFile()":`openDestination('${x.route}')`}"><span>${esc(x.k)}</span><strong>${esc(x.v)}</strong><b>→</b></button>`).join('')}</div>`:`<div class="v103-clear"><strong>Nothing urgent.</strong><span>Your desk is clear. Use the week to create, train or build your business.</span></div>`}</section><section class="v103-actions"><button onclick="go('Create')"><span>CREATE</span><strong>Studio</strong></button><button onclick="go('Stats')"><span>DEVELOP</span><strong>Stats</strong></button><button onclick="careerTab='Social';go('Career')"><span>PUBLIC</span><strong>PULSE</strong></button><button onclick="go('BusinessHQ')"><span>EXECUTIVE</span><strong>Business HQ</strong></button></section><details class="v103-utility"><summary>Quick actions & career details</summary><div class="actions"><button class="action" onclick="action('work')">Work a shift · 15 energy · +$180</button><button class="action" onclick="action('gig')">Open mic · 20 energy</button><button class="action" onclick="action('rest')">Rest · +40 energy</button></div>${homeStats()}${betaHomeNotice()}</details></section>`
}
