function V103_artistFile(){
 migrateV095();migrateEmpire();const w=migrateCareerWorld(),released=s.songs.filter(x=>x.released),albums=s.albums,best=released.reduce((b,x)=>!b||x.total>b.total?x:b,null),records=s.careerRecords||{},certs=released.filter(x=>certificationUnits(x,'songs')>=500000).length+albums.filter(x=>certificationUnits(x,'albums')>=500000).length,ones=released.filter(x=>x.peak===1).length+albums.filter(x=>x.peak===1).length,identity=s.labelBusiness?.company?`Founder · ${s.labelBusiness.company.name}`:s.expansion?.contract?s.expansion.contract.name:'Independent artist',wealth=s.cash+(s.empire?.assets||[]).reduce((n,a)=>n+(a.value||0),0)+catalogOwnedValue();
 return `<article class="v103-file"><header class="v103-file-cover"><div class="v103-file-photo">${personPhoto('player-'+s.name,s.name)}</div><div class="v103-file-id"><span>ENCORE / ARTIST DOSSIER · ${careerDate()}</span><h1>${esc(s.name)}</h1><p>${esc(s.genre)} · ${esc(tierNames[tier(s.fans)])} · ${esc(identity)}</p><div class="v103-file-state"><strong>${esc(w.state)}</strong><small>Career state</small><em>${Math.round(w.momentum)}/100 momentum</em></div></div><button onclick="go('Stats')">DEVELOPMENT ↗</button></header><section class="v103-file-ledger">${[['TRUE FANS',compact(s.fans)],['LIFETIME STREAMS',compact(s.total||0)],['#1 RELEASES',ones],['CERTIFIED',certs],['EST. WEALTH',money(wealth)]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</section><section class="v103-file-spread"><div class="v103-file-main"><div class="v103-file-heading"><span>01 / CURRENT ERA</span><h2>${best?esc(best.title):'The first record is still ahead.'}</h2><p>${best?`${compact(best.total||0)} lifetime streams on your biggest record. Your career is currently ${String(w.state).toLowerCase()}, with ${Math.round(w.publicInterest)}/100 public interest.`:'There is no released catalog yet. Your dossier will grow with every release, tour and career decision.'}</p></div><div class="v103-file-rules"><div><span>PUBLIC INTEREST</span><strong>${Math.round(w.publicInterest)}</strong><i style="--p:${w.publicInterest}%"></i></div><div><span>TOUR DEMAND</span><strong>${Math.round(w.tourDemand)}</strong><i style="--p:${w.tourDemand}%"></i></div><div><span>INDUSTRY INFLUENCE</span><strong>${Math.round(w.industryInfluence)}</strong><i style="--p:${w.industryInfluence}%"></i></div></div></div><aside class="v103-file-note"><span>FIELD NOTE</span><h3>Where your career carries weight.</h3><p>Recognition ${Math.round(w.recognition)}/100 · loyalty ${Math.round(w.fanLoyalty)}/100.</p><button onclick="careerTab='Audience';go('Career')">Audience map →</button><button onclick="careerTab='Social';go('Career')">PULSE →</button></aside></section><section class="v103-file-spread v103-catalog"><div><div class="v103-file-heading"><span>02 / CATALOG</span><h2>Records on file.</h2></div><div class="v103-record-list">${released.slice().sort((a,b)=>(b.total||0)-(a.total||0)).slice(0,6).map((x,i)=>`<button onclick="releaseDetails('songs',${x.id})"><b>${String(i+1).padStart(2,'0')}</b><span><strong>${esc(x.title)}</strong><small>${compact(x.total||0)} streams</small></span><em>${x.peak?'PEAK #'+x.peak:'—'}</em></button>`).join('')||'<p>No released records yet.</p>'}</div></div><aside><div class="v103-file-heading"><span>03 / LIVE FILE</span><h2>Stage résumé.</h2></div><dl><dt>Tour runs</dt><dd>${records.tours?.length||0}</dd><dt>Open mics</dt><dd>${records.openMics||0}</dd><dt>Live gross</dt><dd>${money(records.liveGross||0)}</dd><dt>Live profit</dt><dd>${money(records.liveProfit||0)}</dd></dl><button onclick="careerTab='Touring';go('Career')">Touring desk →</button></aside></section><section class="v103-history"><div class="v103-file-heading"><span>04 / ARCHIVE</span><h2>The career trail.</h2></div><ol>${V103_careerTimeline()}</ol><div class="v103-archive-links"><button onclick="careerTab='Certifications';go('Career')">Plaques</button><button onclick="careerTab='Achievements';go('Career')">Achievements</button><button onclick="careerTab='Activity';go('Career')">Full history</button></div></section></article>`
}
artistFilePage=V103_artistFile;

function V103_statRow(k,sub=false){const a=s.development[k],info=developmentInfo[k],need=a.level>=100?0:xpNeeded(a.level),xp=a.level>=100?100:clamp(a.xp/Math.max(1,need)*100);return `<section class="v103-stat-row ${sub?'specialty':''}"><div class="v103-stat-name"><span>${sub?'SPECIALTY':'CORE ABILITY'}</span><h2>${info[0]}</h2><p>${info[1]}</p></div><div class="v103-stat-score"><strong>${a.level}</strong><small>/100</small></div><div class="v103-stat-track"><span>ABILITY · ${difficulty(a.level)}</span><i><b style="width:${a.level}%"></b></i><span>${a.level===100?'MASTERY COMPLETE':`NEXT LEVEL · ${fmt(a.xp)} / ${fmt(need)} XP`}</span><i class="xp"><b style="width:${xp}%"></b></i></div><div class="v103-stat-train">${[[0,5,20],[1,10,40],[2,20,80]].map(([i,cost,gain])=>`<button ${a.level>=100||s.energy<cost?'disabled':''} onclick="trainStat('${k}',${i})"><strong>+${gain}</strong><small>${cost} energy</small></button>`).join('')}<button class="detail" onclick="trainingDetail('${k}')">DETAILS ↗</button></div></section>`}
function V103_training(){const ranked=coreStats.map(k=>({k,level:level(k)})).sort((a,b)=>b.level-a.level),avg=Math.round(ranked.reduce((n,x)=>n+x.level,0)/ranked.length),strong=developmentInfo[ranked[0].k][0],growth=developmentInfo[ranked.at(-1).k][0];return `<article class="v103-development"><header><div><span>ARTIST DEVELOPMENT / ${careerDate()}</span><h1>Development Board</h1><p>Build the abilities that shape the music, the performance and the career around it.</p></div><div class="v103-energy"><span>AVAILABLE ENERGY</span><strong>${s.energy}<small>/200</small></strong></div></header><section class="v103-development-summary"><div><span>CORE AVERAGE</span><strong>${avg}<small>/100</small></strong></div><div><span>STRONGEST</span><strong>${esc(strong)}</strong></div><div><span>GROWTH EDGE</span><strong>${esc(growth)}</strong></div></section><div class="v103-board-label"><span>THE FIVE CORE ABILITIES</span><small>Ability is permanent skill. XP is progress toward the next ability point.</small></div><div class="v103-stat-stack">${coreStats.map(k=>V103_statRow(k)).join('')}</div><section class="v103-specialties"><div class="v103-board-label"><span>MARKETABILITY SPECIALTIES</span><small>These develop independently. They influence performance, touring and discovery without automatically increasing Marketability.</small></div>${['stagePresence','touring','viralAbility'].map(k=>V103_statRow(k,true)).join('')}</section></article>`}
training=V103_training;

/* ENCORE Visual System 2.0 — Studio creative workspace. Presentation only; existing song mechanics remain authoritative. */
function V103_studioIdeaSummary(){const i=ensureStudioIdeaSchema();return [i.theme||'Personal story',i.mood||directions[0].id,i.tempo||'Mid-tempo',i.texture||'Warm & soulful'].filter(Boolean)}
function V103_studio(){
 const legacy=studioV089();
 if(!s.draft){
  const idea=ensureStudioIdeaSchema(),summary=V103_studioIdeaSummary();
  return `<article class="v103-studio"><header class="v103-studio-head"><div><span>ENCORE / STUDIO A · ${careerDate()}</span><h1>Make the record.</h1><p>Start with an idea. Every creative decision changes the identity of the song—not a promise of a hit.</p></div><div class="v103-studio-energy"><span>SESSION ENERGY</span><strong>${s.energy}<small>/200</small></strong></div></header><section class="v103-console"><div class="v103-console-left"><div class="v103-studio-label"><span>NEW SESSION</span><small>CONCEPT TAPE / SIDE A</small></div><div class="v103-title-stage"><span>WORKING TITLE</span><h2>${esc(idea.title||'Untitled')}</h2><p>${summary.map(esc).join(' · ')}</p></div><div class="v103-wave" aria-hidden="true">${Array.from({length:42},(_,i)=>`<i style="--h:${18+((i*17)%62)}%"></i>`).join('')}</div><div class="v103-session-note"><b>01</b><span><strong>Concept</strong><small>Choose the story, sound and ambition before the red light comes on.</small></span></div></div><div class="v103-console-right"><div class="v103-studio-form">${V092_unifiedSongForm()}</div></div></section><footer class="v103-studio-footer"><span>WRITING ${level('writing')}</span><span>RECORDING ${level('recording')}</span><span>PRODUCING ${level('producing')}</span><button onclick="go('Stats')">Development ↗</button></footer></article>`
 }
 const d=s.draft,p=d.creative||{},scores=creativeProfile(d),stage=d.steps===1?'RECORDING':d.steps===2?'MIXING':'MASTER READY',stageNo=Math.min(3,d.steps+1),guests=guestList(d);
 const nextStage=d.steps===1?{title:'Record the performance.',action:'Record song · $40 · 15 energy →'}:{title:'Mix the record.',action:'Mix song · $30 · 15 energy →'};
 return `<article class="v103-studio v103-session"><header class="v103-studio-head"><div><span>ENCORE / ACTIVE SESSION · ${careerDate()}</span><h1>${esc(d.title)}</h1><p>${esc(p.theme||'Personal story')} · ${esc(p.texture||'Warm & soulful')} · ${esc(p.intent||'Balanced')}</p></div><div class="v103-studio-energy"><span>SESSION ENERGY</span><strong>${s.energy}<small>/200</small></strong></div></header><nav class="v103-session-rail">${['WRITE','RECORD','MIX','RELEASE'].map((x,i)=>`<span class="${d.steps>i?'done':d.steps===i?'live':''}"><b>0${i+1}</b>${x}</span>`).join('')}</nav><section class="v103-active-room"><div class="v103-room-main"><div class="v103-redlight"><i></i><span>${stage}</span></div><div class="v103-track-title"><small>WORKING MASTER</small><h2>${esc(d.title)}</h2><p>${esc(d.sessionPlan?.feedback||'The song is written. Keep the session moving through recording and mixing.')}</p></div><div class="v103-wave v103-wave-live" aria-hidden="true">${Array.from({length:64},(_,i)=>`<i style="--h:${15+((i*29+d.steps*11)%76)}%"></i>`).join('')}</div><div class="v103-room-action">${d.steps<3?`<div><span>NEXT STAGE · 0${stageNo}</span><strong>${nextStage.title}</strong></div><button class="primary" onclick="progressSong()">${nextStage.action}</button>`:`<div><span>MASTER STATUS</span><strong>The record is ready for release planning.</strong></div><button class="primary" onclick="finishSong(true)">Continue to release →</button>`}</div></div><aside class="v103-session-sheet"><div class="v103-sheet-title"><span>SESSION SHEET</span><small>${esc(p.tempo||'Mid-tempo')}</small></div><dl><dt>Theme</dt><dd>${esc(p.theme||'Personal story')}</dd><dt>Intent</dt><dd>${esc(p.intent||'Balanced')}</dd><dt>Texture</dt><dd>${esc(p.texture||'Warm & soulful')}</dd><dt>Hook</dt><dd>${esc(p.hook||'Melodic refrain')}</dd><dt>Guests</dt><dd>${guests.length?guests.map(x=>esc(x.name)).join(', '):'Solo session'}</dd></dl><div class="v103-score-tape"><span>IDENTITY READOUT</span>${[['Depth',scores.depth],['Production',scores.production],['Performance',scores.performance],['Catchiness',scores.catchiness],['Originality',scores.originality],['Commercial',scores.commercial]].map(([k,v])=>`<div><small>${k}</small><i><b style="width:${v}%"></b></i><strong>${v}</strong></div>`).join('')}</div><p>These describe the record being shaped. Audience response and career context still decide what happens after release.</p></aside></section><section class="v103-collab-strip"><div><span>COLLABORATORS</span><strong>${guests.length?`${guests.length} attached`:'No features attached'}</strong></div><button onclick="go('Industry')">Find artists →</button><button onclick="go('Stats')">Check development →</button></section><details class="v103-studio-legacy"><summary>Session tools & project details</summary>${legacy}</details></article>`
}
