/* ENCORE Visual System 2.0 — release presentation + editorial charts. Mechanics stay in existing engines. */
const V103_finishSongBase=finishSong;
finishSong=function(release,confirmed=false){
 const d=s.draft;
 if(release&&!confirmed&&d&&d.steps===3){
  const x=creativeProfile(d);
  modal(`<article class="v103-release-room"><header><span>ENCORE / RELEASE ROOM</span><h2>Put “${esc(d.title)}” into the world.</h2><p>The master is finished. Publishing locks this recording into your released catalog; results resolve when the week closes.</p></header><section class="v103-release-master"><div class="v103-release-disc"><b>E</b><i></i></div><div><span>FINAL MASTER</span><h3>${esc(d.title)}</h3><p>${esc(d.creative?.theme||'Personal story')} · ${esc(d.creative?.texture||'Warm & soulful')} · ${esc(d.creative?.intent||'Balanced')}</p></div></section><section class="v103-release-readout">${[['QUALITY',d.quality],['DEPTH',x.depth],['CATCHINESS',x.catchiness],['COMMERCIAL',x.commercial]].map(([k,v])=>`<div><span>${k}</span><strong>${Math.round(v||0)}</strong></div>`).join('')}</section><div class="v103-release-terms"><div><span>RELEASE FEE</span><strong>$20</strong></div><div><span>ENERGY</span><strong>5</strong></div><div><span>RESULTS</span><strong>Week close</strong></div></div><p class="v103-release-note">A strong record is not guaranteed to chart. Audience size, career temperature, promotion, market fit and competition still matter.</p><footer><button class="secondary" onclick="$('modal').close()">Keep in studio</button><button class="primary" onclick="$('modal').close();finishSong(true,true)">Release single →</button></footer></article>`);return
 }
 return V103_finishSongBase(release,confirmed)
};

const V103_releaseShelfBase=releaseShelf;
releaseShelf=function(id,confirmed=false){
 const x=s.songs.find(x=>x.id===id);
 if(!confirmed&&x&&!x.released){
  modal(`<article class="v103-release-room"><header><span>ENCORE / CATALOG RELEASE</span><h2>Release “${esc(x.title)}” as a single.</h2><p>This finished recording will leave the shelf and enter the active catalog.</p></header><section class="v103-release-master compact"><div class="v103-release-disc"><b>E</b><i></i></div><div><span>ARCHIVED MASTER</span><h3>${esc(x.title)}</h3><p>Quality ${Math.round(x.quality||0)}/100 · Commercial potential ${Math.round(x.commercial||0)}/100</p></div></section><div class="v103-release-terms"><div><span>RELEASE FEE</span><strong>$20</strong></div><div><span>ENERGY</span><strong>5</strong></div><div><span>RESULTS</span><strong>Week close</strong></div></div><footer><button class="secondary" onclick="$('modal').close()">Not yet</button><button class="primary" onclick="releaseShelf(${JSON.stringify(id)},true)">Publish single →</button></footer></article>`);return
 }
 return V103_releaseShelfBase(id,confirmed)
};

const V103_releaseAlbumBase=releaseAlbum;
releaseAlbum=function(e,confirmed=false){
 if(!confirmed&&e){
  e.preventDefault();const f=new FormData(e.target),ids=f.getAll('track').map(Number),tracks=s.songs.filter(x=>ids.includes(x.id)&&!x.album);if(tracks.length<3){toast('Choose at least 3 finished tracks.');return}
  pendingAlbum=f;const title=String(f.get('albumtitle')||'').trim()||'Untitled album',price=Number(f.get('price'))||10,unreleased=tracks.filter(x=>!x.released).length;
  modal(`<article class="v103-release-room album"><header><span>ENCORE / ALBUM RELEASE DESK</span><h2>${esc(title)}</h2><p>${tracks.length} tracks are sequenced for this era. ${unreleased?`${unreleased} unreleased track${unreleased===1?'':'s'} will debut with the album.`:'Every track has already appeared as a single.'}</p></header><section class="v103-album-sequence">${tracks.map((x,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b><span>${esc(x.title)}</span><small>${x.released?'Previously released':'Album debut'}</small></div>`).join('')}</section><div class="v103-release-terms"><div><span>DOWNLOAD PRICE</span><strong>${money(price)}</strong></div><div><span>RELEASE FEE</span><strong>$100</strong></div><div><span>ENERGY</span><strong>10</strong></div></div><p class="v103-release-note">Album performance depends on the songs, cohesion, rollout, audience demand and the competitive week around it.</p><footer><button class="secondary" onclick="$('modal').close();pendingAlbum=null">Keep building</button><button class="primary" onclick="releaseAlbum(null,true)">Release album →</button></footer></article>`);return
 }
 return V103_releaseAlbumBase(e,confirmed)
};

function V103_chartSpark(kind,x){const rec=chartRecord(kind,x.key);const history=(rec?.history||[]).filter(p=>p.rank).slice(-10);if(!history.length)return '<span class="v103-chart-nohistory">NO HISTORY</span>';const max=kind==='songs'?100:50;return `<span class="v103-chart-spark" aria-label="Recent chart path">${history.map(p=>`<i style="--h:${Math.max(8,100-(p.rank-1)/Math.max(1,max-1)*92)}%" title="Week ${p.week}: #${p.rank}"></i>`).join('')}</span>`}
function V103_chartHub(){
 const kind=chartKind==='Albums'?'albums':'songs',list=kind==='songs'?chart():albumChart(),book=s.chartBook,board=book?.[kind],ready=book?.issuedWeek!==null&&book?.issuedWeek!==undefined,visible=chartMine?list.filter(x=>x.you):list,dropouts=ready?(board?.previous||[]).filter(x=>!(board?.current||[]).some(y=>y.key===x.key)):[],mine=list.filter(x=>x.you),best=mine[0]||null,metric=kind==='songs'?'streams':'units';
 return `<article class="v103-charts"><header class="v103-chart-head"><div><span>ENCORE / WEEKLY ISSUE · ${ready?'WEEK '+book.issuedWeek:'PREVIEW'}</span><h1>${kind==='songs'?'Global Top 100':'Global Albums 50'}</h1><p>${kind==='songs'?'Ranked by weekly streams with a 250,000-stream entry floor.':'Ranked by weekly album units; 1,500 track streams equal one unit.'}</p></div><div class="v103-chart-switch">${['Songs','Albums'].map(t=>`<button class="${chartKind===t?'active':''}" onclick="chartKind='${t}';render()">${t}</button>`).join('')}</div></header><section class="v103-chart-cover"><div><span>YOUR POSITION</span><strong>${best?'#'+best.rank:'—'}</strong><small>${best?esc(best.title):'No current entry'}</small></div><div><span>YOUR ENTRIES</span><strong>${mine.length}</strong><small>${mine.length?'currently charting':'build enough weekly activity to enter'}</small></div><div><span>NEW THIS WEEK</span><strong>${list.filter(x=>x.movement==='NEW').length}</strong><small>first recorded entries</small></div><div><span>ENTRY CUT</span><strong>${compact(list.at(-1)?.[metric]??(kind==='songs'?CHART_FLOOR:1000))}</strong><small>${metric}</small></div></section><div class="v103-chart-toolbar"><button aria-pressed="${chartMine}" onclick="chartMine=!chartMine;render()">${chartMine?'SHOW FULL CHART':'SHOW MY RELEASES'}</button><span>${ready?'Movement compares the previous completed issue.':'Advance a week to publish the first issue.'}</span></div><section class="v103-chart-table"><div class="v103-chart-columns"><span>RANK</span><span>RELEASE</span><span>PATH</span><span>${metric.toUpperCase()}</span></div>${visible.map(x=>{const owner=x.you?chartOwner(kind,x.id):null;return `<button class="v103-chart-row ${x.you?'you':''}" onclick="chartDetails('${kind}','${x.key}')"><span class="v103-rank"><strong>${x.rank??list.indexOf(x)+1}</strong><small class="movement-${x.movement||'BASE'}">${ready?movementLabel(x):'—'}</small></span><span class="v103-chart-title"><strong>${esc(x.title)}</strong><small>${esc(x.artist)}${x.you?' · YOU':''}</small><em>Peak ${x.peak?'#'+x.peak:'—'} · ${x.weeks??'—'} weeks${owner&&certificationUnits(owner,kind)>=500000?' · '+esc(certificationInfo(certificationUnits(owner,kind)).label):''}</em></span>${V103_chartSpark(kind,x)}<span class="v103-chart-volume"><strong>${compact(x[metric])}</strong><small>${metric}</small></span></button>`}).join('')||'<div class="v103-chart-empty"><strong>No chart entries yet.</strong><span>Your releases need enough weekly activity to beat the field.</span></div>'}</section>${dropouts.length?`<details class="v103-chart-drop"><summary>DROPPED OUT THIS WEEK · ${dropouts.length}</summary>${dropouts.filter(x=>!chartMine||x.you).map(x=>`<button onclick="chartDetails('${kind}','${x.key}')"><span>${esc(x.title)} · ${esc(x.artist)}</span><b>Last #${x.rank}</b></button>`).join('')||'<p>No releases of yours dropped out.</p>'}</details>`:''}<footer class="v103-chart-key"><span>NEW = first chart entry</span><span>RE-ENTRY = returned after dropping out</span><span>ENTRY = first observed after tracking began</span></footer></article>`
}
chartHub=V103_chartHub;

const V103_releaseDetailsBase=releaseDetails;
releaseDetails=function(kind,id){const item=chartOwner(kind,id);if(!item)return;const key='you:'+(kind==='songs'?'s':'a')+':'+id,rec=chartRecord(kind,key),row=s.chartBook?.[kind]?.current?.find(x=>x.key===key),streams=kind==='albums'?albumStreams(item,true):item.total,units=certificationUnits(item,kind);modal(`<article class="v103-release-file"><header><span>${kind==='songs'?'SINGLE':'ALBUM'} / RELEASE FILE</span><h2>${esc(item.title)}</h2><p>Released Week ${kind==='songs'?item.released:item.week} · ${certificationInfo(units).label}</p></header><section class="v103-release-file-grid"><div><span>LIFETIME STREAMS</span><strong>${fmt(streams||0)}</strong></div><div><span>CERTIFICATION UNITS</span><strong>${fmt(units)}</strong></div><div><span>CHART PEAK</span><strong>${rec?.peak?'#'+rec.peak:'—'}</strong></div><div><span>WEEKS CHARTED</span><strong>${rec?.weeks??0}</strong></div></section>${rec?`<section class="v103-release-chartline"><div><span>CURRENT</span><strong>${row?'#'+row.rank:'OFF CHART'}</strong></div><div><span>DEBUT</span><strong>${rec.debutRank?'#'+rec.debutRank:'—'}</strong></div><div><span>#1 WEEKS</span><strong>${rec.numberOneWeeks||0}</strong></div>${V103_chartSpark(kind,{key})}</section>`:'<p class="v103-release-note">No recorded chart entry yet.</p>'}${kind==='songs'?`<section class="v103-release-identity"><span>RECORD IDENTITY</span><div><b>Quality</b><strong>${item.quality}/100</strong></div><div><b>Commercial potential</b><strong>${item.commercial??'—'}/100</strong></div><div><b>Lifecycle</b><strong>${esc(item.lifecycle||'Awaiting debut')}</strong></div></section>`:`<section class="v103-release-identity"><span>ALBUM READOUT</span><div><b>Cohesion</b><strong>${item.cohesion??'—'}/100</strong></div><div><b>Critical reception</b><strong>${item.criticalReception??'—'}/100</strong></div></section>`}<footer><button class="primary" onclick="$('modal').close()">Close release file</button></footer></article>`)};

/* ENCORE Visual System 2.0 — living PULSE feed + graphical touring operations. */
function V103_pulsePostCard(p){
 const format=pulseFormats.find(f=>f.id===p.format)?.name||'Post',song=p.song?s.songs.find(x=>x.id===p.song):null,eng=p.views?((p.likes+p.comments+p.shares)/p.views*100):0;
 return `<article class="v103-pulse-post"><header><div><span>@${esc(s.name.toLowerCase().replace(/[^a-z0-9]/g,'')||'artist')}</span><strong>${esc(s.name)}</strong></div><small>W${p.week} · ${esc(format)}${p.viral?' · SURGE':''}</small></header><p>${esc(p.caption)}</p>${song?`<button class="v103-linked-song" onclick="releaseDetails('songs',${song.id})">♪ ${esc(song.title)}</button>`:''}<div class="v103-pulse-metrics"><span><b>${compact(p.views)}</b> views</span><span><b>${compact(p.likes)}</b> likes</span><span><b>${compact(p.comments)}</b> replies</span><span><b>${compact(p.shares)}</b> reposts</span></div><footer><span>${eng.toFixed(1)}% engagement · +${compact(p.followers)} followers · +${compact(p.fans)} true fans</span><button ${p.replied||p.week!==s.week?'disabled':''} onclick="replyPulse(${p.id})">${p.replied?'REPLIED':'REPLY · 5 ENERGY'}</button></footer>${p.reaction?`<blockquote>“${esc(p.reaction)}”</blockquote>`:''}</article>`
}
function V103_industryPostCard(p){const artist=s.world[p.artist];if(!artist)return '';const done=s.social.interactions.some(x=>x.week===s.week&&x.artist===p.artist);return `<article class="v103-pulse-industry"><div class="v103-pulse-avatar">${personPhoto('artist-'+artist.id,artist.name)}</div><div><header><strong>${esc(artist.name)}</strong><span>${esc(artist.genre)} · W${p.week}</span></header><p>${esc(p.text)}</p><button ${done?'disabled':''} onclick="supportPulse(${artist.id})">${done?'SUPPORTED':'SUPPORT · 2 ENERGY'}</button></div></article>`}
function V103_pulsePage(){
 migrateSocial();const a=s.social,m=socialAnalytics(),posted=a.posts.filter(p=>p.week===s.week).length,recent=a.posts.slice().reverse().slice(0,8),feed=a.feed.slice().reverse().slice(0,12),topPost=[...m.posts].sort((x,y)=>((y.likes+y.comments+y.shares)/Math.max(1,y.views))-((x.likes+x.comments+x.shares)/Math.max(1,x.views)))[0];
 return `<article class="v103-pulse"><header class="v103-pulse-head"><div><span>PULSE / LIVE PUBLIC CONVERSATION</span><h1>The world is talking.</h1><p>Your posts, fan response and industry conversation feed discovery, leverage and career heat.</p></div><button class="v103-compose" ${posted>=3?'disabled':''} onclick="composePulse()">CREATE POST <b>${posted}/3</b></button></header><section class="v103-pulse-profile"><div class="v103-pulse-person">${personPhoto('player-'+s.name,s.name)}<div><span>@${esc(s.name.toLowerCase().replace(/[^a-z0-9]/g,'')||'artist')}</span><h2>${esc(s.name)}</h2><p>${esc(s.genre)} · ${esc(tierNames[tier(s.fans)])}</p></div></div><div class="v103-pulse-kpis">${[['FOLLOWERS',compact(a.followers)],['RECENT VIEWS',compact(m.views)],['ENGAGEMENT',(m.rate*100).toFixed(1)+'%'],['LABEL SIGNAL',m.signal+'/100']].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div></section><div class="v103-pulse-explainer"><strong>How to read PULSE</strong><span>Engagement is saved likes + replies + reposts divided by views. Generated posts have a 25% floor and no artificial ceiling; above 100% means some viewers interacted more than once.</span></div><section class="v103-pulse-layout"><main><div class="v103-pulse-sectionhead"><span>YOUR CHANNEL</span><small>${recent.length?`${recent.length} recent posts`:'No posts yet'}</small></div>${recent.length?recent.map(V103_pulsePostCard).join(''):`<div class="v103-pulse-empty"><h2>Your first post starts the public record.</h2><p>Performance clips, studio access, stories, trends and release announcements create different kinds of attention.</p><button onclick="composePulse()">Create first post →</button></div>`}</main><aside><section class="v103-pulse-radar"><span>LABEL RADAR</span><strong>${m.signal}/100</strong><small>Current scouting signal</small><i><b style="width:${m.signal}%"></b></i><p>${m.signal>=70?'Your active reach is difficult for labels to ignore.':m.signal>=40?'Your audience activity is creating measurable industry attention.':'Build consistent engaged reach to become easier to discover.'}</p><button onclick="careerTab='Labels';go('Career')">Open deals →</button></section><section class="v103-pulse-note"><span>CHANNEL NOTE</span><h3>${topPost?'Your strongest recent signal':'No signal yet'}</h3><p>${topPost?`${((topPost.likes+topPost.comments+topPost.shares)/Math.max(1,topPost.views)*100).toFixed(1)}% engagement on “${esc(topPost.caption.slice(0,54))}${topPost.caption.length>54?'…':''}”.`:'Your best-performing posts will be called out here as the channel develops.'}</p></section><section class="v103-pulse-history"><span>8-WEEK ACTIVITY</span>${a.weekly.slice(-8).reverse().map(w=>`<div><small>W${w.week}</small><i><b style="width:${Math.min(100,Math.log10(1+w.views)*18)}%"></b></i><strong>${compact(w.views)}</strong></div>`).join('')||'<p>No weekly history yet.</p>'}</section></aside></section><section class="v103-industry-feed"><div class="v103-pulse-sectionhead"><span>INDUSTRY FEED</span><small>Fictional artists · support shapes relationships</small></div>${feed.length?feed.map(V103_industryPostCard).join(''):'<p>Advance a week to see artists around the industry speak.</p>'}</section></article>`
}
pulseAnalyticsPage=V103_pulsePage;

function V103_tourMap(route){
 const plotted=route.filter(r=>V094_marketCoords[r.city]),ordered=[...plotted].sort((a,b)=>a.week-b.week||a.id-b.id),points=ordered.map(r=>{const p=V094_marketCoords[r.city];return `${p[0]*10},${p[1]*6}`}).join(' ');
 return `<svg class="v103-tour-map-svg" viewBox="0 0 1000 600" role="img" aria-label="Tour route map"><path class="land" d="M72 138 145 112 220 132 286 124 352 146 420 130 500 146 574 128 650 151 731 145 804 174 867 185 910 220 884 258 906 300 878 341 900 391 878 430 850 462 824 451 808 414 777 401 748 414 705 428 655 411 596 431 534 420 474 391 414 399 360 380 313 351 263 340 221 303 172 291 151 253 111 221Z"/>${points?`<polyline class="route" points="${points}"/>`:''}${ordered.map((r,i)=>{const p=V094_marketCoords[r.city],m=careerWorldMarket(r.city),city=m?.city||r.city;return `<g class="stop ${r.status}"><circle cx="${p[0]*10}" cy="${p[1]*6}" r="${r.status==='played'?11:9}"/><text x="${p[0]*10+14}" y="${p[1]*6-8}">${i+1}. ${esc(city)}</text><text class="week" x="${p[0]*10+14}" y="${p[1]*6+8}">W${r.week}</text></g>`}).join('')}</svg>`
}
function V103_tourStopRow(r,route){const m=careerWorldMarket(r.city),city=m?.city||r.city,v=liveVenues[r.venue],n=r.report||tourStopEstimate(r,route),sell=Math.round(n.tickets/Math.max(1,v.seats)*100);return `<button class="v103-tour-stop ${r.status}" onclick="${r.status==='scheduled'?`editTourStop(${r.id})`:`void(0)`}"><span class="num">${String(route.indexOf(r)+1).padStart(2,'0')}</span><span class="city"><strong>${esc(city)}</strong><small>W${r.week} · ${esc(V100_venueProfile(r.venue).className)} · ${fmt(v.seats)} cap</small></span><span class="forecast"><b>${sell}%</b><small>sell-through</small></span><span class="money"><b>${money(n.net)}</b><small>${r.report?'show net':'projected net'}</small></span><span class="arrow">${r.status==='scheduled'?'↗':r.status==='played'?'✓':'×'}</span></button>`}
function V103_tourPage(){
 const z=migrateTouring(),t=activeTour(),route=t?.route||z.draft.route,past=s.liveTour&&!t?s.liveTour:null,scheduled=route.filter(r=>r.status==='scheduled'),played=route.filter(r=>r.status==='played'),gross=t?.gross||played.reduce((n,r)=>n+(r.report?.gross||0),0),projected=scheduled.reduce((n,r)=>n+tourStopEstimate(r,route).net,0),currentMarket=careerWorldMarket(s.careerWorld.currentCity);
 return `<article class="v103-tour"><header class="v103-tour-head"><div><span>TOURING / GEOGRAPHIC OPERATIONS</span><h1>${t?esc(t.name):'Build the route.'}</h1><p>Every dot is a market. Venue scale, local audience, ticket price, promoter confidence and travel turn geography into risk.</p></div><div class="v103-tour-actions"><button class="primary" onclick="editTourStop()">ADD SHOW</button>${!t&&route.length?'<button onclick="reviewWorldTour()">REVIEW ROUTE</button>':''}${t?'<button onclick="cancelWorldTour()">CANCEL REMAINING</button>':''}</div></header><section class="v103-tour-kpis">${[['SHOWS',`${played.length} played / ${route.length} planned`],['LIVE GROSS',money(gross)],['PROJECTED REMAINING NET',money(projected)],['CURRENT CITY',esc(currentMarket?.city||s.careerWorld.currentCity||'—')]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</section><section class="v103-tour-map"><div class="v103-tour-mapbar"><span>ROUTE MAP</span><div><i class="played"></i> Played <i class="scheduled"></i> Scheduled <i class="cancelled"></i> Cancelled</div></div>${V103_tourMap(route)}${!route.length?'<div class="v103-map-empty"><strong>No route on the board.</strong><span>Add a city to start drawing the tour.</span></div>':''}</section><section class="v103-tour-ops"><div class="v103-tour-sectionhead"><span>ROUTE LEDGER</span><small>Tap a scheduled stop to edit, reschedule or inspect promoter reality.</small></div>${route.length?[...route].sort((a,b)=>a.week-b.week||a.id-b.id).map(r=>V103_tourStopRow(r,route)).join(''):'<button class="v103-tour-first" onclick="editTourStop()">+ PLACE THE FIRST SHOW</button>'}</section><section class="v103-tour-context"><div><span>HOW DEMAND WORKS</span><p>Regional fans, recent streams, loyalty, city heat, price resistance, repeat visits and opener reach shape demand. Larger rooms add promoter scrutiny and more expensive crew, production, security and logistics.</p></div><div><span>WHAT NET MEANS</span><p>Show net is before label/agent shares and tax. Finance settles those separately, so gross is never presented as take-home.</p></div></section>${tourOpeningOffers()}${past?`<details class="v103-tour-archive"><summary>Last tour · ${esc(past.name)}</summary>${tourRouteCards(past.route)}</details>`:''}${z.archive.length?`<details class="v103-tour-archive"><summary>Earlier tours · ${z.archive.length}</summary>${z.archive.map(a=>`<div><strong>${esc(a.name)}</strong><span>${a.played} shows · ${money(a.gross)} gross</span></div>`).join('')}</details>`:''}</article>`
}
tourPage=V103_tourPage;

/* ENCORE Visual System 2.0 — executive Business HQ + editorial weekly career report. */
function V103_businessPriority(){const items=V096_priorityRaw().filter(x=>['creative','commercial'].includes(x.kind)).slice(0,5);return `<section class="v103-hq-priority"><header><span>PRIORITY INBOX</span><small>${items.length} decision${items.length===1?'':'s'} waiting</small></header>${items.length?items.map(x=>`<button onclick="V096_openPriority('${x.key}')"><i>${x.kind==='creative'?'✦':'$'}</i><span><small>${esc(x.category)}</small><strong>${esc(x.title)}</strong><em>${esc(x.detail)}</em></span><b>REVIEW →</b></button>`).join(''):'<div class="v103-hq-clear"><strong>Desk clear.</strong><span>No creative or commercial request needs a decision right now.</span></div>'}</section>`}
function V103_businessDirectory(){const groups=[...new Set(V096_BUSINESS_AREAS.map(x=>x.group))];return groups.map(group=>`<section class="v103-hq-dept"><header><span>${esc(group).toUpperCase()}</span><small>${V096_BUSINESS_AREAS.filter(x=>x.group===group).length} departments</small></header>${V096_BUSINESS_AREAS.filter(x=>x.group===group).map(x=>{const badge=V096_businessAreaBadge(x.id);return `<button onclick="V096_openBusinessArea('${x.id}')"><span class="mark">${String(x.name).split(/\s+/).slice(0,2).map(w=>w[0]).join('')}</span><span><strong>${esc(x.name)}</strong><small>${esc(x.desc)}</small></span><b>${badge?badge+' ACTIVE':'OPEN'} →</b></button>`}).join('')}</section>`).join('')}
const V103_businessPageOld=V092_businessPage;
V092_businessPage=function(){migrateV096();const co=s.labelBusiness?.company,contracts=(s.v080?.commercial?.contracts||[]).filter(x=>x.active).length,sportsTeams=new Set((s.v081?.sports?.holdings||[]).map(h=>h.team)).size,creative=V096_businessAreaBadge('Creative'),value=V092_businessValue();return `<article class="v103-hq"><header class="v103-hq-head"><div><span>BUSINESS HQ / EXECUTIVE OFFICE</span><h1>${co?esc(co.name):esc(s.name)+' Enterprises'}</h1><p>The business side of your career in one office. Review what needs a decision, then enter the department that owns it.</p></div><div class="v103-hq-value"><span>BUSINESS ASSETS</span><strong>${money(value)}</strong><small>Estimated current value across tracked business holdings.</small></div></header><section class="v103-hq-strip">${[['ACTIVE DEALS',contracts],['CREATIVE REQUESTS',creative],['SPORTS FRANCHISES',sportsTeams],['CASH',money(s.cash)]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</section><div class="v103-hq-layout"><main>${V103_businessPriority()}<section class="v103-hq-directory"><header><span>COMPANY DIRECTORY</span><small>Each department opens the existing authoritative business system.</small></header>${V103_businessDirectory()}</section></main><aside><section><span>EXECUTIVE NOTE</span><h2>${creative||contracts?'Your company has moving pieces.':'Build beyond the music.'}</h2><p>${creative?'Creative requests are waiting. ':''}${contracts?contracts+' commercial deal'+(contracts===1?' is':'s are')+' active. ':''}Ownership, representation, rights, merchandise and investments remain separate businesses with separate economics.</p></section><section><span>HOW TO READ HQ</span><p><b>Active</b> means a department currently contains an item or holding. Opening a department does not accept an offer or spend money automatically.</p></section></aside></div></article>`};

function V103_recapRows(r){const income=[['Streaming royalties',r.royalties],['Album / download sales',r.albumSales],['Live & appearances',r.live],['Media & commercial',r.media],['Publishing',r.publishing],['Sync licensing',r.sync],['Endorsements',r.endorsement],['Merchandise',r.merch],['Sponsorships',r.sponsorship],['Work & advances',r.wages],['Owned label · roster revenue',r.labelBusiness],['Businesses, investments & rent',r.investment],['Other career income',r.other]].filter(x=>Number(x[1]));const contractual=[];if(r.labelCut)contractual.push(['Label royalty share',r.labelCut]);if(Array.isArray(r.representation))for(const x of r.representation)if(x.fee)contractual.push([`${x.name} · ${x.rate}% of eligible income`,x.fee]);else if(r.agentFee)contractual.push(['Representation commissions',r.agentFee]);const op=r.operations||{},expenses=[['Label payroll',r.labelPayroll],['Actions & projects',Math.max(0,(r.actionExpenses||0)-(r.labelPayroll||0))],['Administration',op.administration],['Insurance',op.insurance],['Accounting & legal',op.accountingLegal],['Workspace & local travel',op.workspaceTravel]].filter(x=>Number(x[1]));return {income,contractual,expenses}}
function V103_recapSection(title,rows,negative=false){return `<section class="v103-recap-ledger"><header>${title}</header>${rows.length?rows.map(([k,v])=>`<div><span>${esc(k)}</span><strong>${negative?'−':''}${money(Math.abs(v||0))}</strong></div>`).join(''):'<p>No activity in this section this week.</p>'}</section>`}
function V103_weekRecap(completed,count,added,debut,financial,earned=[]){const label=V083_weekDate(completed),next=V083_weekDate(completed+1),rows=V103_recapRows(financial),gross=Math.max(0,financial.revenue||0),contractual=rows.contractual.reduce((n,x)=>n+Math.abs(x[1]||0),0),expenses=rows.expenses.reduce((n,x)=>n+Math.abs(x[1]||0),0),tax=Math.abs(financial.taxReserve||0),kept=financial.net||0,parts=[['CONTRACTS',contractual],['CAREER COSTS',expenses],['TAX RESERVE',tax],['YOU KEPT',Math.max(0,kept)]],den=Math.max(1,gross),feedCount=s.feed.filter(x=>x.week===completed).length;modal(`<article class="v103-recap"><header class="v103-recap-cover"><span>ENCORE / WEEKLY CAREER REPORT</span><small>${esc(label)}</small><h1>${compact(count)} streams.</h1><p class="${added>=0?'up':'down'}">${added>=0?'+':''}${compact(added)} net fans this week</p></header><section class="v103-recap-score">${[['GROSS INCOME',money(gross)],['YOU KEPT',money(kept)],['SPENDABLE CASH',money(financial.cash||0)],['ENERGY RESET','200 / 200']].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</section><div class="v103-recap-grid"><main>${V103_recapSection('01 / GROSS INCOME',rows.income)}${V103_recapSection('02 / CONTRACTUAL DISTRIBUTION',rows.contractual,true)}${V103_recapSection('03 / CAREER EXPENSES',rows.expenses,true)}<section class="v103-recap-ledger tax"><header>04 / TAXES</header><div><span>${financial.taxReserve<0?'Reserve returned':'Reserve change this week'}</span><strong>${financial.taxReserve<0?'+':'−'}${money(tax)}</strong></div><div><span>Effective rate</span><strong>${V091_pct(financial.effectiveTaxRate||0)}</strong></div><div><span>Current marginal rate</span><strong>${V091_pct(financial.marginalTaxRate||0)}</strong></div>${financial.yearEnd?`<p>Tax year settled: ${money(financial.settlement)} paid from the accumulated reserve.</p>`:''}</section><section class="v103-recap-kept"><span>05 / YOU KEPT</span><strong>${money(kept)}</strong><p>Week-close net after recorded contractual distributions, career expenses and the tax-reserve change above.</p></section></main><aside><section class="v103-dollar"><span>WHERE EVERY $1 WENT</span>${parts.map(([k,v])=>{const pct=Math.max(0,v/den*100);return `<div><header><small>${k}</small><b>${pct.toFixed(1)}¢</b></header><i><b style="width:${Math.min(100,pct)}%"></b></i></div>`}).join('')}<p>Shown as cents per $1 of gross income. When deductions plus kept income differ from gross because of reserve returns or timing, the ledger remains authoritative.</p></section><section class="v103-recap-career"><span>CAREER MOVEMENT</span><div><small>Net fans</small><strong>${added>=0?'+':''}${compact(added)}</strong></div><div><small>Industry releases</small><strong>${feedCount}</strong></div><div><small>Achievements filed</small><strong>${earned.length}</strong></div><p>Charts, audience and industry systems resolve before this report closes the week.</p></section></aside></div><footer><button onclick="$('modal').close();careerTab='Finances';go('Career')">FULL FINANCIAL REPORT</button><button class="primary" onclick="$('modal').close()">CONTINUE · ${esc(next)}</button></footer></article>`,'memo-dialog v103-recap-dialog');queueSave()}
weekRecap=V103_weekRecap;

/* ENCORE Visual System 2.0 — global navigation shell + living Industry Desk. */
function V103_navActive(id){if(id==='Career')return tab==='ArtistFile'||(tab==='Career'&&!['BusinessHQ',...Array.from(typeof V096_BUSINESS_IDS!=='undefined'?V096_BUSINESS_IDS:[])].includes(careerTab));if(id==='Create')return tab==='Create';if(id==='Home')return tab==='Home';if(id==='Industry')return tab==='Industry';if(id==='BusinessHQ')return tab==='Career'&&careerTab==='BusinessHQ';return false}
function V103_navGo(id){if(id==='Career'){openArtistFile();return}if(id==='BusinessHQ'){V096_openBusinessArea('BusinessHQ');return}go(id)}
navigationBar=function(){const items=[['Career','Career','M3 5h18v3H3zm0 6h18v8H3z'],['Create','Create','M5 19V5h14v14H5zm3-11h8v2H8zm0 4h5v2H8z'],['Home','Home','M3 11 12 3l9 8v10h-6v-6H9v6H3z'],['Industry','Industry','M4 20V9h4v11zm6 0V4h4v16zm6 0V7h4v13z'],['HQ','BusinessHQ','M4 7h16v13H4zm4 0V4h8v3']];return items.map(([label,id,path])=>`<button class="v103-nav-${id.toLowerCase()} ${V103_navActive(id)?'active':''} ${id==='Home'?'nav-home':''}" onclick="V103_navGo('${id}')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg><span>${label}</span></button>`).join('')}
function V103_shellContext(){if(tab==='Home')return 'CAREER COMMAND';if(tab==='Create')return 'STUDIO';if(tab==='Stats')return 'DEVELOPMENT';if(tab==='Industry')return industryTab==='Charts'?'CHARTS':industryTab==='New releases'?'RELEASE DESK':'INDUSTRY';if(tab==='ArtistFile')return 'ARTIST FILE';if(tab==='Career'&&careerTab==='BusinessHQ')return 'BUSINESS HQ';if(tab==='Career')return String(careerTab||'CAREER').toUpperCase();return String(tab||'ENCORE').toUpperCase()}
navigationTools=function(){const unread=typeof V080_unreadCount==='function'?V080_unreadCount():0;return `<header class="v103-shellbar"><button class="v103-shell-back" onclick="goBack()" aria-label="Back">← Back</button><div class="v103-shell-id"><span>ENCORE / ${V103_shellContext()}</span><small>${careerDate()}</small></div><div class="v103-shell-state"><button onclick="statDetail('cash')"><small>CASH</small><strong>${money(s.cash)}</strong></button><button onclick="statDetail('energy')"><small>ENERGY</small><strong>${s.energy}/200</strong></button></div><button class="v103-shell-guide" onclick="go('Guide')" aria-label="Player Guide">Guide ?</button><button class="v103-shell-menu" onclick="go('Menu');restoreMenuPosition?.()" aria-label="Open menu"><span></span><span></span><span></span>${unread?`<b>${unread}</b>`:''}</button></header>`}
function V103_menuGroupIcon(group){return ({Music:'♪',Social:'◎',Business:'▣',Wealth:'◇',Career:'◫',Legacy:'✦'})[group]||'·'}
menuPage=function(){const rows=typeof V080_destinations!=='undefined'?V080_destinations:destinations;return `<article class="v103-menu"><header><span>ENCORE / DIRECTORY</span><h1>Where do you want to go?</h1><p>Search the entire career, or move through the departments below.</p><label><span>FIND A SCREEN</span><input type="search" placeholder="Studio, contracts, touring…" oninput="$('v103-menu-results').innerHTML=V103_menuResults(this.value)"></label></header><div id="v103-menu-results">${V103_menuResults('')}</div><footer><button onclick="openSettings()">SETTINGS</button><button onclick="go('Guide')">PLAYER GUIDE</button><button onclick="showTitle()">TITLE SCREEN</button></footer></article>`}
function V103_menuResults(query=''){const rows=typeof V080_destinations!=='undefined'?V080_destinations:destinations,q=String(query).trim().toLowerCase(),matches=rows.filter(d=>d.join(' ').toLowerCase().includes(q)),groups=[...new Set(matches.map(x=>x[1]))];return encoreIconDirectory(query)+groups.map(group=>`<section class="v103-menu-group"><header><i>${V103_menuGroupIcon(group)}</i><span>${esc(group).toUpperCase()}</span><small>${matches.filter(x=>x[1]===group).length}</small></header>${matches.filter(x=>x[1]===group).map(([name,g,id,desc])=>`<button data-destination="${id}" onclick="openDestination('${id}')"><span><strong>${esc(name)}</strong><small>${esc(desc)}</small></span><b>↗</b></button>`).join('')}</section>`).join('')||'<section class="v103-menu-empty"><strong>No matching destination.</strong><span>Try a broader term.</span></section>'}

function V103_industryHeat(){if(typeof migrateAiIndustry==='function'){const z=migrateAiIndustry(),entries=Object.entries(z.genreHeat||{}).sort((a,b)=>b[1]-a[1]);if(entries[0])return {genre:entries[0][0],value:entries[0][1]}}return {genre:'Mixed',value:1}}
function V103_industryArtists(){const visible=s.world.filter(a=>(filter==='All'||tierNames[tier(a.fans)]===filter)&&(genreFilter==='All'||a.genre===genreFilter)).sort((a,b)=>(b.weekly||0)-(a.weekly||0)||b.fans-a.fans);return `<section class="v103-industry-filter"><div class="v103-tier-strip">${['All',...tierNames].map(x=>`<button class="${filter===x?'selected':''}" onclick="filter='${x}';render()">${x}</button>`).join('')}</div><label>GENRE<select onchange="genreFilter=this.value;render()">${['All',...genres].map(g=>`<option ${g===genreFilter?'selected':''}>${g}</option>`).join('')}</select></label></section><section class="v103-industry-roster"><header><span>ARTIST WATCH</span><small>${visible.length} artists in this view · ranked by current weekly activity</small></header>${visible.map((a,i)=>{const career=a.aiCareer||{},recent=a.catalog?.at(-1),status=career.status==='retired'?'RETIRED':career.stage||tierNames[tier(a.fans)],relation=relationship(a);return `<button onclick="profile(${a.id})"><span class="rank">${String(i+1).padStart(2,'0')}</span>${personPhoto('artist-'+(a.directoryKey??a.id),a.name)}<span class="identity"><small>${esc(a.genre)} · ${esc(status)}</small><strong>${esc(a.name)}</strong><em>${recent?'Latest: “'+esc(recent.title)+'”':'Catalog building'}</em></span><span class="numbers"><strong>${compact(a.weekly||0)}</strong><small>STREAMS / WK</small></span><span class="numbers"><strong>${compact(a.fans)}</strong><small>FANS</small></span><span class="relation ${a.relation<0?'bad':''}">${esc(relation)}<small>${a.relation>0?'+':''}${a.relation}</small></span><b>↗</b></button>`}).join('')||'<div class="v103-industry-empty">No artists match these filters.</div>'}</section><section class="v103-industry-note"><span>CAREER LADDER</span><p>Unknown → Emerging → Breakout → Star → Superstar → Global star → Global icon. Fame is only one part of the simulation: release quality, reception, genre climate, relationships, career stage and strategy also shape results.</p></section>`}
function V103_industryReleases(){const feed=s.feed.slice(0,40);return `<section class="v103-release-desk"><header><div><span>THE RELEASE DESK</span><h2>${feed.length?'The industry keeps moving.':'Quiet release week.'}</h2></div><small>${typeof V083_weekDate==='function'?V083_weekDate(Math.max(1,s.week-1)):'LATEST ISSUE'}</small></header>${feed.length?feed.map((x,i)=>`<article><span class="issue">${String(i+1).padStart(2,'0')}</span><div><small>${esc(x.type)} · ${esc(x.tier||'')}</small><strong>${esc(x.title)}</strong><span>${esc(x.name)}</span></div><div><strong>${compact(x.streams)}</strong><small>DEBUT STREAMS</small></div><b class="${String(x.result).toLowerCase().includes('hit')?'up':String(x.result).toLowerCase().includes('flop')?'down':''}">${esc(x.result||'Released')}</b></article>`).join(''):'<p>Advance the week and the living industry will publish its next wave of releases.</p>'}</section>`}
industry=function(){const heat=V103_industryHeat(),active=s.world.filter(a=>a.aiCareer?.status!=='retired').length||s.world.length,releases=s.feed.filter(x=>x.week===Math.max(1,s.week-1)).length,leader=s.world.slice().sort((a,b)=>(b.weekly||0)-(a.weekly||0))[0];return `<article class="v103-industry"><header class="v103-industry-head"><div><span>ENCORE / INDUSTRY DESK</span><h1>The world moves<br>without you.</h1><p>Artists release, rise, cool off, sign deals and build careers on their own timelines. Watch the market—or become the story.</p></div><button onclick="featurePicker()"><span>COLLABORATION DIRECTORY</span><strong>Explore 2,500+ artists →</strong></button></header><section class="v103-industry-tape">${[['ACTIVE ARTISTS',active],['RELEASES LAST ISSUE',releases],['HOT GENRE',heat.genre],['WEEKLY LEADER',leader?.name||'—']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</section><nav class="v103-industry-tabs">${['Artists','Charts','New releases'].map(x=>`<button class="${industryTab===x?'selected':''}" onclick="industryTab='${x}';render()">${x==='New releases'?'Release Desk':x}</button>`).join('')}</nav>${industryTab==='Charts'?`<section class="v103-industry-chart">${chartHub()}</section>`:industryTab==='New releases'?V103_industryReleases():V103_industryArtists()}</article>`}

