/* Advisor quality affects uncertainty and advice — not the underlying tax. */
function V112_forecastUncertainty(){
 const bm=V112_businessManager(),cpa=V112_cpa();
 let spread=.18;
 if(bm)spread-=clamp(Number(bm.skill||70),0,100)/100*.04;
 if(cpa)spread-=clamp(Number(cpa.skill||70),0,100)/100*.08;
 return clamp(spread,.04,.18)
}
function V112_forecastConfidence(){return Math.round((1-V112_forecastUncertainty())*100)}
function V112_cashFloor(){
 const last=s.finance?.last,weekly=Math.max(0,Number(last?.expenses||0))+Math.max(0,Number(last?.taxReserve||0));
 const base=weekly||Math.max(500,V100_operatingTotal?.(V100_operatingCosts?.()||{})||0);
 return cents(base*(V112_businessManager()?8:4))
}
function V112_taxForecast(){
 const p=V111_taxPlanningSnapshot(),spread=V112_forecastUncertainty(),estimate=Math.max(0,p.quote.total),low=cents(estimate*(1-spread)),high=cents(estimate*(1+spread)),strategy=V112_strategy(),recommended=Math.max(0,p.reserve),target=cents(recommended*strategy.multiplier),shortfall=Math.max(0,cents(estimate-target));
 return {...p,spread,low,high,confidence:V112_forecastConfidence(),strategy,target,shortfall,cashFloor:V112_cashFloor()}
}

const V112_repAdviceForBase=V100_repAdviceFor;
V100_repAdviceFor=function(role){
 if(role==='business'){
  const x=V112_taxForecast();return `Reserve strategy: ${x.strategy.name}. Keep enough liquidity for a ${V112_businessManager()?'roughly eight':'basic four'}-week operating buffer (${money(x.cashFloor)}) before treating the remaining cash as truly discretionary.`
 }
 if(role==='cpa'){
  const x=V112_taxForecast();return `Current estimated tax liability is ${money(x.quote.total)} with a ${x.confidence}/100 forecast-confidence score. ${x.shortfall>0?'Your current strategy leaves about '+money(x.shortfall)+' of estimated exposure outside the target reserve.':'Current reserve coverage is at or above the selected target.'}`
 }
 return V112_repAdviceForBase(role)
};

/* Charge the CPA as a real weekly career expense before taxes are calculated.
   The base finance engine already treats action expenses as paid when incurred,
   so cash is reduced once after close while the expense participates in the
   current taxable-income calculation. */
const V112_closeFinancesBase=closeFinances;
closeFinances=function(royalties,rate){
 const plan=V112_plan(),cpa=V112_cpa(),advisorFee=cpa?V112_cpaWeeklyFee():0;
 if(advisorFee){migrateFinance?.();if(!s.finance.week||typeof s.finance.week!=='object')s.finance.week={wages:0,live:0,expenses:0};s.finance.week.expenses=cents((Number(s.finance.week.expenses)||0)+advisorFee)}
 const report=V112_closeFinancesBase(royalties,rate);
 if(advisorFee){changeCash(-advisorFee);report.taxAdvisorFee=advisorFee;report.cash=s.cash;moneyEvent?.((cpa?.name||'CPA')+' tax-advisory retainer',-advisorFee)}
 report.reserveStrategy=plan.reserveStrategy;
 report.reserveStrategyName=V112_strategy().name;
 if(!report.yearEnd){
  const recommended=Math.max(0,Number(s.finance.reserve)||0),strategy=V112_strategy(),rawTarget=cents(recommended*strategy.multiplier);let adjustment=cents(rawTarget-recommended);
  if(adjustment>0)adjustment=Math.min(adjustment,Math.max(0,Number(s.cash)||0));
  if(adjustment){changeCash(-adjustment);s.finance.reserve=cents(recommended+adjustment);report.taxReserve=cents((Number(report.taxReserve)||0)+adjustment);report.net=cents((Number(report.net)||0)-adjustment);report.cash=s.cash}
  report.recommendedTaxReserve=recommended;report.actualTaxReserve=Math.max(0,Number(s.finance.reserve)||0);report.reserveCoverage=recommended?report.actualTaxReserve/recommended:1;report.projectedReserveShortfall=Math.max(0,cents(recommended-report.actualTaxReserve))
 }else{
  report.recommendedTaxReserve=Math.max(0,Number(report.settlement)||0);report.actualTaxReserve=report.recommendedTaxReserve;report.reserveCoverage=1;report.projectedReserveShortfall=0
 }
 report.taxForecastConfidence=V112_forecastConfidence();
 return report
};

/* Keep advisor fees readable instead of hiding the CPA inside Actions & Projects. */
const V112_recapRowsBase=V103_recapRows;
V103_recapRows=function(r){
 const out=V112_recapRowsBase(r),fee=Math.max(0,Number(r?.taxAdvisorFee||0));if(!fee)return out;
 const i=out.expenses.findIndex(([k])=>k==='Actions & projects');
 if(i>=0){const remaining=Math.max(0,Number(out.expenses[i][1]||0)-fee);if(remaining)out.expenses[i][1]=remaining;else out.expenses.splice(i,1)}
 out.expenses.push(['CPA / tax advisor retainer',fee]);return out
};

const V112_financeRowsBase=financeRows;
financeRows=function(r,full=false){
 let rows=V112_financeRowsBase(r,full),fee=Math.max(0,Number(r?.taxAdvisorFee||0));
 if(fee){
  const i=rows.findIndex(([k])=>k==='CAREER EXPENSE · Actions & projects');
  const remaining=Math.max(0,Number(r.actionExpenses||0)-Number(r.labelPayroll||0)-fee);
  if(i>=0){if(remaining)rows[i]=['CAREER EXPENSE · Actions & projects','−'+money(remaining)];else rows.splice(i,1)}
  const at=rows.findIndex(([k])=>k.startsWith('TAXABLE ·'));rows.splice(at<0?rows.length:at,0,['CAREER EXPENSE · CPA / tax advisor','−'+money(fee)])
 }
 if(full){
  const at=rows.findIndex(([k])=>k.startsWith('TAX INFO ·'));
  rows.splice(at<0?rows.length:at,0,['TAX PLAN · Reserve strategy',r.reserveStrategyName||V112_strategy().name],['TAX PLAN · Reserve coverage',Math.round((Number(r.reserveCoverage)||0)*1000)/10+'%'],['TAX PLAN · Forecast confidence',(r.taxForecastConfidence||V112_forecastConfidence())+'/100'])
 }
 return rows
};

function V112_teamStatus(){
 const bm=V112_businessManager(),cpa=V112_cpa();
 return `<div class="v112-advisor-grid"><article><span>BUSINESS MANAGER</span><strong>${bm?esc(bm.name):'Not retained'}</strong><p>${bm?'Cash-flow context and operating-buffer guidance are active.':'Hire one for stronger liquidity and reserve context.'}</p>${bm?`<small>${bm.skill}/100 skill</small>`:'<button onclick="V096_openBusinessArea(\'Agency\')">Review candidates →</button>'}</article><article><span>CPA / TAX ADVISOR</span><strong>${cpa?esc(cpa.name):'Not retained'}</strong><p>${cpa?`Forecast precision active · ${money(V112_cpaWeeklyFee())}/week.`:'Hire one to narrow forecast uncertainty and review tax classification.'}</p>${cpa?`<small>${cpa.skill}/100 tax skill</small>`:'<button onclick="V096_openBusinessArea(\'Agency\')">Review candidates →</button>'}</article></div>`
}
function V112_taxPlanningDesk(){
 const x=V112_taxForecast(),plan=V112_plan();
 return `<section class="card v112-tax-desk"><header><div><span class="eyebrow">TAX PLANNING 2.0 · FINANCE DESK</span><h2>Choose liquidity. The bill does not disappear.</h2><p>Your reserve strategy controls how much cash ENCORE sets aside between now and year-end. It never changes the underlying estimated liability.</p></div><div class="v112-tax-confidence"><small>FORECAST CONFIDENCE</small><strong>${x.confidence}/100</strong><span>Estimated range ${money(x.low)}–${money(x.high)}</span></div></header><div class="v112-tax-metrics">${[['EST. TAX LIABILITY',money(x.quote.total)],['RESERVE HELD',money(x.reserve)],['EST. TAXABLE INCOME',money(x.taxable)],['OPERATING BUFFER',money(x.cashFloor)]].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><div class="v112-strategy-grid">${Object.values(V112_RESERVE_STRATEGIES).map(o=>`<button class="${plan.reserveStrategy===o.id?'selected':''}" onclick="V112_setReserveStrategy('${o.id}')"><span>${esc(o.name.toUpperCase())}</span><strong>${Math.round(o.multiplier*100)}% reserve target</strong><p>${esc(o.desc)}</p><small>${esc(o.risk)}</small></button>`).join('')}</div><div class="v112-tax-warning"><strong>${x.strategy.name} strategy</strong><p>${x.strategy.id==='aggressive'?'Aggressive does not reduce taxes. It keeps more cash available now and can create a larger year-end catch-up payment.':x.strategy.id==='conservative'?'The extra cushion is still your money; it is simply unavailable as spendable cash while held in the tax reserve.':'The recommended strategy targets the current ENCORE estimate without an added cushion.'}</p></div>${V112_teamStatus()}</section>`
}

const V112_financeScreenBase=financeScreen;
financeScreen=function(){V112_plan();return V112_taxPlanningDesk()+V112_financeScreenBase()};

/* ENCORE 0.9.11 — Entities & Assets 1.0.
   Adds fictionalized business structures, business-use asset classification,
   non-cash depreciation and adjusted-basis sale treatment. This is gameplay,
   not a representation of real tax law. */

const V113_ENTITY_TYPES={
 individual:{id:'individual',name:'Individual / Sole Operation',formation:0,weeklyAdmin:0,minFans:0,useCap:.50,assetCap:2,desc:'Simple and cheap. Best for early careers that do not need a large business-asset footprint.'},
 llc:{id:'llc',name:'Career LLC',formation:2500,weeklyAdmin:100,minFans:25000,useCap:.75,assetCap:8,desc:'Adds cleaner separation and room for a small touring or production asset base.'},
 entertainment:{id:'entertainment',name:'Entertainment Company',formation:20000,weeklyAdmin:500,minFans:250000,useCap:.90,assetCap:20,desc:'Built for a serious artist operation with multiple revenue streams and dedicated career assets.'},
 corporation:{id:'corporation',name:'Entertainment Corporation',formation:100000,weeklyAdmin:2500,minFans:2000000,useCap:1,assetCap:100,desc:'High administrative cost, but supports a large documented business-use asset portfolio.'},
 holding:{id:'holding',name:'Holding Company',formation:500000,weeklyAdmin:10000,minFans:20000000,useCap:1,assetCap:500,desc:'Late-game structure for very large ownership stacks. It prepares ENCORE for future multi-company and legacy systems.'}
};

function V113_entityState(){
 const p=V112_plan();
 if(!p.entity||!V113_ENTITY_TYPES[p.entity])p.entity='individual';
 if(!Array.isArray(p.entityHistory))p.entityHistory=[];
 return p
}
function V113_entity(){return V113_ENTITY_TYPES[V113_entityState().entity]||V113_ENTITY_TYPES.individual}
function V113_businessAssets(){migrateEmpire();return (s.empire.assets||[]).filter(a=>Number(a.businessUsePct||0)>0)}
function V113_entityEligible(id){const e=V113_ENTITY_TYPES[id];return !!e&&s.fans>=e.minFans}
function V113_entityAssetCapacity(id=V113_entity().id){const e=V113_ENTITY_TYPES[id]||V113_ENTITY_TYPES.individual;return e.assetCap}
function V113_entityUseCap(id=V113_entity().id){const e=V113_ENTITY_TYPES[id]||V113_ENTITY_TYPES.individual;return e.useCap}
function V113_entityWeeklyAdmin(){return Math.max(0,Number(V113_entity().weeklyAdmin||0))}

function V113_reviewEntity(id){
 const e=V113_ENTITY_TYPES[id];if(!e)return;
 const eligible=V113_entityEligible(id),current=V113_entity();
 modal(`<span class="eyebrow">BUSINESS STRUCTURE · SIMULATED</span><h2>${esc(e.name)}</h2>${profileRows([['Formation / restructure cost',money(e.formation)],['Weekly administration',money(e.weeklyAdmin)],['Documented business-use ceiling',Math.round(e.useCap*100)+'%'],['Business-use asset capacity',String(e.assetCap)],['Career requirement',e.minFans?compact(e.minFans)+' fans':'None'],['Current structure',current.name]])}<p>${esc(e.desc)}</p><p class="fine">ENCORE structures do not change the federal tax brackets. Their current gameplay effects are administration cost, documented business-use limits and asset capacity. These are fictionalized rules, not real entity or tax advice.</p><div class="controls"><button class="primary" ${eligible&&s.cash>=e.formation&&current.id!==id?'':'disabled'} onclick="V113_formEntity('${id}',true)">${current.id===id?'Already active':eligible?s.cash>=e.formation?'Form / restructure':'Insufficient cash':'Career not eligible'}</button><button class="secondary" onclick="$('modal').close()">Cancel</button></div>`)
}
function V113_formEntity(id,confirmed=false){
 const e=V113_ENTITY_TYPES[id],state=V113_entityState(),current=V113_entity();if(!e||current.id===id)return false;
 if(!V113_entityEligible(id)){toast?.('Your career is not large enough for that structure yet.');return false}
 if(s.cash<e.formation){toast?.('You need '+money(e.formation)+' in spendable cash.');return false}
 if(!confirmed){V113_reviewEntity(id);return false}
 if(e.formation){changeCash(-e.formation);moneyEvent?.('Business structure filing · '+e.name,-e.formation)}
 state.entity=id;state.entityHistory.unshift({week:s.week,from:current.id,to:id,cost:e.formation});state.entityHistory=state.entityHistory.slice(0,30);$('modal')?.close?.();queueSave?.();render();toast?.(e.name+' is now your active business structure.');return true
}

/* Career-specific physical assets. They use the existing Wealth market and
   remain real cash purchases; only the documented business-use portion enters
   depreciation over time. */
const V113_NEW_ASSETS=[
 {id:'tourvan',name:'Touring Sprinter',kind:'Cars',price:95000,drift:-.01,vol:.02,icon:'car',businessEligible:true,usefulLifeWeeks:260,desc:'A dedicated touring van for regional routing, equipment and crew movement.'},
 {id:'tourcoach',name:'Tour Coach',kind:'Cars',price:850000,drift:-.008,vol:.025,icon:'car',businessEligible:true,usefulLifeWeeks:364,desc:'A full touring coach for large routing schedules and road operations.'},
 {id:'studio-loft',name:'Recording Studio Loft',kind:'Property',price:1800000,drift:.0018,vol:.02,icon:'house',rent:0,businessEligible:true,usefulLifeWeeks:1040,desc:'A dedicated recording and production property. Business-use classification can create non-cash depreciation.'},
 {id:'creative-hq',name:'Creative Headquarters',kind:'Property',price:8000000,drift:.0015,vol:.025,icon:'house',rent:0,businessEligible:true,usefulLifeWeeks:1040,desc:'A large office, rehearsal and production campus for an established entertainment operation.'}
];
for(const x of V113_NEW_ASSETS)if(!wealthItems.some(a=>a.id===x.id))wealthItems.push(x);

function V113_assetUseLabel(a){const p=Math.round(Number(a?.businessUsePct||0)*100);return p<=0?'Personal':p>=100?'Business':`Mixed use · ${p}% business`}
function V113_assetBusinessCap(x){return x?.businessEligible?V113_entityUseCap():0}
function V113_businessAssetSlotsRemaining(){return Math.max(0,V113_entityAssetCapacity()-V113_businessAssets().length)}
function V113_depreciableBasis(a){return Math.max(0,cents(Number(a?.basis||0)*clamp(Number(a?.businessUsePct||0),0,1)))}
function V113_adjustedBasis(a){return Math.max(0,cents(Number(a?.basis||0)-Number(a?.depreciationClaimed||0)))}

const V113_assetDetailBase=assetDetail;
assetDetail=function(id){
 if(marketInstrument(id)){tradeForm(id);return}
 const x=wealthItems.find(a=>a.id===id);if(!x?.businessEligible)return V113_assetDetailBase(id);
 const tax=x.kind==='Property'?.02:.08,cap=V113_assetBusinessCap(x),slots=V113_businessAssetSlotsRemaining();
 modal(`${assetPhoto(x)}<span class="eyebrow">BUSINESS-USE ELIGIBLE · ${esc(V113_entity().name.toUpperCase())}</span><h2>${esc(x.name)}</h2><p>${esc(x.desc)}</p>${profileRows([['Price per unit',money(x.price)],['Purchase tax',tax*100+'%'],['Current structure',V113_entity().name],['Maximum documented business use',Math.round(cap*100)+'%'],['Business-asset slots remaining',String(slots)],['Depreciation period',Math.round((x.usefulLifeWeeks||260)/52)+' years']])}<form class="form" onsubmit="V113_reviewBusinessAssetBuy(event,'${id}')"><label>Quantity<input name="qty" type="number" min="1" max="100" step="1" value="1" required></label><label>Use classification<select name="use"><option value="personal">Personal · no depreciation</option><option value="mixed">Mixed use</option><option value="business">Business use</option></select></label><label>Documented business use %<input name="pct" type="number" min="0" max="${Math.round(cap*100)}" step="5" value="${Math.round(Math.min(.5,cap)*100)}"></label><button class="primary">Review purchase</button></form><p class="fine">A business classification does not make the purchase price immediately deductible. ENCORE depreciates the documented business-use basis over the asset’s simulated useful life.</p>`)
};

function V113_reviewBusinessAssetBuy(event,id){
 event.preventDefault();const x=wealthItems.find(a=>a.id===id&&a.businessEligible),f=new FormData(event.target),qty=Number(f.get('qty')),use=String(f.get('use')||'personal');if(!labelActive()||!x||!Number.isInteger(qty)||qty<1||qty>100)return;
 let pct=use==='personal'?0:clamp(Number(f.get('pct')||0)/100,0,V113_assetBusinessCap(x));if(use==='business')pct=V113_assetBusinessCap(x);
 if(pct>0&&V113_businessAssetSlotsRemaining()<qty){toast?.('Your current business structure does not have enough business-asset capacity.');return}
 const subtotal=x.price*qty,tax=subtotal*(x.kind==='Property'?.02:.08);pendingAsset={id,qty,subtotal,tax,total:cents(subtotal+tax),taxUse:pct<=0?'personal':pct>=.999?'business':'mixed',businessUsePct:pct,usefulLifeWeeks:x.usefulLifeWeeks||260};
 modal(`<span class="eyebrow">ASSET ACQUISITION · CLASSIFICATION REVIEW</span><h2>${qty} × ${esc(x.name)}</h2>${profileRows([['Purchase',money(subtotal)],['Purchase tax',money(tax)],['Total cash required',money(subtotal+tax)],['Use classification',pct<=0?'Personal':pct>=.999?'Business':`Mixed · ${Math.round(pct*100)}% business`],['Initial depreciable basis',money((subtotal+tax)*pct)],['Useful life',Math.round((x.usefulLifeWeeks||260)/52)+' years']])}<p>5 energy. The purchase itself is not an immediate career deduction. Only simulated depreciation on the documented business-use basis is deducted over time.</p><button class="primary" onclick="confirmAssetBuy()">Pay & acquire</button><button class="secondary" onclick="$('modal').close()">Cancel</button>`)
}

const V113_confirmAssetBuyBase=confirmAssetBuy;
confirmAssetBuy=function(){
 const p=pendingAsset;if(!p||p.businessUsePct===undefined)return V113_confirmAssetBuyBase();if(!labelActive())return;if(s.cash<p.total){toast('Not enough spendable cash.');return}if(!spend(5))return;
 const x=wealthItems.find(a=>a.id===p.id);if(!x)return;changeCash(-p.total);s.empire.assets.push({id:s.empire.nextId++,item:p.id,name:x.name,kind:x.kind,city:x.kind==='Property'?s.scene.city:null,qty:p.qty,basis:p.total,value:p.subtotal,condition:['Stocks','Bonds','Crypto'].includes(x.kind)?null:100,tenant:null,rent:(x.rent||0)*p.qty,arrears:0,renovated:0,taxUse:p.taxUse,businessUsePct:p.businessUsePct,usefulLifeWeeks:p.usefulLifeWeeks,depreciationClaimed:0});moneyEvent('Purchased '+x.name,-p.total);pendingAsset=null;$('modal').close();render()
};

function V113_weeklyDepreciation(){
 let total=0;
 for(const a of V113_businessAssets()){
  const max=V113_depreciableBasis(a),life=Math.max(52,Number(a.usefulLifeWeeks||260)),claimed=Math.max(0,Number(a.depreciationClaimed||0)),remaining=Math.max(0,max-claimed),weekly=Math.min(remaining,cents(max/life));
  if(weekly>0){a.depreciationClaimed=cents(claimed+weekly);total+=weekly}
 }
 return cents(total)
}
function V113_entityAdminFee(){return V113_entity().id==='individual'?0:V113_entityWeeklyAdmin()}

/* Depreciation is a non-cash deduction. Entity administration is a real cash
   expense. Both flow through the existing taxable-income foundation. */
const V113_closeFinancesBase=closeFinances;
closeFinances=function(royalties,rate){
 migrateFinance?.();const depreciation=V113_weeklyDepreciation(),admin=V113_entityAdminFee();if(!s.finance.week||typeof s.finance.week!=='object')s.finance.week={wages:0,live:0,expenses:0};
 if(depreciation||admin)s.finance.week.expenses=cents((Number(s.finance.week.expenses)||0)+depreciation+admin);
 /* Administration is a true cash cost. Charge it before Tax Planning 2.0
    chooses the reserve target so conservative reserves cannot spend money that
    is already committed to the business structure. */
 if(admin){changeCash(-admin);moneyEvent?.(V113_entity().name+' administration',-admin)}
 const report=V113_closeFinancesBase(royalties,rate);
 if(admin){report.entityAdminFee=admin;report.cash=s.cash}
 report.depreciationDeduction=depreciation;report.entityStructure=V113_entity().name;report.businessAssetCount=V113_businessAssets().length;
 if(report.deductibleBreakdown){const cpa=Math.max(0,Number(report.taxAdvisorFee||0));report.deductibleBreakdown.depreciation=depreciation;report.deductibleBreakdown.entityAdministration=admin;report.deductibleBreakdown.taxAdvisor=cpa;report.deductibleBreakdown.actions=Math.max(0,Number(report.deductibleBreakdown.actions||0)-depreciation-admin-cpa)}
 return report
};

/* Depreciation lowers adjusted basis, so selling a depreciated business-use
   asset can create a larger taxable gain. */
const V113_sellAssetBase=sellAsset;
sellAsset=function(id,confirmed=false){
 const a=s.empire.assets.find(x=>x.id===id);if(!a||!Number(a.depreciationClaimed||0))return V113_sellAssetBase(id,confirmed);if(!labelActive()||a.tenant)return;if(marketInstrument(a.item)){tradeForm(a.item,'sell');return}
 const proceeds=cents(a.value*.98),adjusted=V113_adjustedBasis(a),gain=cents(proceeds-adjusted);
 if(!confirmed){modal(`<span class="eyebrow">BUSINESS ASSET SALE · TAX BASIS</span><h2>Sell ${esc(a.name)}?</h2>${profileRows([['Proceeds after 2% fee',money(proceeds)],['Original cost basis',money(a.basis)],['Depreciation claimed','−'+money(a.depreciationClaimed||0)],['Adjusted tax basis',money(adjusted)],['Taxable gain / loss',money(gain)]])}<p>5 energy. Depreciation already reduced taxable income during ownership, so claimed depreciation also reduces the basis used to calculate the sale gain.</p><button class="primary" onclick="sellAsset(${id},true)">Confirm sale</button>`);return}
 if(!spend(5))return;changeCash(proceeds);s.finance.week.investment=cents((s.finance.week.investment||0)+gain);s.empire.assets=s.empire.assets.filter(x=>x.id!==id);moneyEvent('Sold '+a.name,proceeds);$('modal').close();render()
};

const V113_recapRowsBase=V103_recapRows;
V103_recapRows=function(r){
 const out=V113_recapRowsBase(r),dep=Math.max(0,Number(r?.depreciationDeduction||0)),admin=Math.max(0,Number(r?.entityAdminFee||0));if(!dep&&!admin)return out;
 const i=out.expenses.findIndex(([k])=>k==='Actions & projects');if(i>=0){const remaining=Math.max(0,Number(out.expenses[i][1]||0)-dep-admin);if(remaining)out.expenses[i][1]=remaining;else out.expenses.splice(i,1)}
 if(admin)out.expenses.push(['Business structure administration',admin]);if(dep)out.expenses.push(['Non-cash depreciation',dep]);return out
};

const V113_financeRowsBase=financeRows;
financeRows=function(r,full=false){
 let rows=V113_financeRowsBase(r,full),dep=Math.max(0,Number(r?.depreciationDeduction||0)),admin=Math.max(0,Number(r?.entityAdminFee||0));
 if(dep||admin){
  const i=rows.findIndex(([k])=>k==='CAREER EXPENSE · Actions & projects'),remaining=Math.max(0,Number(r.actionExpenses||0)-Number(r.labelPayroll||0)-Number(r.taxAdvisorFee||0)-dep-admin);
  if(i>=0){if(remaining)rows[i]=['CAREER EXPENSE · Actions & projects','−'+money(remaining)];else rows.splice(i,1)}
  const at=rows.findIndex(([k])=>k.startsWith('TAXABLE ·')),add=[];if(admin)add.push(['CAREER EXPENSE · Entity administration','−'+money(admin)]);if(dep)add.push(['TAX DEDUCTION · Non-cash depreciation','−'+money(dep)]);rows.splice(at<0?rows.length:at,0,...add)
 }
 if(full){const at=rows.findIndex(([k])=>k.startsWith('TAX PLAN ·'));rows.splice(at<0?rows.length:at,0,['BUSINESS STRUCTURE',r.entityStructure||V113_entity().name],['BUSINESS-USE ASSETS',String(r.businessAssetCount??V113_businessAssets().length)])}
 return rows
};

function V113_entityCard(){
 const current=V113_entity(),assets=V113_businessAssets(),claimed=assets.reduce((n,a)=>n+Math.max(0,Number(a.depreciationClaimed||0)),0);
 return `<section class="card v113-entity-card"><header><div><span class="eyebrow">ENTITY & ASSET PLANNING · SIMULATED</span><h2>${esc(current.name)}</h2><p>${esc(current.desc)}</p></div><div><small>BUSINESS-USE ASSETS</small><strong>${assets.length} / ${current.assetCap}</strong><span>${money(claimed)} depreciation claimed to date</span></div></header><div class="v113-entity-grid">${Object.values(V113_ENTITY_TYPES).map(e=>`<button class="${current.id===e.id?'selected':''}" onclick="V113_reviewEntity('${e.id}')"><span>${esc(e.name)}</span><strong>${money(e.weeklyAdmin)}/wk admin</strong><small>${Math.round(e.useCap*100)}% use ceiling · ${e.assetCap} assets${e.minFans?' · '+compact(e.minFans)+' fans':''}</small></button>`).join('')}</div><p class="fine">Structures do not change ENCORE’s tax brackets. Business-use depreciation only applies to eligible assets and lowers adjusted basis for a later sale.</p></section>`
}
function V113_businessAssetPanel(){
 const assets=V113_businessAssets();if(!assets.length)return `<section class="card v113-business-assets"><span class="eyebrow">BUSINESS ASSETS</span><h2>No depreciable career assets yet.</h2><p>Touring vehicles and dedicated studio / headquarters properties can be classified for personal, mixed or business use when purchased.</p></section>`;
 return `<section class="card v113-business-assets"><span class="eyebrow">BUSINESS ASSETS · TAX BASIS</span><h2>${assets.length} documented asset${assets.length===1?'':'s'}</h2>${assets.map(a=>`<div class="project-row"><div><strong>${esc(a.name)}</strong><small>${esc(V113_assetUseLabel(a))} · Basis ${money(a.basis)} · Claimed ${money(a.depreciationClaimed||0)} · Adjusted ${money(V113_adjustedBasis(a))}</small></div><button class="secondary" onclick="holdingDetail(${a.id})">Manage</button></div>`).join('')}</section>`
}

const V113_financeScreenBase=financeScreen;
financeScreen=function(){V113_entityState();return V113_entityCard()+V113_financeScreenBase()};
const V113_wealthInventoryBase=wealthInventory;
wealthInventory=function(){V113_entityState();return V113_businessAssetPanel()+V113_wealthInventoryBase()};

/* ENCORE 0.9.12 — Music Platform Ecosystem 1.0.
   Restores separate artist profiles for multiple fictional music services, ties
   them to the authoritative stream count, and lets PULSE/video discovery feed
   future catalog performance without duplicating current-week royalties. */

const V114_AUDIO_PLATFORMS={
 vybe:{id:'vybe',name:'VYBE',tag:'PLAYLIST / ALGORITHM',baseShare:.36,desc:'Fast discovery, saves and playlist momentum. Commercial appeal and viral ability matter most.'},
 muse:{id:'muse',name:'MUSE',tag:'ALBUM / LIBRARY',baseShare:.28,desc:'Album listening, library adds and editorial support. Quality, loyalty and complete projects matter most.'},
 amp:{id:'amp',name:'AMP',tag:'COMMUNITY / EARLY DISCOVERY',baseShare:.18,desc:'Follower-heavy discovery and repost culture. Emerging artists and direct fan activity can overperform here.'},
 worldwave:{id:'worldwave',name:'WORLDWAVE',tag:'GLOBAL / RADIO',baseShare:.18,desc:'Global crossover and radio-style reach. Reputation, broad appeal and durable records matter most.'}
};
const V114_PLATFORM_IDS=Object.keys(V114_AUDIO_PLATFORMS);
const V114_VIDEO_FORMATS={
 visualizer:{id:'visualizer',name:'Visualizer',minimum:1500,energy:10,reach:.55,decay:.76},
 performance:{id:'performance',name:'Performance video',minimum:12000,energy:15,reach:.9,decay:.80},
 official:{id:'official',name:'Official music video',minimum:60000,energy:20,reach:1.35,decay:.84},
 cinematic:{id:'cinematic',name:'Cinematic video',minimum:250000,energy:30,reach:2.05,decay:.88}
};
let V114_platformTab='Overview';
let V114_pendingVideo=null;

function V114_num(v){const n=Number(v);return Number.isFinite(n)?n:0}
function V114_serviceSeed(id,fans){const rate={vybe:.55,muse:.30,amp:.18,worldwave:.14}[id]||.2;return Math.max(0,Math.round(Math.max(0,fans)*rate))}
function V114_emptyService(id,fans=0){return {id,followers:V114_serviceSeed(id,fans),lifetimeStreams:0,currentWeekStreams:0,monthlyListeners:0,saves:0,libraryAdds:0,reposts:0,radioSpins:0,editorialAdds:0,playlistReach:0,weekly:[],placements:[]}}
function V114_trackService(){return {lifetime:0,thisWeek:0,lastWeek:0,saves:0,libraryAdds:0,reposts:0,radioSpins:0}}
function V114_state(state=s){
 if(!state.musicPlatforms||typeof state.musicPlatforms!=='object')state.musicPlatforms={version:1,migratedAtWeek:state.week||1,services:{},tracks:{},video:{subscribers:Math.max(0,Math.round((state.fans||0)*.2)),lifetimeViews:0,currentWeekViews:0,lifetimeRevenue:0,nextId:1,videos:[],weekly:[]},events:[]};
 const p=state.musicPlatforms;p.version=1;p.services=p.services&&typeof p.services==='object'?p.services:{};p.tracks=p.tracks&&typeof p.tracks==='object'?p.tracks:{};p.events=Array.isArray(p.events)?p.events:[];
 for(const id of V114_PLATFORM_IDS){const old=p.services[id]&&typeof p.services[id]==='object'?p.services[id]:V114_emptyService(id,state.fans||0);p.services[id]={...V114_emptyService(id,0),...old,id,weekly:Array.isArray(old.weekly)?old.weekly:[],placements:Array.isArray(old.placements)?old.placements:[]}}
 if(!p.video||typeof p.video!=='object')p.video={subscribers:Math.max(0,Math.round((state.fans||0)*.2)),lifetimeViews:0,currentWeekViews:0,lifetimeRevenue:0,nextId:1,videos:[],weekly:[]};
 p.video.videos=Array.isArray(p.video.videos)?p.video.videos:[];p.video.weekly=Array.isArray(p.video.weekly)?p.video.weekly:[];p.video.nextId=Math.max(1,Math.floor(V114_num(p.video.nextId)||1));
 if(!p.seeded){V114_seedExistingCareer(state,p);p.seeded=true}
 return p
}
function V114_songAlbumSignal(track,state=s){
 const albums=Array.isArray(state.albums)?state.albums:[];
 for(const a of albums){const tracks=Array.isArray(a.tracks)?a.tracks:Array.isArray(a.songs)?a.songs:[];if(tracks.some(x=>Number(x?.id??x)===Number(track.id)))return 1}
 return track.albumBoost?1:0
}
function V114_socialSignal(track){try{return typeof socialSongBoost==='function'?clamp(V114_num(socialSongBoost(track)),0,.2):0}catch{return 0}}
function V114_audioWeights(track,state=s){
 const quality=clamp(V114_num(track.quality||50),0,100)/100,commercial=clamp(V114_num(track.commercial||50),0,100)/100,viral=clamp(typeof level==='function'?V114_num(level('viralAbility')):50,0,100)/100,loyalty=clamp(V114_num(state.loyalty||0),0,100)/100,reputation=clamp(V114_num(state.reputation||0),0,100)/100,album=V114_songAlbumSignal(track,state),social=V114_socialSignal(track),emerging=1-reputation;
 const raw={
  vybe:V114_AUDIO_PLATFORMS.vybe.baseShare*(.75+commercial*.42+viral*.18+social*1.35),
  muse:V114_AUDIO_PLATFORMS.muse.baseShare*(.78+quality*.42+album*.24+loyalty*.13),
  amp:V114_AUDIO_PLATFORMS.amp.baseShare*(.74+quality*.18+emerging*.22+social*.85),
  worldwave:V114_AUDIO_PLATFORMS.worldwave.baseShare*(.76+reputation*.34+commercial*.14+quality*.12)
 };
 const total=Object.values(raw).reduce((n,v)=>n+v,0)||1;for(const id of V114_PLATFORM_IDS)raw[id]/=total;return raw
}
function V114_allocate(total,weights){
 const n=Math.max(0,Math.round(V114_num(total))),out={},ids=[...V114_PLATFORM_IDS];let used=0;
 ids.forEach((id,i)=>{const value=i===ids.length-1?n-used:Math.max(0,Math.floor(n*Math.max(0,V114_num(weights[id]))));out[id]=value;used+=value});return out
}
function V114_trackRow(state,track){
 const p=V114_state(state),key=String(track.id);if(!p.tracks[key])p.tracks[key]={songId:track.id,title:track.title||'Untitled',services:{},weekly:[],lastLift:0};const row=p.tracks[key];row.title=track.title||row.title;row.services=row.services&&typeof row.services==='object'?row.services:{};for(const id of V114_PLATFORM_IDS)row.services[id]={...V114_trackService(),...(row.services[id]||{})};row.weekly=Array.isArray(row.weekly)?row.weekly:[];return row
}
function V114_seedExistingCareer(state,p){
 for(const track of (state.songs||[]).filter(x=>x.released)){
  const row=V114_trackRow(state,track),weights=V114_audioWeights(track,state),life=V114_allocate(Math.max(0,V114_num(track.total)),weights),current=V114_allocate(Math.max(0,V114_num(track.streams)),weights);
  for(const id of V114_PLATFORM_IDS){const svc=p.services[id],ts=row.services[id];ts.lifetime=life[id];ts.thisWeek=current[id];ts.lastWeek=state.week||1;svc.lifetimeStreams+=life[id];svc.currentWeekStreams+=current[id]}
 }
 for(const id of V114_PLATFORM_IDS){const svc=p.services[id],listeners=Math.round(svc.currentWeekStreams/(id==='muse'?2.1:id==='amp'?1.55:1.8));svc.monthlyListeners=Math.max(0,Math.round(listeners*2.4))}
}
function V114_monthlyListeners(service){
 const recent=(service.weekly||[]).slice(-4),sum=recent.reduce((n,x)=>n+V114_num(x.listeners),0),peak=recent.reduce((n,x)=>Math.max(n,V114_num(x.listeners)),0);return Math.max(0,Math.round(peak+(sum-peak)*.56))
}
function V114_addEvent(p,event){p.events.unshift({...event,week:s.week});p.events=p.events.slice(0,80)}
function V114_hasPlacement(service,key){return (service.placements||[]).some(x=>x.key===key&&x.expires>=s.week)}
function V114_place(p,serviceId,track,name,lift,weeks=4){
 const service=p.services[serviceId],key=serviceId+':'+track.id+':'+name;if(V114_hasPlacement(service,key))return 0;
 const item={key,songId:track.id,title:track.title,name,start:s.week,expires:s.week+weeks-1,lift};service.placements.unshift(item);service.placements=service.placements.filter(x=>x.expires>=s.week-8).slice(0,40);V114_addEvent(p,{type:'placement',service:serviceId,songId:track.id,text:`${track.title} entered ${name} on ${V114_AUDIO_PLATFORMS[serviceId].name}.`});return lift
}
function V114_placementLift(p,track,alloc){
 const quality=clamp(V114_num(track.quality||50),0,100),commercial=clamp(V114_num(track.commercial||50),0,100),rep=clamp(V114_num(s.reputation||0),0,100),social=V114_socialSignal(track),newRelease=s.week-V114_num(track.released||s.week)<=4;let lift=0;
 if(commercial>=68&&alloc.vybe>=Math.max(3000,(s.fans||0)*.08))lift+=V114_place(p,'vybe',track,alloc.vybe>=250000?'Top Rotation':'Rising Rotation',alloc.vybe>=250000?.10:.06,4);
 if(quality>=75&&newRelease&&alloc.muse>=1500){p.services.muse.editorialAdds++;lift+=V114_place(p,'muse',track,V114_songAlbumSignal(track)?'Album Spotlight':'Editors’ Table',.05,4)}
 if((social>=.035||rep<35)&&alloc.amp>=1000){p.services.amp.reposts+=Math.max(1,Math.round(Math.sqrt(alloc.amp)/8));lift+=V114_place(p,'amp',track,'Community Repost Network',.04,3)}
 if(rep>=45&&quality>=70&&alloc.worldwave>=5000){p.services.worldwave.radioSpins+=Math.max(1,Math.round(Math.sqrt(alloc.worldwave)/5));lift+=V114_place(p,'worldwave',track,'Global Rotation',.05,5)}
 return clamp(lift,0,.18)
}
function V114_settleAudio(state=s){
 const p=V114_state(state),summary={week:state.week,streams:0,followers:0,placements:0,videoViews:0,videoRevenue:0,top:null};for(const id of V114_PLATFORM_IDS)p.services[id].currentWeekStreams=0;
 let topStreams=-1;
 for(const track of (state.songs||[]).filter(x=>x.released)){
  const total=Math.max(0,Math.round(V114_num(track.streams))),weights=V114_audioWeights(track,state),alloc=V114_allocate(total,weights),row=V114_trackRow(state,track),quality=clamp(V114_num(track.quality||50),0,100)/100,loyalty=clamp(V114_num(state.loyalty||0),0,100)/100,social=V114_socialSignal(track);let lift=0;
  for(const id of V114_PLATFORM_IDS){
   const cfg=V114_AUDIO_PLATFORMS[id],svc=p.services[id],ts=row.services[id],streams=alloc[id],avg=id==='muse'?2.15:id==='amp'?1.5:id==='worldwave'?1.9:1.75,listeners=Math.max(0,Math.round(streams/avg)),conversion={vybe:.006,muse:.0045,amp:.0085,worldwave:.0035}[id],gained=Math.max(0,Math.round(listeners*(conversion+quality*.002+loyalty*.001))),saveRate=.018+quality*.035+loyalty*.012;
   ts.thisWeek=streams;ts.lastWeek=state.week;ts.lifetime=Math.max(0,V114_num(ts.lifetime)+streams);svc.currentWeekStreams+=streams;svc.lifetimeStreams=Math.max(0,V114_num(svc.lifetimeStreams)+streams);svc.followers=Math.max(0,V114_num(svc.followers)+gained);summary.followers+=gained;
   if(id==='vybe'){const saves=Math.round(streams*(saveRate+social*.025));ts.saves+=saves;svc.saves+=saves;svc.playlistReach=Math.max(svc.playlistReach,Math.round(listeners*(1+social*2)))}
   if(id==='muse'){const adds=Math.round(listeners*(.025+quality*.05));ts.libraryAdds+=adds;svc.libraryAdds+=adds}
   if(id==='amp'){const reposts=Math.round(listeners*(.003+social*.03));ts.reposts+=reposts;svc.reposts+=reposts}
   if(id==='worldwave'){const spins=Math.max(0,Math.round(Math.sqrt(streams)*(.03+V114_num(state.reputation||0)/1800)));ts.radioSpins+=spins;svc.radioSpins+=spins}
   svc.weekly.push({week:state.week,streams,listeners,followers:gained});svc.weekly=svc.weekly.slice(-12);svc.monthlyListeners=V114_monthlyListeners(svc)
  }
  lift=V114_placementLift(p,track,alloc);row.lastLift=lift;row.weekly.push({week:state.week,total,allocation:alloc,lift});row.weekly=row.weekly.slice(-12);summary.streams+=total;summary.placements+=lift>0?1:0;if(total>topStreams){topStreams=total;summary.top={songId:track.id,title:track.title,streams:total}}
  track.platformLiftNext=lift
 }
 return summary
}
function V114_videoBudgetFactor(video){return clamp(.75+Math.log10(1+Math.max(0,V114_num(video.budget))/Math.max(1,V114_num(V114_VIDEO_FORMATS[video.format]?.minimum||1)))*.42,.75,1.75)}
function V114_settleVideo(state=s){
 const p=V114_state(state),v=p.video;v.currentWeekViews=0;let revenueTotal=0,totalSubscribers=0,totalLift={};
 for(const video of v.videos){const format=V114_VIDEO_FORMATS[video.format]||V114_VIDEO_FORMATS.performance,track=(state.songs||[]).find(x=>Number(x.id)===Number(video.songId));if(!track)continue;const age=Math.max(0,state.week-video.week),social=V114_socialSignal(track),base=Math.max(120,Math.max(V114_num(track.streams)*.36,V114_num(state.fans)*.055)),decay=Math.pow(format.decay,age),views=Math.max(0,Math.round(base*format.reach*V114_videoBudgetFactor(video)*decay*(1+social*2.4)*(video.quality||1)));video.thisWeekViews=views;video.lifetimeViews=Math.max(0,V114_num(video.lifetimeViews)+views);v.currentWeekViews+=views;v.lifetimeViews=Math.max(0,V114_num(v.lifetimeViews)+views);const subs=Math.max(0,Math.round(views*(.0025+clamp(typeof level==='function'?V114_num(level('charisma')):50,0,100)*.000035)));v.subscribers+=subs;totalSubscribers+=subs;const revenue=cents(views*.003);video.lifetimeRevenue=cents(V114_num(video.lifetimeRevenue)+revenue);v.lifetimeRevenue=cents(V114_num(v.lifetimeRevenue)+revenue);revenueTotal=cents(revenueTotal+revenue);const spill=clamp(views/Math.max(10000,V114_num(track.streams)*22),0,.10);totalLift[track.id]=Math.max(totalLift[track.id]||0,spill)}
 if(revenueTotal>0){changeCash(revenueTotal);const previous=typeof V110_incomeContext!=='undefined'?V110_incomeContext:null;if(typeof V110_incomeContext!=='undefined')V110_incomeContext={family:'platform',category:'video',name:'FRAME',phase:'Creator revenue'};try{recordIncome('media',revenueTotal)}finally{if(typeof V110_incomeContext!=='undefined')V110_incomeContext=previous}moneyEvent?.('FRAME creator revenue',revenueTotal)}
 v.weekly.push({week:state.week,views:v.currentWeekViews,subscribers:totalSubscribers,revenue:revenueTotal});v.weekly=v.weekly.slice(-12);return {views:v.currentWeekViews,subscribers:totalSubscribers,revenue:revenueTotal,lifts:totalLift}
}
function V114_applyNextWeekLift(state,audio,video){
 for(const track of (state.songs||[]).filter(x=>x.released)){
  const audioLift=clamp(V114_num(track.platformLiftNext),0,.18),videoLift=clamp(V114_num(video?.lifts?.[track.id]),0,.10),combined=clamp(audioLift+videoLift,0,.25);track.platformLiftNext=combined;if(combined>0&&Number.isFinite(Number(track.organic)))track.organic=Math.max(8,V114_num(track.organic)*(1+combined));const row=V114_state(state).tracks[String(track.id)];if(row)row.lastLift=combined
 }
}
function V114_settlePlatforms(state=s){const p=V114_state(state),audio=V114_settleAudio(state),video=V114_settleVideo(state);V114_applyNextWeekLift(state,audio,video);const summary={...audio,videoViews:video.views,videoRevenue:video.revenue,videoSubscribers:video.subscribers};p.lastWeek={...summary};V114_addEvent(p,{type:'week',text:`Platform week closed with ${compact(summary.streams)} audio streams and ${compact(summary.videoViews)} video views.`});return summary}

/* Seed the system before the authoritative release engine mutates lifetime totals,
   then allocate that week's already-computed streams afterward. */
const V114_releaseSettleBase=globalThis.ENCORE_RELEASES?.settle;
if(V114_releaseSettleBase)globalThis.ENCORE_RELEASES.settle=function(state,h){V114_state(state);const result=V114_releaseSettleBase(state,h);V114_settlePlatforms(state);return result};
const V114_weeklySettleBase=globalThis.ENCORE_WEEKLY?.settle;
if(V114_weeklySettleBase)globalThis.ENCORE_WEEKLY.settle=function(state,h){const out=V114_weeklySettleBase(state,h);if(state.lastReport)state.lastReport.platforms=V114_state(state).lastWeek||null;return out};

function V114_topTracks(serviceId,limit=8){
 const p=V114_state();return Object.values(p.tracks).map(row=>({row,stats:row.services?.[serviceId]||V114_trackService()})).filter(x=>x.stats.lifetime>0||x.stats.thisWeek>0).sort((a,b)=>b.stats.thisWeek-a.stats.thisWeek||b.stats.lifetime-a.stats.lifetime).slice(0,limit)
}
function V114_activePlacements(serviceId){return (V114_state().services[serviceId].placements||[]).filter(x=>x.expires>=s.week).sort((a,b)=>b.lift-a.lift)}
function V114_platformMetricRows(id,svc){
 if(id==='vybe')return [['Monthly listeners',compact(svc.monthlyListeners)],['Followers',compact(svc.followers)],['Saves',compact(svc.saves)],['Playlist reach',compact(svc.playlistReach)]];
 if(id==='muse')return [['Monthly listeners',compact(svc.monthlyListeners)],['Followers',compact(svc.followers)],['Library adds',compact(svc.libraryAdds)],['Editorial placements',String(svc.editorialAdds)]];
 if(id==='amp')return [['Monthly listeners',compact(svc.monthlyListeners)],['Followers',compact(svc.followers)],['Reposts',compact(svc.reposts)],['Current-week streams',compact(svc.currentWeekStreams)]];
 return [['Monthly listeners',compact(svc.monthlyListeners)],['Followers',compact(svc.followers)],['Radio spins',compact(svc.radioSpins)],['Current-week streams',compact(svc.currentWeekStreams)]]
}
function V114_platformPanel(id){
 const p=V114_state(),cfg=V114_AUDIO_PLATFORMS[id],svc=p.services[id],tracks=V114_topTracks(id),placements=V114_activePlacements(id);return `<section class="v114-profile" data-platform="${id}"><header><div><span class="eyebrow">${esc(cfg.tag)}</span><h2>${esc(cfg.name)}</h2><p>${esc(cfg.desc)}</p></div><div class="v114-profile-week"><small>THIS WEEK</small><strong>${compact(svc.currentWeekStreams)}</strong><span>streams allocated from your existing ENCORE total</span></div></header><div class="v114-metrics">${V114_platformMetricRows(id,svc).map(([k,v])=>`<div><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="v114-profile-grid"><section><span class="eyebrow">TOP TRACKS · THIS WEEK</span>${tracks.length?tracks.map((x,i)=>`<div class="v114-track-row"><b>${i+1}</b><span><strong>${esc(x.row.title)}</strong><small>${compact(x.stats.thisWeek)} this week · ${compact(x.stats.lifetime)} on ${esc(cfg.name)}</small></span></div>`).join(''):'<p>No released music has activity on this profile yet.</p>'}</section><aside><span class="eyebrow">ACTIVE DISCOVERY</span>${placements.length?placements.map(x=>`<article><strong>${esc(x.name)}</strong><span>${esc(x.title)}</span><small>Through Week ${x.expires} · +${Math.round(x.lift*100)}% discovery signal</small></article>`).join(''):'<p>No active placement. Strong records can earn discovery organically.</p>'}</aside></div></section>`
}
function V114_totalFollowers(){const p=V114_state();return V114_PLATFORM_IDS.reduce((n,id)=>n+V114_num(p.services[id].followers),0)+V114_num(p.video.subscribers)}
function V114_overview(){
 const p=V114_state(),released=(s.songs||[]).filter(x=>x.released),last=p.lastWeek||{},top=last.top,events=p.events.filter(x=>x.type==='placement').slice(0,5);return `<section class="v114-overview"><header><div><span class="eyebrow">MUSIC PLATFORM ECOSYSTEM 1.0</span><h2>One career. Different audiences.</h2><p>Your authoritative ENCORE stream total is split across four platform profiles. The split changes by record, career position and fan behavior; the system never duplicates a stream just to make the profiles look bigger.</p></div><div class="v114-overview-total"><small>COMBINED PLATFORM FOLLOWING</small><strong>${compact(V114_totalFollowers())}</strong><span>audio followers + FRAME subscribers</span></div></header><div class="v114-overview-metrics">${[['AUDIO STREAMS · LAST WEEK',compact(last.streams||s.streams||0)],['VIDEO VIEWS · LAST WEEK',compact(last.videoViews||0)],['ACTIVE RELEASES',String(released.length)],['NEXT-WEEK DISCOVERY',top?esc(top.title):'No active leader']].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><div class="v114-service-overview">${V114_PLATFORM_IDS.map(id=>{const cfg=V114_AUDIO_PLATFORMS[id],svc=p.services[id];return `<button data-platform="${id}" onclick="V114_setTab('${id}')"><span>${esc(cfg.tag)}</span><strong>${esc(cfg.name)}</strong><b>${compact(svc.monthlyListeners)}</b><small>monthly listeners</small></button>`}).join('')}<button data-platform="frame" onclick="V114_setTab('frame')"><span>VIDEO / VISUALS</span><strong>FRAME</strong><b>${compact(p.video.subscribers)}</b><small>subscribers</small></button></div><section class="v114-system-loop"><span class="eyebrow">WHY THE PROFILES MATTER</span><div><article><b>01</b><strong>PULSE creates attention.</strong><p>Linked posts increase discovery weight for the song instead of adding fake streams.</p></article><article><b>02</b><strong>Each service reacts differently.</strong><p>Commercial appeal can dominate VYBE while quality, albums or early fan activity win elsewhere.</p></article><article><b>03</b><strong>Placements create future lift.</strong><p>Editorial, repost and radio support can improve the song’s next-week organic stream base.</p></article><article><b>04</b><strong>FRAME can revive catalog.</strong><p>Video views earn media revenue and create a bounded spillover into future song discovery.</p></article></div></section>${events.length?`<section class="v114-recent"><span class="eyebrow">RECENT PLATFORM MOMENTS</span>${events.map(e=>`<p><strong>Week ${e.week}</strong> · ${esc(e.text)}</p>`).join('')}</section>`:''}<section class="v114-pulse-link"><div><span class="eyebrow">PULSE CONNECTION</span><strong>${compact(s.social?.followers||0)} followers</strong><p>Social followers are not music-platform listeners. PULSE is an attention source that can push a specific song into platform discovery when you link it.</p></div><button class="secondary" onclick="openDestination('Social')">Open PULSE →</button></section></section>`
}
function V114_videoPage(){
 const p=V114_state(),v=p.video,videos=v.videos.slice().sort((a,b)=>b.week-a.week);return `<section class="v114-profile v114-frame" data-platform="frame"><header><div><span class="eyebrow">VIDEO / VISUALS</span><h2>FRAME</h2><p>Videos are separate career assets. Production costs real cash and energy, videos can earn creator revenue, and strong viewing can push listeners back toward the linked song.</p></div><div class="v114-profile-week"><small>THIS WEEK</small><strong>${compact(v.currentWeekViews||0)}</strong><span>video views</span></div></header><div class="v114-metrics">${[['Subscribers',compact(v.subscribers)],['Lifetime views',compact(v.lifetimeViews)],['Creator revenue',money(v.lifetimeRevenue)],['Published videos',String(videos.length)]].map(([k,val])=>`<div><small>${k}</small><strong>${val}</strong></div>`).join('')}</div><div class="v114-video-actions"><button class="primary" ${(s.songs||[]).some(x=>x.released)?'':'disabled'} onclick="V114_openVideoStudio()">Plan a video</button><p>Budget improves reach, but a weak song is still a weak foundation. Video revenue is recorded as media income and video production as a career expense.</p></div><div class="v114-video-list">${videos.length?videos.map(x=>{const song=(s.songs||[]).find(y=>Number(y.id)===Number(x.songId));return `<article><div><span>${esc(V114_VIDEO_FORMATS[x.format]?.name||'Video')}</span><strong>${esc(song?.title||x.title||'Catalog video')}</strong><small>Released Week ${x.week} · Budget ${money(x.budget)}</small></div><div><b>${compact(x.thisWeekViews||0)}</b><small>this week</small><b>${compact(x.lifetimeViews||0)}</b><small>lifetime views</small></div></article>`}).join(''):'<p>No videos yet. Release a song, then build its visual campaign here.</p>'}</div></section>`
}
function V114_setTab(id){if(!['Overview',...V114_PLATFORM_IDS,'frame'].includes(id))return;V114_platformTab=id;render()}
function V114_tabs(){return `<nav class="v114-tabs" aria-label="Music platform profiles">${[['Overview','Overview'],...V114_PLATFORM_IDS.map(id=>[id,V114_AUDIO_PLATFORMS[id].name]),['frame','FRAME']].map(([id,name])=>`<button class="${V114_platformTab===id?'selected':''}" onclick="V114_setTab('${id}')">${esc(name)}</button>`).join('')}</nav>`}
function V114_platformPage(){V114_state();const body=V114_platformTab==='Overview'?V114_overview():V114_platformTab==='frame'?V114_videoPage():V114_platformPanel(V114_platformTab);return head('Every platform tells a different story.','Music platforms.',`<span class="pill">${compact(V114_totalFollowers())} combined follows</span>`)+V114_tabs()+body}

function V114_openVideoStudio(){
 const released=(s.songs||[]).filter(x=>x.released);if(!released.length){toast?.('Release a song before planning a video.');return}
 modal(`<span class="eyebrow">FRAME · VIDEO STUDIO</span><h2>Build a visual around a record.</h2><form class="form" onsubmit="V114_reviewVideo(event)"><label>Song<select name="song">${released.slice().sort((a,b)=>(b.streams||0)-(a.streams||0)).map(x=>`<option value="${x.id}">${esc(x.title)} · ${compact(x.streams||0)} current weekly streams</option>`).join('')}</select></label><label>Format<select name="format">${Object.values(V114_VIDEO_FORMATS).map(x=>`<option value="${x.id}">${esc(x.name)} · minimum ${money(x.minimum)} · ${x.energy} energy</option>`).join('')}</select></label><label>Production budget<input name="budget" type="number" min="1500" max="50000000" step="500" value="60000" required></label><p class="fine">The selected format sets a minimum viable budget. Spending above it improves reach with diminishing returns; it does not guarantee virality.</p><button class="primary">Review production</button></form>`)
}
function V114_reviewVideo(event){
 event.preventDefault();const f=new FormData(event.target),track=(s.songs||[]).find(x=>Number(x.id)===Number(f.get('song'))&&x.released),format=V114_VIDEO_FORMATS[String(f.get('format'))],budget=Math.max(0,Math.round(Number(f.get('budget'))||0));if(!track||!format)return;if(budget<format.minimum){toast?.(format.name+' needs at least '+money(format.minimum)+'.');return}const factor=V114_videoBudgetFactor({format:format.id,budget}),base=Math.max(120,Math.max(V114_num(track.streams)*.36,V114_num(s.fans)*.055)),projected=Math.round(base*format.reach*factor),low=Math.round(projected*.65),high=Math.round(projected*1.35);V114_pendingVideo={songId:track.id,title:track.title,format:format.id,budget,energy:format.energy,quality:clamp(.85+V114_num(track.quality||50)/400,.85,1.1)};modal(`<span class="eyebrow">FRAME · PRODUCTION REVIEW</span><h2>${esc(format.name)} · ${esc(track.title)}</h2>${profileRows([['Production budget',money(budget)],['Energy',format.energy],['Projected first-week views',compact(low)+' – '+compact(high)],['Current song streams',compact(track.streams||0)],['Potential catalog effect','Up to +10% next-week discovery from video spillover']])}<p>The view range is a forecast, not a guarantee. PULSE activity, song demand and production level still affect the actual result.</p><div class="controls"><button class="primary" onclick="V114_publishVideo()">Fund & publish</button><button class="secondary" onclick="V114_openVideoStudio()">Change plan</button></div>`)
}
function V114_publishVideo(){
 const plan=V114_pendingVideo;if(!plan)return false;if(s.cash<plan.budget){toast?.('You need '+money(plan.budget)+' in spendable cash.');return false}if(!spend(plan.energy))return false;migrateFinance?.();if(!s.finance.week||typeof s.finance.week!=='object')s.finance.week={wages:0,live:0,expenses:0};changeCash(-plan.budget);s.finance.week.expenses=cents(V114_num(s.finance.week.expenses)+plan.budget);moneyEvent?.('FRAME video production · '+plan.title,-plan.budget);const v=V114_state().video;v.videos.push({id:v.nextId++,songId:plan.songId,title:plan.title,format:plan.format,budget:plan.budget,quality:plan.quality,week:s.week,thisWeekViews:0,lifetimeViews:0,lifetimeRevenue:0});v.videos=v.videos.slice(-60);V114_addEvent(V114_state(),{type:'video',songId:plan.songId,text:`${V114_VIDEO_FORMATS[plan.format].name} for ${plan.title} published on FRAME.`});V114_pendingVideo=null;$('modal')?.close?.();queueSave?.();render();toast?.('Video published. Performance resolves at week close.');return true
}

/* Separate platform-generated media revenue from vague commercial income in the
   recap while preserving the authoritative media total and tax math. */
function V114_platformIncomeDetails(r){return (Array.isArray(r?.dealIncomeDetails)?r.dealIncomeDetails:[]).filter(x=>x.family==='platform'&&V114_num(x.amount)>0)}
const V114_recapRowsBase=V103_recapRows;
V103_recapRows=function(r){const out=V114_recapRowsBase(r),details=V114_platformIncomeDetails(r),video=details.reduce((n,x)=>n+V114_num(x.amount),0);if(!video)return out;const generic=out.income.findIndex(([k])=>k==='Other media & commercial'||k==='Media & commercial');if(generic>=0){const left=Math.max(0,V114_num(out.income[generic][1])-video);if(left)out.income[generic][1]=left;else out.income.splice(generic,1)}out.income.push(['Video platform revenue',video]);return out};
const V114_financeRowsBase=financeRows;
financeRows=function(r,full=false){let rows=V114_financeRowsBase(r,full),details=V114_platformIncomeDetails(r);if(full&&details.length){let at=rows.findIndex(([k])=>String(k).includes('media')||String(k).includes('Media'));if(at<0)at=1;for(const x of details)rows.splice(++at,0,[`↳ ${x.name} · ${x.phase}`,money(x.amount)])}return rows};

/* Late routing keeps the new ecosystem out of the already crowded Business HQ. */
if(typeof destinations!=='undefined'&&!destinations.some(x=>x[2]==='Platforms'))destinations.splice(Math.max(0,destinations.findIndex(x=>x[2]==='Campaigns')),0,['Music platforms','Music','Platforms','Separate streaming and video artist profiles',3]);
const V114_openDestinationBase=openDestination;
openDestination=function(id){if(id==='Platforms'){careerTab='Platforms';tab='Career';render();window.scrollTo?.(0,0);return}return V114_openDestinationBase(id)};
const V114_careerBase=career;
career=function(){if(careerTab==='Platforms')return V114_platformPage();return V114_careerBase()};

/* ENCORE 0.9.12 migration + navigation guard.
   Existing careers can already contain released songs when Music Platform
   Ecosystem first initializes. Mark the in-progress seed before nested track
   initialization so the migration remains one-pass instead of recursing.

   Visual System 2.0 renders the More directory from V080_destinations rather
   than the older destinations array. Keep both registries synchronized so the
   Music Platforms screen is always discoverable after deployment. */
const V114_stateSeedBase=V114_state;
V114_state=function(state=s){
 const p=state?.musicPlatforms;
 if(p&&p.seeded!==true)p.seeded=true;
 return V114_stateSeedBase(state)
};

const V114_PLATFORM_DESTINATION=['Music platforms','Music','Platforms','Streaming services, playlists, video and audience profiles',3];
function V114_installPlatformDestination(rows){
 if(!Array.isArray(rows)||rows.some(x=>x?.[2]==='Platforms'))return;
 const after=rows.findIndex(x=>x?.[2]==='Releases');
 rows.splice(after>=0?after+1:rows.length,0,[...V114_PLATFORM_DESTINATION]);
}
if(typeof destinations!=='undefined')V114_installPlatformDestination(destinations);
if(typeof V080_destinations!=='undefined')V114_installPlatformDestination(V080_destinations);

const V114_screenFamilyGuardBase=screenFamily;
screenFamily=function(){
 if(tab==='Career'&&careerTab==='Platforms')return 'studio';
 return V114_screenFamilyGuardBase()
};

/* ENCORE 0.9.12 interaction hotfix — Representation role actions.
   The role rows previously displayed OPEN as a visual tag even though players
   reasonably read it as a tappable control. Turn every open role into a real
   action and provide a focused candidate picker before contract review. */

function V115_roleCandidates(role){
 const rep=V100_repTeam();
 if(rep.team?.[role])return [];
 return V100_REP_CANDIDATES.filter(c=>c.role===role)
}

function V115_reviewCandidate(id){
 const dialog=$('modal');
 if(dialog?.open)dialog.close();
 return V100_reviewRep(id)
}

function V115_openRoleMarket(role){
 const r=V100_REP_ROLES[role];
 if(!r)return false;
 const rep=V100_repTeam(),current=rep.team?.[role];
 if(current){V100_reviewTermination(role);return true}
 const candidates=V115_roleCandidates(role);
 if(!candidates.length){toast?.('No '+r.name+' candidates are available right now.');return false}
 const explainer=typeof V108_repExplanation==='function'?V108_repExplanation(role):`<p>${esc(r.purpose||'Representation specialist.')}</p>`;
 modal(`<span class="eyebrow">REPRESENTATION MARKET · ${esc(r.name.toUpperCase())}</span><h2>Choose who you want to review.</h2>${explainer}<div class="v115-role-candidates">${candidates.map(c=>`<section class="card"><strong>${esc(c.name)}</strong><small>${esc(c.specialty||'General representation')} · ${c.skill}/100 skill</small><p>${esc(c.resume||'')}</p><button class="primary" type="button" onclick="V115_reviewCandidate('${c.id}')">Review role & contract →</button></section>`).join('')}</div><button class="secondary" type="button" onclick="$('modal').close()">Keep looking</button>`);
 return true
}

V100_repTeamPanel=function(){
 const rep=V100_repTeam();
 const rows=Object.entries(V100_REP_ROLES).map(([id,r])=>{
  const c=rep.team[id];
  return `<div class="project-row"><div><strong>${esc(r.name)}</strong><small>${c?esc(c.name)+' · '+(c.commission||0)+'% · '+esc(V100_repScopeLabel(c.scope)):esc(r.purpose)}</small><p>${esc(V100_repAdviceFor(id))}</p></div>${c?`<button class="secondary" type="button" onclick="V100_reviewTermination('${id}')">Review agreement</button>`:`<button class="secondary" type="button" onclick="V115_openRoleMarket('${id}')">Browse candidates →</button>`}</div>`
 }).join('');
 const market=V100_REP_CANDIDATES.filter(c=>!rep.team[c.role]).map(c=>V100_repCandidateCard(c)).join('');
 const history=rep.history.slice(0,12).map(x=>`<p><strong>Week ${x.week}</strong> · ${esc(x.name)} · ${x.type==='hired'?'Joined as '+V100_REP_ROLES[x.role].name:'Agreement ended · '+esc(x.reason||'New direction')+(x.fee?' · '+money(x.fee):'')}</p>`).join('')||'<p>Your hires, departures and termination reasons will appear here.</p>';
 return `<section class="card v108-representation-guide"><span class="eyebrow">REPRESENTATION · HOW THE TEAM WORKS</span><h2>Every representative has a defined job.</h2><p>There are no mystery bonuses here. Tap a role to compare available candidates, then review the exact role, compensation and contract before signing.</p></section><section class="card"><span class="eyebrow">REPRESENTATION 2.0 · YOUR TEAM</span><h2>Advice has a job attached to it.</h2><p>Percentage compensation only applies to the income categories written into that person’s scope. Investments, catalog sales and unrelated assets are excluded unless a future contract explicitly says otherwise.</p>${rows}</section><h2>Representation market</h2>${market}<section class="card"><h2>Team history</h2>${history}</section>`
};

