function V122_artistRequestProfile(a){
  if(!a)return '';
  return `<div class="v122-request-artist">${personPhoto('artist-'+(a.directoryKey??a.id),a.name)}<div><small>${esc(a.genre||'Artist')} · ${tierNames[tier(a.fans||0)]}</small><strong>${esc(a.name)}</strong><span>${compact(a.fans||0)} fans · Reputation ${Math.round(a.reputation||0)} · Relationship ${Math.round(a.relation||0)}</span></div></div>`
}
function V122_openLabelServiceRequest(id){
  const c=V100_labelCompetition(),o=c.inbound.find(x=>x.id===id&&x.status==='open'&&x.expires>=s.week);if(!o)return;
  const a=s.world?.[o.artist];
  modal(`<article class="v122-request-review"><span class="eyebrow">ARTIST REQUEST · INBOUND SERVICES</span><h2>${esc(a?.name||'Artist')} wants ${esc(o.name)}.</h2>${V122_artistRequestProfile(a)}${profileRows([['Service',o.name],['Scope',o.detail],['Company fee',money(o.fee)],['Term',o.weeks+' weeks'],['Service participation',o.share?Math.round(o.share*100)+'%':'None'],['Decision deadline','Week '+o.expires]])}<p class="v122-request-note">Review the full request here. You do not need to leave this popup or hunt through another department.</p><div class="v122-request-actions"><button class="secondary" onclick="$('modal').close();V100_declineInbound('${id}')">Decline</button><button class="primary" onclick="$('modal').close();V100_acceptInbound('${id}')">Accept ${esc(o.name)}</button></div></article>`,'v122-request-dialog')
}
function V122_openCreativeRequest(id){
  migrateV081?.();const o=s.v081?.creative?.offers?.find(x=>x.id===id&&x.status==='open'),a=o&&s.world?.[o.artist];if(!o||!a)return;
  const type={ghostwrite:'Ghostwriting request',produce:'Production request',songOffer:'Song offered to you',featureInvite:'Feature / collaboration request'}[o.type]||'Artist request';
  const fee=(o.type==='ghostwrite'||o.type==='produce')?money(o.fee||0):o.type==='songOffer'?money(Math.round((o.fee||0)*.75)):'Deal terms shown on review';
  const accept=o.type==='featureInvite'&&typeof V092_reviewIncomingFeature==='function'?`<button class="primary" onclick="V092_reviewIncomingFeature(${id})">Review feature terms</button>`:`<button class="primary" onclick="$('modal').close();V081_acceptCreative(${id})">${o.type==='songOffer'?'Accept / acquire song':'Accept request'}</button>`;
  modal(`<article class="v122-request-review"><span class="eyebrow">ARTIST REQUEST · ${esc(type.toUpperCase())}</span><h2>${esc(a.name)} reached out.</h2>${V122_artistRequestProfile(a)}${profileRows([['Request',type],['Estimated creative quality',Math.round(o.quality||0)+'/100'],['Value / terms',fee]])}<p class="v122-request-note">Everything needed to decide is kept in this popup. Opening the request does not move you to Creative Network.</p><div class="v122-request-actions"><button class="secondary" onclick="$('modal').close();V081_declineCreative(${id})">Decline</button>${accept}</div></article>`,'v122-request-dialog')
}
function V122_openTourRequest(id){
  migrateTouring?.();const o=s.touring?.offers?.find(x=>x.id===id&&!x.done&&x.expires>=s.week);if(!o)return;
  const a=s.world?.[o.artist],city=careerWorldMarket?.(o.city)?.city||o.city||'Tour stop';
  modal(`<article class="v122-request-review"><span class="eyebrow">ARTIST REQUEST · TOUR INVITATION</span><h2>${esc(a?.name||'Artist')} wants you on the bill.</h2>${V122_artistRequestProfile(a)}${profileRows([['Role','Opening slot'],['City',city],['Guaranteed fee',money(o.fee||0)],['Audience reach',compact(o.reach||0)],['Energy','25'],['Decision deadline','Week '+o.expires]])}<p class="v122-request-note">Review the invitation here. Accepting still uses the existing Touring simulation and shared live-history systems.</p><div class="v122-request-actions"><button class="secondary" onclick="$('modal').close()">Later</button><button class="primary" onclick="acceptOpeningSlot(${id})">Review & accept</button></div></article>`,'v122-request-dialog')
}

/* Priority requests now open in-place. Commercial/company opportunities keep their
   existing departmental route because they are not artist-to-player requests. */
if(typeof V096_openPriority==='function'){
  const V122_openPriorityBase=V096_openPriority;
  V096_openPriority=function(key){
    const item=V096_priorityRaw().find(x=>x.key===key);if(!item)return;
    if(item.kind==='creative'||item.kind==='tour'){
      V096_markSeen([key]);if($('modal')?.open)$('modal').close();
      return item.kind==='creative'?V122_openCreativeRequest(item.id):V122_openTourRequest(item.id)
    }
    return V122_openPriorityBase(key)
  }
}

/* The exact Artist Relations briefing shown for inbound label services can be
   reviewed directly without leaving the briefing flow. */
const V122_offerBriefingButtonBase=offerBriefingButton;
offerBriefingButton=function(b){
  if(b?.id?.startsWith('label-service:')){
    const id=b.id.slice('label-service:'.length);
    return `<button class="memo-primary" onclick="V122_openLabelServiceRequest('${id}')">Review artist request here</button>`
  }
  return V122_offerBriefingButtonBase(b)
};

/* ENCORE 0.9.19 — Executive Office 1.0.
   Separates the artist's personal representation from company leadership and
   turns late-career management into a delegation/strategy simulation instead
   of another passive-buff roster. */

const V123_EXEC_ROLES={
 chief:{name:'Chief of Staff',short:'Chief of Staff',unlock:1,dept:'Executive Office',purpose:'Coordinates leadership, priorities and cross-department execution.',kpis:['Decision pace','Leadership alignment','Execution']},
 coo:{name:'President / COO',short:'COO',unlock:2,dept:'Operations',purpose:'Runs company operations, staffing discipline and execution.',kpis:['Operating efficiency','Execution','Department health']},
 cfo:{name:'Chief Financial Officer',short:'CFO',unlock:2,dept:'Finance',purpose:'Protects liquidity, budgets, forecasting and sustainable growth.',kpis:['Cash discipline','Margin','Forecast quality']},
 legal:{name:'General Counsel',short:'General Counsel',unlock:2,dept:'Legal',purpose:'Owns company legal risk, rights strategy and complex agreements.',kpis:['Rights protection','Contract risk','Dispute prevention']},
 cmo:{name:'Chief Marketing Officer',short:'CMO',unlock:2,dept:'Marketing',purpose:'Turns attention into durable audience, demand and commercial growth.',kpis:['Audience growth','Campaign efficiency','Demand conversion']},
 creative:{name:'Chief Creative Officer / Head of A&R',short:'CCO / A&R',unlock:2,dept:'Creative',purpose:'Leads artist development, repertoire and long-term creative strategy.',kpis:['Release quality','Roster development','Creative pipeline']},
 touring:{name:'Head of Touring & Live',short:'Touring',unlock:2,dept:'Live',purpose:'Owns routing, production scale, margins and road operations.',kpis:['Tour margin','Sell-through','Operational reliability']},
 catalog:{name:'President of Catalog & Rights',short:'Catalog',unlock:3,dept:'Catalog',purpose:'Builds catalog value through ownership, licensing and acquisition strategy.',kpis:['Catalog value','Ownership','Licensing']},
 international:{name:'President of International',short:'International',unlock:4,dept:'Global',purpose:'Coordinates international expansion, regional partnerships and global growth.',kpis:['Global audience','Regional depth','International demand']}
};
const V123_STRATEGIES={
 balanced:{name:'Balanced',desc:'Protect cash, creative quality and growth without overcommitting to one lane.',bias:{chief:3,coo:4,cfo:4,legal:3,cmo:2,creative:2,touring:2,catalog:2,international:2}},
 growth:{name:'Maximum Growth',desc:'Spend aggressively when credible opportunities can accelerate the next career tier.',bias:{chief:2,coo:3,cfo:-3,legal:-1,cmo:7,creative:3,touring:4,catalog:1,international:5}},
 profit:{name:'Profitability',desc:'Prioritize margin, liquidity and efficient operations over headline expansion.',bias:{chief:2,coo:6,cfo:8,legal:3,cmo:-2,creative:-1,touring:1,catalog:3,international:-2}},
 development:{name:'Artist Development',desc:'Favor quality, A&R patience, artist growth and sustainable catalog value.',bias:{chief:2,coo:1,cfo:0,legal:3,cmo:1,creative:8,touring:0,catalog:5,international:1}},
 global:{name:'Global Expansion',desc:'Push regional audience growth, international touring and cross-border partnerships.',bias:{chief:2,coo:3,cfo:-1,legal:3,cmo:4,creative:2,touring:5,catalog:2,international:9}},
 catalog:{name:'Catalog Ownership',desc:'Prioritize long-lived rights, acquisitions and ownership over short-term checks.',bias:{chief:2,coo:1,cfo:4,legal:7,cmo:0,creative:4,touring:-1,catalog:9,international:1}},
 dominate:{name:'Market Domination',desc:'Use scale, marketing and release pressure to maximize market share and visibility.',bias:{chief:3,coo:4,cfo:-3,legal:1,cmo:9,creative:5,touring:4,catalog:2,international:5}},
 independence:{name:'Independence',desc:'Protect ownership, optionality and founder control even when outside capital is tempting.',bias:{chief:3,coo:2,cfo:4,legal:9,cmo:1,creative:5,touring:0,catalog:7,international:0}}
};
const V123_AUTHORITY={
 hands:{name:'Hands-On',desc:'You approve every meaningful move. The executive advises but does not act.'},
 recommend:{name:'Recommend',desc:'The executive prepares plans and recommendations but still waits for approval.'},
 guardrails:{name:'Guardrails',desc:'The executive may act inside the weekly budget and reserve floor you set.'},
 full:{name:'Full Authority',desc:'The executive runs the department inside company policy and reports the result.'}
};
const V123_FIRST=['Jordan','Naomi','Marcus','Camille','Darius','Sierra','Avery','Malik','Renee','Victor','Tiana','Julian','Imani','Morgan','Micah','Selena','Elias','Kendall'];
const V123_LAST=['Hale','Banks','Cole','Mercer','Stone','Cross','Wells','King','Blake','Rowe','Bennett','Monroe','Carter','Ellis','Hart','Vale','Reed','Lane'];
const V123_STYLES=[
 {id:'operator',name:'Disciplined operator',skill:3,rep:2,trust:2,desc:'Prefers clear systems, measurable execution and fewer unforced errors.'},
 {id:'builder',name:'Growth builder',skill:2,rep:3,trust:0,desc:'Comfortable spending and reorganizing when the growth case is strong.'},
 {id:'diplomat',name:'Relationship executive',skill:0,rep:5,trust:4,desc:'Protects partnerships and gets alignment before forcing change.'},
 {id:'hawk',name:'Hard-line strategist',skill:5,rep:2,trust:-2,desc:'Pushes aggressively for leverage, margin and control.'},
 {id:'visionary',name:'Vision-led executive',skill:3,rep:4,trust:1,desc:'Accepts more variance in exchange for differentiated upside.'}
];
let V123_execTab='Leadership';
let V123_hiringRole='chief';

function V123_scale(){
 const assets=typeof V092_businessValue==='function'?V092_businessValue():0,fans=Math.max(0,Number(s.fans)||0),label=Boolean(s.labelBusiness?.company);
 if(assets>=1e9||fans>=100000000)return 4;
 if(assets>=250000000||fans>=20000000)return 3;
 if(assets>=25000000||fans>=2000000||label)return 2;
 if(assets>=1000000||fans>=250000)return 1;
 return 0
}
function V123_scaleName(level=V123_scale()){return ['Founder-led operation','Growing company','Established company','Major company','Global empire'][clamp(level,0,4)]}
function V123_execState(){
 if(!s.executiveOffice||typeof s.executiveOffice!=='object')s.executiveOffice={version:1,strategy:'balanced',team:{},history:[],meetings:[],policies:{reserveFloor:0},lastPayrollWeek:0,lastMeetingWeek:0,marketRefresh:{},nextMeetingId:1};
 const e=s.executiveOffice;e.version=1;e.team??={};e.history??=[];e.meetings??=[];e.policies??={reserveFloor:0};e.marketRefresh??={};e.nextMeetingId??=1;e.strategy=V123_STRATEGIES[e.strategy]?e.strategy:'balanced';
 for(const [role,x] of Object.entries(e.team)){if(!V123_EXEC_ROLES[role]){delete e.team[role];continue}x.role=role;x.trust=clamp(Number.isFinite(Number(x.trust))?Number(x.trust):55,0,100);x.alignment=clamp(Number.isFinite(Number(x.alignment))?Number(x.alignment):55,0,100);x.performance=clamp(Number.isFinite(Number(x.performance))?Number(x.performance):65,0,100);x.authority=V123_AUTHORITY[x.authority]?x.authority:'hands';x.weeklyBudget=Math.max(0,Number(x.weeklyBudget)||0);x.started??=s.week;x.lastInteractionWeek??=0;x.history??=[]}
 return e
}
function V123_founderOwnership(){return clamp(100-Object.values(V123_execState().team).reduce((n,x)=>n+(Number(x.equityBps)||0)/100,0),0,100)}
function V123_candidate(role,i){
 const ri=Math.max(0,Object.keys(V123_EXEC_ROLES).indexOf(role)),style=V123_STYLES[(i+ri)%V123_STYLES.length],scale=Math.max(1,V123_scale()),seed=i+ri*7;
 const name=V123_FIRST[(seed*5+ri)%V123_FIRST.length]+' '+V123_LAST[(seed*7+3)%V123_LAST.length];
 const skill=clamp(72+((seed*7)%20)+style.skill,65,99),reputation=clamp(68+((seed*5)%22)+style.rep,60,99);
 const base={chief:180000,coo:450000,cfo:520000,legal:560000,cmo:480000,creative:500000,touring:360000,catalog:520000,international:600000}[role]||350000;
 const salary=Math.round(base*(.72+skill/160)*(1+(scale-1)*.32)/5000)*5000;
 const bonusPct=clamp(8+Math.round((skill-70)/3)+((seed)%5)*2,8,35);
 const equityBps=scale>=3&&skill>=90?25+((seed*11)%76):scale>=2&&skill>=95?20:0;
 return {id:`v123-${role}-${i}`,role,name,skill,reputation,style:style.id,styleName:style.name,styleDesc:style.desc,salary,bonusPct,equityBps,specialty:V123_EXEC_ROLES[role].kpis[(i+ri)%V123_EXEC_ROLES[role].kpis.length]}
}
function V123_candidates(role){const refresh=V123_execState().marketRefresh[role]||0,start=((s.week+refresh*3)%6);return [0,1,2,3].map(k=>V123_candidate(role,(start+k)%6))}
function V123_weeklySalary(x){return cents((Number(x.salary)||0)/52)}
function V123_totalPayroll(){return cents(Object.values(V123_execState().team).reduce((n,x)=>n+V123_weeklySalary(x),0))}
function V123_strategyBias(role){const strategy=V123_STRATEGIES[V123_execState().strategy]||V123_STRATEGIES.balanced;return Number(strategy.bias?.[role]||0)}
function V123_effectiveSkill(x){if(!x)return 0;return clamp(Math.round((Number(x.skill)||0)+(x.trust-50)*.06+(x.alignment-50)*.05),0,100)}
function V123_performanceGrade(n){return n>=93?'A+':n>=88?'A':n>=83?'A−':n>=78?'B+':n>=72?'B':n>=66?'B−':n>=60?'C+':n>=54?'C':n>=45?'D':'F'}
function V123_roleUnlocked(role){return V123_scale()>=V123_EXEC_ROLES[role].unlock}
function V123_canOperate(x){return x&&['guardrails','full'].includes(x.authority)}
function V123_history(type,detail,role=''){const e=V123_execState();e.history.unshift({week:s.week,type,detail,role});e.history=e.history.slice(0,80)}

function V123_reviewCandidate(role,id){const c=V123_candidates(role).find(x=>x.id===id)||V123_candidate(role,Number(String(id).split('-').pop())||0),r=V123_EXEC_ROLES[role];if(!c||!r)return;const fourWeeks=V123_weeklySalary(c)*4;modal(`<span class="eyebrow">EXECUTIVE SEARCH · ${esc(r.dept.toUpperCase())}</span><h2>${esc(c.name)}</h2><p>${esc(c.styleName)} · ${esc(c.specialty)}</p>${profileRows([['Role',r.name],['Skill',c.skill+'/100'],['Industry reputation',c.reputation+'/100'],['Annual salary',money(c.salary)],['Target bonus',c.bonusPct+'%'],['Equity request',c.equityBps?(c.equityBps/100).toFixed(2)+'%':'None'],['Four-week payroll',money(fourWeeks)]])}<p>${esc(c.styleDesc)}</p><p class="fine">Executives begin in Hands-On mode. They cannot spend or execute delegated decisions until you explicitly increase their authority.</p><button class="primary" onclick="V123_hireExecutive('${role}','${c.id}')">Hire ${esc(c.name)}</button><button class="secondary" onclick="$('modal').close()">Keep searching</button>`)}
function V123_hireExecutive(role,id){const e=V123_execState(),r=V123_EXEC_ROLES[role];if(!r||e.team[role])return;if(!V123_roleUnlocked(role)){toast('Grow the company before opening this seat.');return}const c=V123_candidates(role).find(x=>x.id===id)||V123_candidate(role,Number(String(id).split('-').pop())||0);if(!c)return;const runway=V123_weeklySalary(c)*4;if(s.cash<runway){toast('Keep at least four weeks of this salary in cash before hiring.');return}e.team[role]={...c,authority:'hands',weeklyBudget:Math.round(c.salary/52*.75),trust:55+(V123_STYLES.find(x=>x.id===c.style)?.trust||0),alignment:clamp(55+V123_strategyBias(role),25,90),performance:68,started:s.week,lastInteractionWeek:0,history:[]};V123_history('hire',c.name+' joined as '+r.name,role);$('modal').close();queueSave?.();render();toast(c.name+' joined the executive team.')}
function V123_reviewExit(role){const x=V123_execState().team[role],r=V123_EXEC_ROLES[role];if(!x||!r)return;const severance=cents(V123_weeklySalary(x)*8);modal(`<span class="eyebrow">EXECUTIVE CHANGE</span><h2>End ${esc(x.name)}'s tenure?</h2>${profileRows([['Role',r.name],['Tenure',Math.max(0,s.week-x.started)+' weeks'],['Performance',V123_performanceGrade(x.performance)+' · '+Math.round(x.performance)+'/100'],['Trust',Math.round(x.trust)+'/100'],['Severance',money(severance)],['Equity already granted',x.equityBps?(x.equityBps/100).toFixed(2)+'%':'None']])}<p class="fine">Granted equity remains part of the executive's permanent compensation history. Severance is paid immediately.</p><button class="primary" onclick="V123_fireExecutive('${role}',${severance})">Confirm departure</button><button class="secondary" onclick="$('modal').close()">Keep executive</button>`)}
function V123_fireExecutive(role,severance){const e=V123_execState(),x=e.team[role];if(!x)return;if(s.cash<severance){toast('Not enough cash for the severance obligation.');return}changeCash(-severance);s.finance.week.expenses=cents((s.finance.week.expenses||0)+severance);V123_history('departure',x.name+' left the '+V123_EXEC_ROLES[role].name+' role · '+money(severance)+' severance',role);delete e.team[role];$('modal').close();queueSave?.();render()}
function V123_refreshMarket(role){const e=V123_execState();e.marketRefresh[role]=(e.marketRefresh[role]||0)+1;V123_hiringRole=role;render()}

function V123_setAuthority(role,authority){const x=V123_execState().team[role];if(!x||!V123_AUTHORITY[authority])return;x.authority=authority;V123_history('authority',x.name+' moved to '+V123_AUTHORITY[authority].name+' authority',role);queueSave?.();render()}
function V123_updateBudget(role,value){const x=V123_execState().team[role],n=Math.max(0,Math.round(Number(value)||0));if(!x)return;x.weeklyBudget=n;V123_history('policy',x.name+' weekly delegation budget set to '+money(n),role);queueSave?.();render();toast('Delegation guardrail updated.')}
function V123_setReserveFloor(value){const e=V123_execState(),n=Math.max(0,Math.round(Number(value)||0));e.policies.reserveFloor=n;V123_history('policy','Company reserve floor set to '+money(n),'cfo');queueSave?.();render()}
function V123_changeStrategy(id){const e=V123_execState();if(!V123_STRATEGIES[id]||e.strategy===id)return;e.strategy=id;for(const [role,x] of Object.entries(e.team)){const delta=V123_strategyBias(role);x.alignment=clamp(x.alignment+Math.sign(delta)*(2+Math.min(4,Math.abs(delta))),0,100)}V123_history('strategy','Company strategy changed to '+V123_STRATEGIES[id].name);queueSave?.();render();toast('Company strategy updated.')}
function V123_interact(role,kind){const x=V123_execState().team[role];if(!x)return false;if(x.lastInteractionWeek===s.week){toast('You already had a direct executive interaction with '+x.name+' this week.');return false}if(!spend(5))return false;let trust=0,alignment=0,label='Executive check-in';if(kind==='check'){trust=7;alignment=2;label='One-on-one check-in'}if(kind==='back'){trust=5;alignment=7;label='Backed executive recommendation'}if(kind==='challenge'){trust=-5;alignment=-3;label='Challenged executive strategy'}if(kind==='reset'){trust=10;alignment=8;label='Reset priorities and expectations'}x.lastInteractionWeek=s.week;x.trust=clamp(x.trust+trust,0,100);x.alignment=clamp(x.alignment+alignment,0,100);x.history.unshift({week:s.week,label,trust,alignment});x.history=x.history.slice(0,16);queueSave?.();render();V123_openExecutive(role);return true}

function V123_execKpiScore(role){
 const e=V123_execState(),x=e.team[role];if(!x)return 0;let score=65;
 if(role==='cfo'){const last=s.finance?.last;score=55+(s.cash>=Math.max(0,e.policies.reserveFloor)?12:-10)+(last?.net>=0?8:-5)+V092_businessLevel('Finance')*.12}
 else if(role==='coo')score=60+V092_businessLevel('Management')*.18+(s.cash>=0?8:-8);
 else if(role==='legal')score=62+V092_businessLevel('Negotiation')*.12+(s.expansion?.contract?3:8);
 else if(role==='cmo')score=58+clamp((s.careerWorld?.momentum||0)*.2,0,20)+V092_businessLevel('Marketing')*.12;
 else if(role==='creative')score=58+V092_businessLevel('A&R')*.15+clamp((s.careerWorld?.releaseForm||50)*.18,0,18);
 else if(role==='touring')score=58+V092_businessLevel('Management')*.08+clamp((s.careerWorld?.tourDemand||45)*.2,0,20)+(s.careerRecords?.liveProfit>=0?5:-5);
 else if(role==='chief'){const open=e.meetings.filter(m=>m.status==='open').length,avg=Object.values(e.team).reduce((n,z)=>n+z.alignment,0)/Math.max(1,Object.keys(e.team).length);score=65+avg*.18-open*4}
 else if(role==='catalog')score=58+V092_businessLevel('Finance')*.08+clamp(Math.log10(1+(s.v080?.catalog?.holdings||[]).reduce((n,h)=>n+(h.lastValue||0),0))*3,0,22);
 else if(role==='international')score=60+clamp((s.careerWorld?.momentum||0)*.12,0,12)+V092_businessLevel('Networking')*.15;
 return clamp(score+(V123_effectiveSkill(x)-80)*.18+V123_strategyBias(role)*.35,30,99)
}
function V123_applyExecutiveEffects(){
 const e=V123_execState(),cfo=e.team.cfo,coo=e.team.coo,cmo=e.team.cmo,creative=e.team.creative,touring=e.team.touring;
 let reach=0,costEfficiency=0,tourCost=0,tourDemand=0;
 if(V123_canOperate(cmo))reach+=(V123_effectiveSkill(cmo)-60)/2500;
 if(V123_canOperate(creative))reach+=(V123_effectiveSkill(creative)-60)/5000;
 if(V123_canOperate(cfo))costEfficiency+=(V123_effectiveSkill(cfo)-60)/7000;
 if(V123_canOperate(coo))costEfficiency+=(V123_effectiveSkill(coo)-60)/8000;
 if(V123_canOperate(touring)){tourCost+=(V123_effectiveSkill(touring)-60)/1400;tourDemand+=(V123_effectiveSkill(touring)-60)/2500}
 if(e.strategy==='growth'||e.strategy==='dominate')reach+=.02;
 if(e.strategy==='profit')costEfficiency+=.01;
 if(e.strategy==='global'){tourDemand+=.02;tourCost+=.01}
 if(e.activePlan?.until>=s.week){reach+=Number(e.activePlan.reachLift)||0;tourDemand+=Number(e.activePlan.tourLift)||0;costEfficiency+=Number(e.activePlan.efficiencyLift)||0}
 return {reach:clamp(reach,0,.10),costEfficiency:clamp(costEfficiency,0,.06),tourCost:clamp(tourCost,0,.08),tourDemand:clamp(tourDemand,0,.08)}
}
const V123_operationRateBase=operationRate;
operationRate=function(){const base=V123_operationRateBase(),fx=V123_applyExecutiveEffects();return Math.max(0,base-fx.costEfficiency)};
const V123_adjustReleaseStreamsBase=adjustReleaseStreams;
adjustReleaseStreams=function(track,n){const out=V123_adjustReleaseStreamsBase(track,n),fx=V123_applyExecutiveEffects();return Math.max(0,Math.round(out*(1+fx.reach)))};
const V123_tourEstimateBase=tourEstimate;
tourEstimate=function(i){const out=V123_tourEstimateBase(i),fx=V123_applyExecutiveEffects();out.cost=Math.max(0,Math.round(out.cost*(1-fx.tourCost)));out.sold=Math.min(venueTiers[i]?.seats||out.sold,Math.round(out.sold*(1+fx.tourDemand)));out.gross=out.sold*(venueTiers[i]?.ticket||0);return out};

function V123_meetingTemplate(){
 const e=V123_execState(),team=e.team,cash=Math.max(0,s.cash),templates=[];
 if(team.cmo)templates.push({type:'marketing',title:'Scale the next campaign?',lead:'cmo',body:team.cmo.name+' wants a larger audience-conversion push while attention is available.',options:[{id:'push',label:'Approve growth campaign',cost:Math.max(5000,Math.min(cash*.04,team.cmo.weeklyBudget||500000)),trust:5,align:6,plan:{reachLift:.035,weeks:4}},{id:'measured',label:'Approve measured test',cost:Math.max(1000,Math.min(cash*.01,(team.cmo.weeklyBudget||100000)*.35)),trust:2,align:2,plan:{reachLift:.015,weeks:3}},{id:'hold',label:'Hold spending',cost:0,trust:-2,align:-4,plan:{}}]});
 if(team.cfo)templates.push({type:'liquidity',title:'How much cash should the company protect?',lead:'cfo',body:team.cfo.name+' wants a formal liquidity floor before more expansion decisions are delegated.',options:[{id:'protect',label:'Protect a 12-week payroll reserve',cost:0,trust:6,align:6,reserve:'12w'},{id:'balanced',label:'Protect a 6-week payroll reserve',cost:0,trust:3,align:2,reserve:'6w'},{id:'flex',label:'Keep capital flexible',cost:0,trust:-3,align:-5,reserve:'0w'}]});
 if(team.creative)templates.push({type:'creative',title:'Fund a deeper A&R development cycle?',lead:'creative',body:team.creative.name+' wants more time and development money behind fewer, stronger records.',options:[{id:'invest',label:'Fund development',cost:Math.max(3000,Math.min(cash*.025,team.creative.weeklyBudget||250000)),trust:5,align:7,plan:{reachLift:.02,weeks:5}},{id:'pilot',label:'Run a smaller pilot',cost:Math.max(1000,Math.min(cash*.008,(team.creative.weeklyBudget||100000)*.3)),trust:2,align:2,plan:{reachLift:.008,weeks:3}},{id:'volume',label:'Keep release volume high',cost:0,trust:-2,align:-4,plan:{}}]});
 if(team.touring)templates.push({type:'touring',title:'Push the live business into larger rooms?',lead:'touring',body:team.touring.name+' believes current demand can support a more aggressive live strategy.',options:[{id:'scale',label:'Scale live production',cost:Math.max(5000,Math.min(cash*.03,team.touring.weeklyBudget||350000)),trust:5,align:6,plan:{tourLift:.04,weeks:6}},{id:'selective',label:'Scale only strongest markets',cost:Math.max(1500,Math.min(cash*.01,(team.touring.weeklyBudget||100000)*.4)),trust:2,align:2,plan:{tourLift:.018,weeks:5}},{id:'hold',label:'Hold venue strategy',cost:0,trust:-2,align:-3,plan:{}}]});
 if(!templates.length)return null;return templates[(s.week+e.nextMeetingId)%templates.length]
}
function V123_generateMeeting(force=false){const e=V123_execState();if(!Object.keys(e.team).length)return null;if(!force&&(s.week-e.lastMeetingWeek<4||e.meetings.some(x=>x.status==='open')))return null;const t=V123_meetingTemplate();if(!t)return null;const m={id:e.nextMeetingId++,week:s.week,status:'open',...t};e.meetings.unshift(m);e.meetings=e.meetings.slice(0,30);e.lastMeetingWeek=s.week;addBriefing?.('exec-meeting:'+m.id,'Business','Executive meeting waiting',m.title+' Open Business HQ → Executive Office to make the call.');V123_history('meeting','Executive meeting opened · '+m.title,m.lead);return m}
function V123_openMeetings(){V123_execTab='Meetings';careerTab='Team';go('Career')}
function V123_openMeeting(id){const m=V123_execState().meetings.find(x=>x.id===Number(id));if(!m)return;if(m.status!=='open'){toast('That executive decision is already closed.');return}const lead=V123_execState().team[m.lead],role=V123_EXEC_ROLES[m.lead];modal(`<span class="eyebrow">EXECUTIVE MEETING · WEEK ${m.week}</span><h2>${esc(m.title)}</h2><p>${esc(m.body)}</p>${lead?profileRows([['Lead executive',lead.name+' · '+role.short],['Trust',Math.round(lead.trust)+'/100'],['Alignment',Math.round(lead.alignment)+'/100'],['Current strategy',V123_STRATEGIES[V123_execState().strategy].name]]):''}<div class="v123-decision-options">${m.options.map((o,i)=>`<button class="${i===0?'primary':'secondary'}" onclick="V123_resolveMeeting(${m.id},'${o.id}')"><strong>${esc(o.label)}</strong><small>${o.cost?money(o.cost)+' company spend':'No immediate spend'}</small></button>`).join('')}</div><p class="fine">The decision changes executive trust/alignment and can create a temporary operating plan. Nothing is accepted simply by opening this meeting.</p>`)}
function V123_resolveMeeting(id,optionId){const e=V123_execState(),m=e.meetings.find(x=>x.id===Number(id));if(!m||m.status!=='open')return;const o=m.options.find(x=>x.id===optionId);if(!o)return;if(o.cost>s.cash){toast('The company does not have enough spendable cash for that option.');return}if(o.cost){changeCash(-o.cost);s.finance.week.expenses=cents((s.finance.week.expenses||0)+o.cost)}const x=e.team[m.lead];if(x){x.trust=clamp(x.trust+(o.trust||0),0,100);x.alignment=clamp(x.alignment+(o.align||0),0,100)}if(o.reserve==='12w')e.policies.reserveFloor=Math.round(V123_totalPayroll()*12);else if(o.reserve==='6w')e.policies.reserveFloor=Math.round(V123_totalPayroll()*6);else if(o.reserve==='0w')e.policies.reserveFloor=0;if(o.plan&&Object.keys(o.plan).length)e.activePlan={source:m.type,started:s.week,until:s.week+(o.plan.weeks||4),reachLift:o.plan.reachLift||0,tourLift:o.plan.tourLift||0,efficiencyLift:o.plan.efficiencyLift||0};m.status='resolved';m.choice=o.id;m.choiceLabel=o.label;m.resolvedWeek=s.week;m.cost=o.cost||0;V123_history('decision',m.title+' · '+o.label,m.lead);$('modal').close();queueSave?.();render();toast('Executive decision recorded.')}

function V123_settleExecutiveWeek(completed=s.week){const e=V123_execState();if(e.lastPayrollWeek===completed)return 0;let payroll=0;for(const [role,x] of Object.entries({...e.team})){payroll+=V123_weeklySalary(x);const target=V123_execKpiScore(role);x.performance=clamp(x.performance+(target-x.performance)*.18,0,100);x.alignment=clamp(x.alignment+(V123_strategyBias(role)>=0?.35:-.45),0,100);if(completed-(x.lastInteractionWeek||x.started)>=10&&completed%2===0)x.trust=clamp(x.trust-1,0,100);if(x.trust<=8){V123_history('resignation',x.name+' resigned after executive trust collapsed',role);addBriefing?.('exec-resign:'+x.id+':'+completed,'Business',x.name+' resigned',V123_EXEC_ROLES[role].name+' is now vacant after the working relationship broke down.');delete e.team[role];continue}if(completed%52===0){const bonus=cents((x.salary||0)*(x.bonusPct||0)/100*(x.performance/100));if(bonus>0){changeCash(-bonus);s.finance.week.expenses=cents((s.finance.week.expenses||0)+bonus);V123_history('bonus',x.name+' earned '+money(bonus)+' annual performance bonus',role)}}}
payroll=cents(payroll);if(payroll){changeCash(-payroll);s.finance.week.expenses=cents((s.finance.week.expenses||0)+payroll)}e.lastPayrollWeek=completed;V123_generateMeeting(false);return payroll}
const V123_beginCareerWeekBase=beginCareerWeek;
beginCareerWeek=function(){V123_beginCareerWeekBase();V123_settleExecutiveWeek(s.week)};

function V123_execCard(role,x){const r=V123_EXEC_ROLES[role];return `<article class="v123-exec-card"><div class="v123-exec-head">${typeof personPhoto==='function'?personPhoto('exec-'+x.id,x.name):''}<div><small>${esc(r.dept.toUpperCase())}</small><h3>${esc(x.name)}</h3><p>${esc(r.short)} · ${esc(x.styleName)}</p></div><span class="v123-grade">${V123_performanceGrade(x.performance)}</span></div>${profileRows([['Performance',Math.round(x.performance)+'/100'],['Trust',Math.round(x.trust)+'/100'],['Alignment',Math.round(x.alignment)+'/100'],['Authority',V123_AUTHORITY[x.authority].name],['Salary',money(x.salary)+'/yr'],['Effective skill',V123_effectiveSkill(x)+'/100']])}<button class="secondary" onclick="V123_openExecutive('${role}')">Open executive file →</button></article>`}
function V123_openExecutive(role){const x=V123_execState().team[role],r=V123_EXEC_ROLES[role];if(!x||!r)return;modal(`<section class="v123-executive-sheet">${typeof personPhoto==='function'?personPhoto('exec-'+x.id,x.name,true):''}<span class="eyebrow">${esc(r.name.toUpperCase())}</span><h2>${esc(x.name)}</h2><p>${esc(x.styleName)} · ${esc(x.specialty)}</p>${profileRows([['Performance',V123_performanceGrade(x.performance)+' · '+Math.round(x.performance)+'/100'],['Trust',Math.round(x.trust)+'/100'],['Strategic alignment',Math.round(x.alignment)+'/100'],['Base / effective skill',x.skill+'/100 · '+V123_effectiveSkill(x)+'/100'],['Annual salary',money(x.salary)],['Target bonus',x.bonusPct+'%'],['Equity',(x.equityBps||0)?(x.equityBps/100).toFixed(2)+'%':'None'],['Tenure',Math.max(0,s.week-x.started)+' weeks']])}<h3>Authority</h3><div class="v123-authority-grid">${Object.entries(V123_AUTHORITY).map(([id,a])=>`<button class="${x.authority===id?'selected':''}" onclick="$('modal').close();V123_setAuthority('${role}','${id}')"><strong>${esc(a.name)}</strong><small>${esc(a.desc)}</small></button>`).join('')}</div><form class="form" onsubmit="event.preventDefault();$('modal').close();V123_updateBudget('${role}',this.elements.budget.value)"><label>Weekly delegated-spend ceiling<input type="number" name="budget" min="0" step="1000" value="${Math.round(x.weeklyBudget||0)}"></label><button class="secondary">Update guardrail</button></form><h3>Working relationship</h3><div class="controls"><button class="secondary" ${x.lastInteractionWeek===s.week?'disabled':''} onclick="V123_interact('${role}','check')">1:1 check-in · 5 energy</button><button class="secondary" ${x.lastInteractionWeek===s.week?'disabled':''} onclick="V123_interact('${role}','back')">Back their plan · 5 energy</button><button class="secondary" ${x.lastInteractionWeek===s.week?'disabled':''} onclick="V123_interact('${role}','challenge')">Challenge strategy · 5 energy</button>${x.trust<35?`<button class="primary" ${x.lastInteractionWeek===s.week?'disabled':''} onclick="V123_interact('${role}','reset')">Reset relationship · 5 energy</button>`:''}</div><p class="fine">Delegation is never implied by hiring. Hands-On is the default. Guardrails and Full Authority activate department-level effects only after you choose them.</p><button class="secondary" onclick="V123_reviewExit('${role}')">Review departure / severance</button></section>`)}
function V123_leadershipPanel(){const e=V123_execState(),roles=Object.entries(V123_EXEC_ROLES),open=e.meetings.filter(x=>x.status==='open').length;return `<section class="v123-office-hero"><div><span class="eyebrow">BUSINESS HQ · EXECUTIVE OFFICE</span><h1>${esc(s.labelBusiness?.company?.name||s.name+' Enterprises')}</h1><p>${esc(V123_scaleName())}. Your personal manager, booking agent, attorney and publicist remain under <strong>Representation</strong>; this office is for company leadership.</p></div><div class="v123-founder-card"><small>FOUNDER OWNERSHIP</small><strong>${V123_founderOwnership().toFixed(2)}%</strong><span>${Object.keys(e.team).length} executives · ${open} decision${open===1?'':'s'} waiting</span></div></section><section class="v123-metric-rail">${[['EXECUTIVE PAYROLL',money(V123_totalPayroll())+'/wk'],['STRATEGY',V123_STRATEGIES[e.strategy].name],['RESERVE FLOOR',money(e.policies.reserveFloor||0)],['OPEN MEETINGS',String(open)]].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('')}</section><div class="v123-exec-grid">${roles.filter(([role])=>e.team[role]).map(([role])=>V123_execCard(role,e.team[role])).join('')||'<section class="card"><h2>Founder-led for now.</h2><p>Your personal representation can carry an early career. Company executives unlock as the operation grows.</p></section>'}</div><section class="card"><div class="sectionhead"><div><span class="eyebrow">OPEN SEATS</span><h2>Build leadership as the company earns the complexity.</h2></div></div><div class="v123-seat-grid">${roles.map(([role,r])=>{const x=e.team[role],unlocked=V123_roleUnlocked(role);return `<button ${x||!unlocked?'disabled':''} onclick="V123_hiringRole='${role}';V123_execTab='Hiring';render()"><small>${esc(r.dept)}</small><strong>${esc(r.short)}</strong><span>${x?esc(x.name):unlocked?'Open search →':'Unlocks at '+V123_scaleName(r.unlock)}</span></button>`}).join('')}</div></section>`}
function V123_strategyPanel(){const e=V123_execState(),current=V123_STRATEGIES[e.strategy];return `<section class="card"><span class="eyebrow">COMPANY STRATEGY</span><h2>${esc(current.name)}</h2><p>${esc(current.desc)}</p><div class="v123-strategy-grid">${Object.entries(V123_STRATEGIES).map(([id,x])=>`<button class="${e.strategy===id?'selected':''}" onclick="V123_changeStrategy('${id}')"><strong>${esc(x.name)}</strong><small>${esc(x.desc)}</small></button>`).join('')}</div></section><section class="card"><span class="eyebrow">OPERATING POLICY</span><h2>Cash guardrails</h2><form class="form" onsubmit="event.preventDefault();V123_setReserveFloor(this.elements.reserve.value)"><label>Company reserve floor<input type="number" name="reserve" min="0" step="1000" value="${Math.round(e.policies.reserveFloor||0)}"></label><button class="primary">Update reserve policy</button></form><p class="fine">Guardrails and Full Authority should not spend below this floor. Executive payroll still remains a contractual company obligation.</p></section>`}
function V123_meetingsPanel(){const meetings=V123_execState().meetings;return `<section class="card"><div class="sectionhead"><div><span class="eyebrow">EXECUTIVE MEETINGS</span><h2>Leadership should disagree sometimes.</h2></div><button class="secondary" onclick="V123_generateMeeting(true);render()">Call special meeting</button></div><p>Major decisions surface as proposals with competing tradeoffs. The choice can affect money, operating plans, trust and strategic alignment.</p>${meetings.map(m=>`<button class="v123-meeting-row ${m.status}" onclick="${m.status==='open'?`V123_openMeeting(${m.id})`:''}"><span><small>WEEK ${m.week} · ${esc(V123_EXEC_ROLES[m.lead]?.short||'Executive Office')}</small><strong>${esc(m.title)}</strong><em>${m.status==='open'?'Decision required':esc(m.choiceLabel||'Resolved')}</em></span><b>${m.status==='open'?'Review →':'Closed'}</b></button>`).join('')||'<p class="fine">Meetings begin after executives are hired and recur as the company develops.</p>'}</section>`}
function V123_hiringPanel(){const e=V123_execState(),roles=Object.entries(V123_EXEC_ROLES).filter(([role])=>!e.team[role]),role=roles.some(([id])=>id===V123_hiringRole)?V123_hiringRole:(roles[0]?.[0]||'chief'),r=V123_EXEC_ROLES[role];if(!r)return '<section class="card"><h2>Every executive seat is filled.</h2></section>';V123_hiringRole=role;return `<section class="card"><span class="eyebrow">EXECUTIVE SEARCH</span><h2>Hire for the company, not the artist.</h2><p>Compensation is salary + performance bonus, with rare equity asks at the highest levels. Candidates differ in skill, reputation and operating style.</p><div class="chips">${roles.map(([id,x])=>`<button ${!V123_roleUnlocked(id)?'disabled':''} class="${id===role?'selected':''}" onclick="V123_hiringRole='${id}';render()">${esc(x.short)}</button>`).join('')}</div></section>${V123_roleUnlocked(role)?`<div class="v123-candidate-grid">${V123_candidates(role).map(c=>`<article class="v123-candidate"><span class="eyebrow">${esc(r.dept.toUpperCase())}</span><h3>${esc(c.name)}</h3><p>${esc(c.styleName)} · ${esc(c.specialty)}</p>${profileRows([['Skill',c.skill+'/100'],['Reputation',c.reputation+'/100'],['Salary',money(c.salary)+'/yr'],['Bonus',c.bonusPct+'%'],['Equity',c.equityBps?(c.equityBps/100).toFixed(2)+'%':'None']])}<p class="fine">${esc(c.styleDesc)}</p><button class="primary" onclick="V123_reviewCandidate('${role}','${c.id}')">Review candidate →</button></article>`).join('')}</div><button class="secondary" onclick="V123_refreshMarket('${role}')">Refresh ${esc(r.short)} search</button>`:`<section class="card"><h2>${esc(r.short)} is not justified yet.</h2><p>This seat unlocks at ${esc(V123_scaleName(r.unlock))}. Grow audience, company assets or your owned label first.</p></section>`}`}
function V123_historyPanel(){const e=V123_execState();return `<section class="card"><span class="eyebrow">ORGANIZATION & HISTORY</span><h2>The company remembers who built it.</h2>${profileRows([['Company stage',V123_scaleName()],['Founder ownership',V123_founderOwnership().toFixed(2)+'%'],['Executive seats filled',String(Object.keys(e.team).length)],['Weekly executive payroll',money(V123_totalPayroll())],['Resolved executive decisions',String(e.meetings.filter(x=>x.status==='resolved').length)]])}<h3>Leadership record</h3>${e.history.slice(0,30).map(x=>`<div class="story"><small>WEEK ${x.week} · ${esc(x.type.toUpperCase())}</small>${esc(x.detail)}</div>`).join('')||'<p class="fine">Hires, strategy changes, authority changes, bonuses, resignations and departures will build the executive record.</p>'}</section><section class="card"><span class="eyebrow">PERSONAL TEAM</span><h2>Representation stays separate.</h2><p>Your manager, booking agent, personal attorney, business manager, publicist, CPA and other artist-side specialists remain in Representation. The Executive Office governs the company itself.</p><button class="secondary" onclick="careerTab='Agency';go('Career')">Open Artist Representation →</button></section>`}
function V123_teamPage(){V123_execState();const tabs=['Leadership','Strategy','Meetings','Hiring','Organization'];const body=V123_execTab==='Strategy'?V123_strategyPanel():V123_execTab==='Meetings'?V123_meetingsPanel():V123_execTab==='Hiring'?V123_hiringPanel():V123_execTab==='Organization'?V123_historyPanel():V123_leadershipPanel();return head('Run the company, not every task','Executive Office.')+`<nav class="v123-tabs">${tabs.map(x=>`<button class="${V123_execTab===x?'selected':''}" onclick="V123_execTab='${x}';render()">${x}${x==='Meetings'&&V123_execState().meetings.some(m=>m.status==='open')?' •':''}</button>`).join('')}</nav>${body}`}
teamPage=V123_teamPage;

/* Re-label Business HQ so personal representation and company leadership are no longer conflated. */
for(const area of V096_BUSINESS_AREAS||[]){if(area.id==='Agency'){area.name='Artist representation';area.desc='Your personal manager, agent, attorney, publicist, CPA and specialist team'}if(area.id==='Team'){area.name='Executive Office';area.desc='Company leadership, strategy, delegation, meetings and executive performance'}}
if(typeof V109_HQ_GROUPS!=='undefined'){const company=V109_HQ_GROUPS.find(x=>x.id==='Company');if(company)company.desc='Your label, industry position, artist representation and company leadership.'}
const V123_badgeBase=V096_businessAreaBadge;
V096_businessAreaBadge=function(id){if(id==='Team')return V123_execState().meetings.filter(x=>x.status==='open').length;return V123_badgeBase(id)};
if(typeof V109_businessPriorityItems==='function'){
 const V123_priorityBase=V109_businessPriorityItems;
 V109_businessPriorityItems=function(){const base=V123_priorityBase(),exec=V123_execState().meetings.filter(x=>x.status==='open').map(m=>({key:'exec:'+m.id,kind:'Executive decision',title:m.title,detail:(V123_EXEC_ROLES[m.lead]?.short||'Leadership')+' recommendation · Week '+m.week,priority:7,action:`V123_openMeeting(${m.id})`}));return [...exec,...base].sort((a,b)=>(b.priority||0)-(a.priority||0)).slice(0,8)}
}

/* ENCORE 0.9.20 — Legal Affairs 2.0.
   Expands the civil docket from label-only contract disputes into a career-wide
   legal-risk simulation with cause-based filings, General Counsel integration,
   prevention, outside counsel and player-visible risk forecasting. */

const V124_LEGAL_TYPES={
 copyright:{name:'Copyright / sample dispute',category:'Music IP',issue:'Copyright, sample or composition infringement',claim:1.25,strength:58,prevent:'Clear samples, keep stronger legal review and avoid an oversized uncleared catalog.'},
 credit:{name:'Songwriting credit dispute',category:'Music IP',issue:'Songwriting credit / ownership dispute',claim:.8,strength:54,prevent:'Keep collaborator relationships healthy and document splits before release.'},
 producer:{name:'Producer royalty dispute',category:'Music IP',issue:'Producer royalty / accounting dispute',claim:.95,strength:56,prevent:'Use clear producer terms and accurate royalty accounting.'},
 venue:{name:'Tour / venue contract dispute',category:'Live',issue:'Venue, promoter or cancellation breach',claim:1.35,strength:57,prevent:'Keep routing realistic, honor booked dates and use stronger live operations.'},
 injury:{name:'Live-event injury claim',category:'Live',issue:'Negligence / live-event personal injury',claim:1.6,strength:61,prevent:'Fund security, avoid overextended routing and reduce live incidents.'},
 employment:{name:'Employment / termination claim',category:'Corporate',issue:'Employment, termination or compensation dispute',claim:.9,strength:55,prevent:'Use stable leadership, fair exits and General Counsel review around departures.'},
 merch:{name:'Merch / vendor dispute',category:'Commerce',issue:'Vendor, manufacturing or merchandise contract dispute',claim:.7,strength:52,prevent:'Keep vendor volume manageable and avoid scaling merchandise faster than operations.'},
 sponsor:{name:'Sponsorship / endorsement dispute',category:'Commercial',issue:'Sponsorship, endorsement or deliverables dispute',claim:1.1,strength:55,prevent:'Avoid overcommitting brand obligations and maintain commercial review.'},
 trademark:{name:'Trademark / name dispute',category:'IP',issue:'Trademark, likeness or brand-confusion dispute',claim:1.35,strength:59,prevent:'Protect the artist/company identity as the brand becomes more valuable.'},
 defamation:{name:'Defamation / publication claim',category:'Media',issue:'Defamation, false-light or publication dispute',claim:.9,strength:53,prevent:'Reduce reckless public conflict and use counsel on high-risk public statements.'},
 property:{name:'Property / lease dispute',category:'Assets',issue:'Property, lease, contractor or premises dispute',claim:1.15,strength:56,prevent:'Maintain owned property and keep business-use/property obligations documented.'},
 label:{name:'Label interference / poaching claim',category:'Industry',issue:'Interference, solicitation or label-to-label contract dispute',claim:1.8,strength:62,prevent:'Use clean roster negotiations and legal review around poaching or contract exits.'},
 tax:{name:'Tax / regulatory matter',category:'Regulatory',issue:'Tax assessment, records or regulatory compliance matter',claim:1.0,strength:64,prevent:'Use qualified finance/legal staff, maintain reserves and keep entity administration current.'},
 sports:{name:'Sports ownership dispute',category:'Ownership',issue:'Ownership, governance or partner dispute',claim:2.5,strength:61,prevent:'Use strong governance and legal review around high-value ownership positions.'},
 partnership:{name:'Business partnership dispute',category:'Corporate',issue:'Commercial partnership, ownership or performance dispute',claim:1.3,strength:57,prevent:'Document ownership, obligations and exit terms before scaling partnerships.'}
};

function V124_legalState(){
 const root=V118_state();
 if(!root.legalRisk||typeof root.legalRisk!=='object')root.legalRisk={version:1,startedWeek:s.week,lastGeneratedWeek:0,lastByType:{},generated:0,lastChance:0,lastScore:0};
 const x=root.legalRisk;x.version=1;x.startedWeek??=s.week;x.lastGeneratedWeek??=0;x.lastByType??={};x.generated??=0;x.lastChance??=0;x.lastScore??=0;return x
}
function V124_hash(value){let h=2166136261;for(const ch of String(value)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function V124_roll(key){return V124_hash(`${key}|${s.week}|${s.name||''}`)/4294967296}
function V124_log10(n){return Math.log10(Math.max(1,Number(n)||0))}
function V124_ctx(){
 const songs=Array.isArray(s.songs)?s.songs:[],world=Array.isArray(s.world)?s.world:[],emp=s.empire||{},assets=Array.isArray(emp.assets)?emp.assets:[],merch=Array.isArray(emp.merch)?emp.merch:[],media=Array.isArray(emp.media)?emp.media:[],contracts=Array.isArray(s.labelBusiness?.company?.contracts)?s.labelBusiness.company.contracts:[],exec=typeof V123_execState==='function'?V123_execState():{team:{},history:[]};
 const routes=[...(Array.isArray(s.touring?.archive)?s.touring.archive.flatMap(t=>Array.isArray(t.route)?t.route:[]):[]),...(Array.isArray(s.liveTour?.route)?s.liveTour.route:[])];
 const played=routes.filter(r=>['played','completed'].includes(r.status)),cancelled=routes.filter(r=>r.status==='cancelled'),incidents=played.filter(r=>r.report?.incident).length;
 const collaborators=songs.reduce((n,x)=>n+(Array.isArray(x.guests)?x.guests.length:Array.isArray(x.features)?x.features.length:0),0);
 const properties=assets.filter(a=>String(a.kind||'').toLowerCase().includes('property')).length;
 const sports=assets.filter(a=>/sport|team|franchise/i.test(`${a.kind||''} ${a.name||''} ${a.item||''}`)).length;
 const businesses=Array.isArray(emp.businesses)?emp.businesses.length:assets.filter(a=>/business|company|store|laund|rental/i.test(`${a.kind||''} ${a.name||''}`)).length;
 const recentExecDepartures=(exec.history||[]).filter(x=>['departure','resignation'].includes(x.type)&&s.week-(x.week||0)<=26).length;
 const negativeIndustry=world.filter(a=>Number(a.relation||0)<=-25).length;
 const feed=Array.isArray(s.social?.feed)?s.social.feed:[];
 const merchSold=merch.reduce((n,x)=>n+Math.max(0,Number(x.sold)||0),0),mediaUsed=media.filter(x=>x.used).length;
 let entity='individual';if(typeof V113_entity==='function')entity=V113_entity().id||'individual';
 return {songs:songs.length,collaborators,played:played.length,cancelled:cancelled.length,incidents,merch:merch.length,merchSold,mediaUsed,properties,sports,businesses,contracts:contracts.length,execCount:Object.keys(exec.team||{}).length,recentExecDepartures,negativeIndustry,feed:feed.length,entity,fans:Math.max(0,Number(s.fans)||0),cash:Math.max(0,Number(s.cash)||0),reputation:Math.max(0,Number(s.reputation)||0),assets:assets.length,label:Boolean(s.labelBusiness?.company)}
}
function V124_scores(ctx=V124_ctx()){
 const entityWeight={individual:0,llc:1,entertainment:2,corporation:3,holding:4}[ctx.entity]||0;
 const score={
  copyright:ctx.songs>=2?8+ctx.songs*1.2+ctx.collaborators*2+ctx.reputation*.06:0,
  credit:ctx.songs>=4||ctx.collaborators?5+ctx.songs*.75+ctx.collaborators*3:0,
  producer:ctx.songs>=3?5+ctx.songs+ctx.collaborators:0,
  venue:ctx.played+ctx.cancelled>=2?5+ctx.played*.7+ctx.cancelled*7:0,
  injury:ctx.played?3+ctx.played*.55+ctx.incidents*15:0,
  employment:ctx.execCount||ctx.recentExecDepartures?3+ctx.execCount*1.5+ctx.recentExecDepartures*16:0,
  merch:ctx.merchSold>=100?4+V124_log10(ctx.merchSold)*8+ctx.merch*2:0,
  sponsor:ctx.mediaUsed?4+ctx.mediaUsed*4+V124_log10(ctx.fans)*2:0,
  trademark:ctx.fans>=250000||ctx.label?5+V124_log10(ctx.fans)*5+(ctx.label?8:0):0,
  defamation:ctx.feed>=5?3+ctx.feed*.45+ctx.negativeIndustry*2+ctx.reputation*.05:0,
  property:ctx.properties?4+ctx.properties*7+ctx.assets:0,
  label:ctx.contracts>=2?4+ctx.contracts*7+ctx.negativeIndustry*2:0,
  tax:entityWeight?5+entityWeight*9+V124_log10(ctx.cash)*2.5:0,
  sports:ctx.sports?10+ctx.sports*12+V124_log10(ctx.cash)*3:0,
  partnership:ctx.businesses?5+ctx.businesses*8+ctx.assets*.8:0
 };
 for(const k of Object.keys(score))score[k]=clamp(Math.round(score[k]),0,100);return score
}
function V124_counsel(){
 const gc=typeof V123_execState==='function'?V123_execState().team?.legal:null;
 if(gc)return {name:gc.name,skill:typeof V123_effectiveSkill==='function'?V123_effectiveSkill(gc):gc.skill||70,type:'General Counsel',authority:gc.authority||'hands'};
 const attorney=typeof V100_repTeam==='function'?V100_repTeam()?.team?.attorney:null;
 if(attorney)return {name:attorney.name,skill:typeof V117_effectiveSkill==='function'?V117_effectiveSkill(attorney):attorney.skill||70,type:'Personal attorney',authority:'hands'};
 return null
}
function V124_prevention(){const c=V124_counsel();if(!c)return 0;let reduction=Math.min(.24,(c.skill||0)*.0024);if(c.type==='General Counsel'){if(c.authority==='guardrails')reduction+=.07;if(c.authority==='full')reduction+=.11;if(c.authority==='recommend')reduction+=.03}return clamp(reduction,0,.42)}
function V124_snapshot(){
 const st=V124_legalState(),scores=V124_scores(),entries=Object.entries(scores).filter(([,v])=>v>0).map(([id,score])=>({id,score,...V124_LEGAL_TYPES[id]})).sort((a,b)=>b.score-a.score),total=entries.reduce((n,x)=>n+x.score,0),open=V118_openCases().length,prevention=V124_prevention(),cooldown=s.sandbox?3:6,recent=s.week-st.lastGeneratedWeek<cooldown;
 let raw=total?Math.min(.055,.0015+total*.000035):0;if(s.sandbox)raw=Math.min(.09,raw*1.8);if(open===1)raw*=.75;if(open===2)raw*=.5;if(open>=3||recent)raw=0;const chance=clamp(raw*(1-prevention),0,.09);st.lastChance=chance;st.lastScore=total;return {scores,entries,total,open,prevention,chance,recent,counsel:V124_counsel()}
}
function V124_companyValue(){return typeof V092_businessValue==='function'?Math.max(0,Number(V092_businessValue())||0):0}
function V124_claim(type,score){const spec=V124_LEGAL_TYPES[type],base=clamp(Math.max(50000,s.cash*.012+s.fans*.06+V124_companyValue()*.0015),50000,25000000),swing=.72+V124_roll('claim:'+type)*.62;return cents(clamp(base*spec.claim*swing*(.72+score/180),25000,100000000))}
function V124_strength(type,score){const spec=V124_LEGAL_TYPES[type];return clamp(Math.round(spec.strength+(score-40)*.18+(V124_roll('strength:'+type)-.5)*12),30,94)}
function V124_claimant(type){
 const names={copyright:'Northline Publishing',credit:'A former co-writer',producer:'A former producer',venue:'Regional Venue Partners',injury:'A concert attendee',employment:'A former company employee',merch:'Meridian Manufacturing',sponsor:'Atlas Brand Group',trademark:'A competing entertainment brand',defamation:'An industry figure',property:'A property counterparty',label:'A competing label',tax:'Revenue Compliance Bureau',sports:'A minority ownership partner',partnership:'A commercial partner'};
 if(['defamation','label','credit'].includes(type)&&Array.isArray(s.world)&&s.world.length){const a=s.world[V124_hash(type+s.week)%s.world.length];if(a?.name)return type==='label'?a.name+' / affiliated label':a.name}
 return names[type]||'Counterparty'
}
function V124_triggerDetail(type,ctx){const map={copyright:`${ctx.songs} songs and ${ctx.collaborators} credited collaborators have expanded music-rights exposure.`,credit:`A growing catalog and ${ctx.collaborators} collaborator credits create split/credit pressure.`,producer:`${ctx.songs} recorded works create more producer-accounting touchpoints.`,venue:`${ctx.played} played shows and ${ctx.cancelled} cancellations create promoter/venue exposure.`,injury:`${ctx.played} completed shows with ${ctx.incidents} recorded live incidents create premises/injury risk.`,employment:`${ctx.execCount} executives and ${ctx.recentExecDepartures} recent leadership departures create employment exposure.`,merch:`${ctx.merchSold} lifetime merch units sold across ${ctx.merch} products create vendor exposure.`,sponsor:`${ctx.mediaUsed} completed media/brand opportunities create deliverables risk.`,trademark:`A ${compact(ctx.fans)}-fan brand and growing company identity create name/likeness exposure.`,defamation:`${ctx.feed} PULSE posts and ${ctx.negativeIndustry} strained industry relationships create publication risk.`,property:`${ctx.properties} owned property assets create lease, contractor and premises exposure.`,label:`${ctx.contracts} roster contracts and ${ctx.negativeIndustry} strained industry relationships create interference risk.`,tax:`Your ${ctx.entity} structure and current company scale create more records/compliance exposure.`,sports:`${ctx.sports} sports ownership positions create governance and partner exposure.`,partnership:`${ctx.businesses} business interests and ${ctx.assets} owned assets create commercial-counterparty exposure.`};return map[type]||'Career activity created a legal exposure.'}
function V124_pickType(snapshot){let pool=snapshot.entries.map(x=>({...x,weight:x.score})).filter(x=>{const last=V124_legalState().lastByType[x.id]||0;return s.week-last>=16});if(!pool.length)pool=snapshot.entries.map(x=>({...x,weight:x.score*.25}));const sum=pool.reduce((n,x)=>n+x.weight,0);if(!sum)return null;let needle=V124_roll('legal-type')*sum;for(const x of pool){needle-=x.weight;if(needle<=0)return x}return pool.at(-1)}
function V124_generateMatter(type=null,forced=false){
 const st=V124_legalState(),snap=V124_snapshot(),ctx=V124_ctx(),pick=type&&V124_LEGAL_TYPES[type]?{id:type,score:V124_scores(ctx)[type]||35,...V124_LEGAL_TYPES[type]}:V124_pickType(snap);if(!pick)return null;
 const claim=V124_claim(pick.id,pick.score),plaintiff=V124_claimant(pick.id),detail=V124_triggerDetail(pick.id,ctx),c=V118_fileCase({title:`${plaintiff} v. ${s.labelBusiness?.company?.name||s.name}`,issue:pick.issue,plaintiff,claim,strength:V124_strength(pick.id,pick.score),clauses:[pick.category],matterType:pick.id,category:pick.category,triggerDetail:detail,preventText:pick.prevent,riskScore:pick.score,generatedBy:'legal-risk'});
 if(!c)return null;c.filingKind=pick.id==='tax'?'Regulatory matter':'Civil claim';c.triggerDetail=detail;c.preventText=pick.prevent;c.riskScore=pick.score;c.category=pick.category;c.matterType=pick.id;c.generatedBy='legal-risk';st.lastGeneratedWeek=s.week;st.lastByType[pick.id]=s.week;st.generated++;V118_event('legal-risk',pick.name,detail,{caseId:c.id});addBriefing?.('legal-risk:'+c.id,'Legal',pick.name+' filed',detail+' Exposure: '+money(claim)+'.');if(forced)toast?.('Sandbox legal matter generated for testing.');return c
}
function V124_legalRiskWeek(){const st=V124_legalState();if(st.lastCheckedWeek===s.week)return null;st.lastCheckedWeek=s.week;const snap=V124_snapshot();if(!snap.entries.length)return null;const sandboxGuarantee=!!s.sandbox&&st.generated===0&&s.week-st.startedWeek>=6&&snap.total>=80;if(sandboxGuarantee||V124_roll('legal-week')<snap.chance)return V124_generateMatter(null,sandboxGuarantee);return null}

/* Every filing now prefers corporate General Counsel when one exists. Personal
   representation remains a fallback, and legacy label disputes get the same upgrade. */
const V124_fileCaseBase=V118_fileCase;
V118_fileCase=function(spec={}){const c=V124_fileCaseBase(spec);if(!c)return c;const counsel=V124_counsel();if(counsel){c.assignedAttorney=counsel.name;c.attorneySkill=counsel.skill;c.counselType=counsel.type;c.counselAuthority=counsel.authority}for(const key of ['matterType','category','triggerDetail','preventText','riskScore','generatedBy','filingKind'])if(spec[key]!==undefined)c[key]=spec[key];return c};

function V124_assignGeneralCounsel(id){const c=V118_legalCases().find(x=>x.id===id&&x.status==='open'),gc=typeof V123_execState==='function'?V123_execState().team?.legal:null;if(!c||!gc)return false;c.assignedAttorney=gc.name;c.attorneySkill=typeof V123_effectiveSkill==='function'?V123_effectiveSkill(gc):gc.skill||70;c.counselType='General Counsel';c.counselAuthority=gc.authority;c.history.unshift({week:s.week,text:'General Counsel assumed lead responsibility for the matter.'});queueSave?.();render();V118_openDocketCase(id);return true}
function V124_outsideCost(c){return cents(clamp(c.claim*.015,5000,250000))}
function V124_retainOutsideCounsel(id){const c=V118_legalCases().find(x=>x.id===id&&x.status==='open');if(!c)return false;const cost=V124_outsideCost(c);if(s.cash<cost){toast?.('Not enough cash for outside counsel.');return false}changeCash(-cost);if(s.finance?.week)s.finance.week.expenses=cents((s.finance.week.expenses||0)+cost);c.attorneySkill=clamp(Math.max(c.attorneySkill||0,72)+12,0,100);c.counselType=c.counselType==='General Counsel'?'General Counsel + outside litigation':'Outside litigation counsel';c.assignedAttorney=c.assignedAttorney||'Outside litigation counsel';c.history.unshift({week:s.week,text:'Outside litigation counsel retained: '+money(cost)+'.'});queueSave?.();render();V118_openDocketCase(id);return true}
function V124_mediationCost(c){return cents(clamp(c.claim*.0125,2500,150000))}
function V124_mediateCase(id){const c=V118_legalCases().find(x=>x.id===id&&x.status==='open');if(!c||c.stage!=='FILED')return false;const fee=V124_mediationCost(c);if(!spend(5,fee))return false;c.history.unshift({week:s.week,text:'Pretrial mediation opened. Legal spend '+money(fee)+'.'});const counsel=Math.max(0,c.attorneySkill||0),score=counsel*.55+s.reputation*.12-c.plaintiffStrength*.42+(V124_roll('mediate:'+c.number)-.5)*35;if(score>=10){const amount=cents(c.claim*clamp(.32+c.plaintiffStrength*.0022,.34,.56));if(s.cash<amount){c.history.unshift({week:s.week,text:'Mediation produced terms, but the company could not fund the settlement.'});render();return false}changeCash(-amount);if(s.finance?.week)s.finance.week.expenses=cents((s.finance.week.expenses||0)+amount);c.history.unshift({week:s.week,text:'Mediated settlement paid: '+money(amount)+'.'});V118_closeCase(c,'Resolved through mediation',0,0);$('modal')?.close?.();render();toast?.(c.number+' resolved through mediation.');return true}c.deadlineWeek+=1;c.history.unshift({week:s.week,text:'Mediation ended without agreement. Response deadline extended one week.'});$('modal')?.close?.();render();toast?.('No settlement. The response deadline moved one week.');return false}

const V124_caseActionBase=V118_caseAction;
