/* ENCORE 1.29 — persistent, player-controlled appearance. */
const V129_SKINS=['#6b3f2d','#87543c','#a66d4d','#c18b68','#d8a887','#edc7a4','#f4d8bc'];
const V129_HAIRS=['#171311','#35251d','#68452e','#b08a4e','#b85b38','#d5c4a0','#6c747b','#9b466f'];
const V129_STYLES=['Close fade','Short curls','Waves','Locs','Long straight','Braids'];
const V129_EYES=['#302019','#68452e','#527b69','#6585a8','#7a604b','#72777d'];
function V129_default(){return {skin:2,hair:0,style:1,eyes:0,gender:'masculine',facialHair:0}}
let V129_draft=null,V129_returnFocus=null;
function V129_normalize(value){const a=V129_default();for(const [k,n] of Object.entries({skin:7,hair:8,style:6,eyes:6,facialHair:2})){const v=value?.[k];if(Number.isInteger(v)&&v>=0&&v<n)a[k]=v}return a}
function V129_get(){return V129_normalize(s.appearance)}
function V129_portrait(a){
 const skin=V129_SKINS[a.skin]||V129_SKINS[2],hair=V129_HAIRS[a.hair]||V129_HAIRS[0],eyes=V129_EYES[a.eyes]||V129_EYES[0];
 const styles=[`<path d="M25 40Q21 12 50 12Q80 12 75 40L67 30Q50 22 33 31Z" fill="${hair}"/>`,`<path d="M22 39Q23 9 50 12Q78 10 78 39L70 28Q50 20 30 30Z" fill="${hair}"/><circle cx="29" cy="29" r="8" fill="${hair}"/><circle cx="70" cy="28" r="8" fill="${hair}"/>`,`<path d="M23 39Q23 10 50 12Q78 10 77 39L72 65H64L67 30Q50 21 33 30L36 65H28Z" fill="${hair}"/>`,`<path d="M22 38Q22 10 50 12Q78 10 78 38L73 72H65L67 28L57 73H49L50 27L40 73H32L34 29L27 68Z" fill="${hair}"/>`,`<path d="M23 38Q22 10 50 12Q78 10 77 38L80 88H69L66 30Q50 21 34 30L31 88H20Z" fill="${hair}"/>`,`<path d="M22 38Q22 10 50 12Q78 10 78 38L75 78H67L68 29L58 76H50L50 27L40 76H32L33 29L25 78Z" fill="${hair}"/>`];
 return `<svg viewBox="0 0 100 100" role="img" aria-label="Your customized character portrait"><rect width="100" height="100" rx="10" fill="#263746"/><path d="M8 100Q15 70 36 68H64Q85 70 92 100" fill="#d8b45f"/><path d="M40 60H60V75H40Z" fill="${skin}"/><ellipse cx="50" cy="43" rx="23" ry="28" fill="${skin}"/>${styles[a.style]||styles[1]}<path d="M37 42h9M54 42h9" stroke="#302019" stroke-width="2" stroke-linecap="round"/><circle cx="42" cy="44" r="2.3" fill="${eyes}"/><circle cx="58" cy="44" r="2.3" fill="${eyes}"/><path d="M50 45l-2 9h5M42 61q8 5 16 0" fill="none" stroke="#704735" stroke-width="1.6" stroke-linecap="round"/>${a.facialHair?'<path d="M35 56Q50 73 65 56L61 69Q50 78 39 69Z" fill="'+hair+'"/>':''}</svg>`
}
function V129_open(){if(document.getElementById('v129-character-editor'))return;V129_returnFocus=document.activeElement;V129_draft=V129_get();V129_draw()}
function V129_draw(){const a=V129_draft;document.getElementById('v129-character-editor')?.remove();
 const el=document.createElement('div');el.id='v129-character-editor';el.className='v129-overlay';el.innerHTML=`<section class="v129-sheet" role="dialog" aria-modal="true" aria-labelledby="v129-title"><header><div><small>ENCORE · IDENTITY</small><h2 id="v129-title">Create your artist</h2><p>Your look is yours. Change it whenever you want.</p></div><button class="v129-close" onclick="V129_close()" aria-label="Close">×</button></header><div class="v129-preview" id="v129-preview">${V129_portrait(a)}<div><strong>${esc(s.name||'Your artist')}</strong><span>Appearance preview</span></div></div><div class="v129-fields">
 <label>Skin tone<div class="v129-swatches">${V129_SKINS.map((c,i)=>`<button data-field="skin" data-value="${i}" aria-pressed="${a.skin===i}" aria-label="Skin tone ${i+1}" class="${a.skin===i?'selected':''}" style="background:${c}" onclick="V129_set('skin',${i})"></button>`).join('')}</div></label>
 <label>Hair color<div class="v129-swatches">${V129_HAIRS.map((c,i)=>`<button data-field="hair" data-value="${i}" aria-pressed="${a.hair===i}" aria-label="Hair color ${i+1}" class="${a.hair===i?'selected':''}" style="background:${c}" onclick="V129_set('hair',${i})"></button>`).join('')}</div></label>
 <label>Hair style<select name="style" onchange="V129_set('style',this.value)">${V129_STYLES.map((v,i)=>`<option value="${i}" ${a.style===i?'selected':''}>${v}</option>`).join('')}</select></label>
 <label>Eye color<select name="eyes" onchange="V129_set('eyes',this.value)">${V129_EYES.map((v,i)=>`<option value="${i}" ${a.eyes===i?'selected':''}>${['Dark brown','Brown','Hazel green','Blue','Light brown','Gray'][i]}</option>`).join('')}</select></label>
 <label class="v129-check"><input type="checkbox" ${a.facialHair?'checked':''} onchange="V129_set('facialHair',this.checked?1:0)"> Facial hair</label>
 </div><footer><button class="v129-reset" onclick="V129_reset()">Reset appearance</button><button class="v129-save" onclick="V129_save()">Save appearance</button></footer></section>`;
 el.addEventListener('click',e=>{if(e.target===el)V129_close()});document.body.appendChild(el);el.querySelector('.v129-close').focus();el.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();V129_close()}if(e.key==='Tab'){const items=[...el.querySelectorAll('button,select,input')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}})}
function V129_set(k,v){if(!V129_draft||!['skin','hair','style','eyes','facialHair'].includes(k))return;V129_draft=V129_normalize({...V129_draft,[k]:Number(v)});const a=V129_draft;document.getElementById('v129-preview').innerHTML=V129_portrait(a)+'<div><strong>'+esc(s.name||'Your artist')+'</strong><span>Appearance preview</span></div>';document.querySelectorAll('#v129-character-editor [data-field]').forEach(b=>{const selected=a[b.dataset.field]===Number(b.dataset.value);b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})}
function V129_reset(){V129_draft=V129_default();V129_draw()}
async function V129_save(){if(!V129_draft||!saveReady||saveConflict)return;s.appearance=V129_normalize(V129_draft);V129_close();render();await saveNow()}
function V129_close(){document.getElementById('v129-character-editor')?.remove();V129_draft=null;if(V129_returnFocus?.isConnected)V129_returnFocus.focus()}
const V129_oldArtistFile=artistFilePage;
artistFilePage=function(){return V129_oldArtistFile().replace('</header>','<div class="v129-entry"><button class="secondary v129-edit-button" onclick="V129_open()">Edit appearance</button></div></header>')};
const V129_oldPersonPhoto=personPhoto;
personPhoto=function(key,name,large=false){if(key==='player-'+s.name&&s.appearance)return '<span class="person-photo v129-portrait '+(large?'portrait-large':'')+'">'+V129_portrait(V129_get())+'</span>';return V129_oldPersonPhoto(key,name,large)};

/* ENCORE 0.9.24 — Music Platforms 2.0, visual certification plaques and simplified song setup.
   Platform actions add bounded future-discovery effects without duplicating the authoritative stream total. */
const V130_PLATFORM_ACTIONS={
 vybe:{label:'Push focus track',placement:'Focus Track Push',lift:.05,weeks:2,detail:'Put one record in front of VYBE’s algorithm. Saves, commercial appeal and momentum still decide whether it sticks.'},
 muse:{label:'Submit for editorial',placement:'Editorial Submission',lift:.04,weeks:4,detail:'Put a finished record in front of MUSE editors. Albums, quality and library behavior matter most.'},
 amp:{label:'Start community push',placement:'Community Push',lift:.035,weeks:2,detail:'Seed the record through AMP’s creator community. Reposts and emerging-artist energy matter more than polish.'},
 worldwave:{label:'Service global radio',placement:'International Radio Service',lift:.04,weeks:4,detail:'Send one record into WORLDWAVE’s radio network. Reputation and durable crossover demand matter most.'}
};
function V130_service(id){const p=V114_state(),svc=p.services[id];svc.strategy=svc.strategy&&typeof svc.strategy==='object'?svc.strategy:{lastActionWeek:-999,focusSongId:null,history:[]};svc.strategy.history=Array.isArray(svc.strategy.history)?svc.strategy.history:[];return svc}
function V130_serviceTracks(id){return V114_topTracks(id,20)}
function V130_bestTrack(id){return V130_serviceTracks(id)[0]?.row||(s.songs||[]).filter(x=>x.released).sort((a,b)=>(b.streams||0)-(a.streams||0))[0]||null}
function V130_trackOptions(id){const rows=V130_serviceTracks(id),seen=new Set(rows.map(x=>Number(x.row.id))),rest=(s.songs||[]).filter(x=>x.released&&!seen.has(Number(x.id))).map(row=>({row,stats:V114_trackService()}));return [...rows,...rest].slice(0,30).map(x=>`<option value="${x.row.id}">${esc(x.row.title)} · ${compact(x.stats.thisWeek||x.row.streams||0)} this week</option>`).join('')}
function V130_runPlatformAction(id,songId){const cfg=V130_PLATFORM_ACTIONS[id],p=V114_state(),svc=V130_service(id),track=(s.songs||[]).find(x=>Number(x.id)===Number(songId)&&x.released);if(!cfg||!track)return false;if(svc.strategy.lastActionWeek===s.week){toast?.(`${V114_AUDIO_PLATFORMS[id].name} already has a strategy push this week.`);return false}if(!spend(5))return false;const lift=cfg.lift;V114_place(p,id,track,cfg.placement,lift,cfg.weeks);track.platformLiftNext=clamp(V114_num(track.platformLiftNext)+lift,0,.25);svc.strategy.lastActionWeek=s.week;svc.strategy.focusSongId=track.id;svc.strategy.history.unshift({week:s.week,songId:track.id,title:track.title,action:cfg.label,lift});svc.strategy.history=svc.strategy.history.slice(0,24);if(id==='vybe')svc.playlistReach=Math.max(svc.playlistReach,Math.round((svc.monthlyListeners||0)*.12));if(id==='muse')svc.editorialAdds=Math.max(0,V114_num(svc.editorialAdds)+1);if(id==='amp')svc.reposts=Math.max(0,V114_num(svc.reposts)+Math.max(1,Math.round(Math.sqrt(Math.max(1,svc.currentWeekStreams||1))/6)));if(id==='worldwave')svc.radioSpins=Math.max(0,V114_num(svc.radioSpins)+Math.max(1,Math.round(Math.sqrt(Math.max(1,svc.currentWeekStreams||1))/4)));V114_addEvent(p,{type:'strategy',service:id,songId:track.id,text:`${cfg.label}: ${track.title} on ${V114_AUDIO_PLATFORMS[id].name}.`});queueSave?.();render();toast?.(`${cfg.label} launched for ${track.title}.`);return true}
function V130_delta(svc){const a=(svc.weekly||[]).at(-1),b=(svc.weekly||[]).at(-2);if(!a||!b||!b.streams)return 0;return (V114_num(a.streams)-V114_num(b.streams))/Math.max(1,V114_num(b.streams))}
function V130_spark(svc,key='streams'){const rows=(svc.weekly||[]).slice(-8),max=Math.max(1,...rows.map(x=>V114_num(x[key])));return `<div class="v130-spark" aria-label="Recent ${esc(key)} trend">${rows.length?rows.map(x=>`<i style="--v:${Math.max(6,Math.round(V114_num(x[key])/max*100))}%" title="Week ${x.week}: ${compact(V114_num(x[key]))}"></i>`).join(''):'<span>No history yet</span>'}</div>`}
function V130_strategyCard(id){const cfg=V130_PLATFORM_ACTIONS[id],svc=V130_service(id),track=V130_bestTrack(id),used=svc.strategy.lastActionWeek===s.week;return `<aside class="v130-strategy"><span class="eyebrow">THIS WEEK’S MOVE</span><h3>${esc(cfg.label)}</h3><p>${esc(cfg.detail)}</p>${track?`<label>Focus record<select id="v130-focus-${id}">${V130_trackOptions(id)}</select></label><button class="primary" ${used?'disabled':''} onclick="V130_runPlatformAction('${id}',Number(document.getElementById('v130-focus-${id}').value))">${used?'Used this week':esc(cfg.label)+' · 5 energy'}</button>`:'<p class="fine">Release a song before using platform strategy.</p>'}${svc.strategy.history[0]?`<small>Last move: Week ${svc.strategy.history[0].week} · ${esc(svc.strategy.history[0].title)}</small>`:''}</aside>`}
function V130_trackRows(id,limit=6){const cfg=V114_AUDIO_PLATFORMS[id],rows=V114_topTracks(id,limit);return rows.length?rows.map((x,i)=>`<button class="v130-track" onclick="releaseDetails('songs',${x.row.songId})"><b>${String(i+1).padStart(2,'0')}</b><span><strong>${esc(x.row.title)}</strong><small>${compact(x.stats.thisWeek)} this week · ${compact(x.stats.lifetime)} lifetime on ${esc(cfg.name)}</small></span></button>`).join(''):'<p class="fine">No released music has activity here yet.</p>'}
function V130_vybePanel(){const svc=V130_service('vybe'),d=V130_delta(svc),top=V130_bestTrack('vybe'),saveRate=svc.currentWeekStreams?svc.saves/Math.max(1,svc.lifetimeStreams)*100:0;return `<section class="v130-platform v130-vybe"><header><div><span class="eyebrow">VYBE · ALGORITHM / MOMENTUM</span><h2>Win the next listen.</h2><p>VYBE rewards velocity. Saves, commercial appeal, social attention and repeat momentum determine whether a record keeps spreading.</p></div><div class="v130-hero-number"><small>THIS WEEK</small><strong>${compact(svc.currentWeekStreams)}</strong><span>${d>=0?'+':''}${Math.round(d*100)}% vs previous week</span></div></header><div class="v130-metrics"><div><span>Monthly listeners</span><strong>${compact(svc.monthlyListeners)}</strong></div><div><span>Saves</span><strong>${compact(svc.saves)}</strong></div><div><span>Playlist reach</span><strong>${compact(svc.playlistReach)}</strong></div><div><span>Catalog save signal</span><strong>${saveRate.toFixed(1)}%</strong></div></div><section class="v130-two"><div><span class="eyebrow">ALGORITHM PULSE</span>${V130_spark(svc)}<h3>${top?esc(top.title):'No focus record yet'}</h3><p>${top?'Your leading VYBE record right now. Watch its week-to-week curve instead of only lifetime totals.':'Release music to start building algorithm history.'}</p><div class="v130-list">${V130_trackRows('vybe')}</div></div>${V130_strategyCard('vybe')}</section></section>`}
function V130_musePanel(){const svc=V130_service('muse'),albums=[...(s.albums||[])].sort((a,b)=>albumStreams(b,true)-albumStreams(a,true)).slice(0,4);return `<section class="v130-platform v130-muse"><header><div><span class="eyebrow">MUSE · ALBUM / LIBRARY</span><h2>Build records people keep.</h2><p>MUSE is about projects, library behavior and long-tail listening. Deep cuts and strong albums can matter here without winning the viral race.</p></div><div class="v130-hero-number"><small>LIBRARY ADDS</small><strong>${compact(svc.libraryAdds)}</strong><span>${svc.editorialAdds} editorial placements earned</span></div></header><div class="v130-metrics"><div><span>Monthly listeners</span><strong>${compact(svc.monthlyListeners)}</strong></div><div><span>Library adds</span><strong>${compact(svc.libraryAdds)}</strong></div><div><span>Editorial support</span><strong>${compact(svc.editorialAdds)}</strong></div><div><span>Followers</span><strong>${compact(svc.followers)}</strong></div></div><section class="v130-two"><div><span class="eyebrow">ALBUM SHELF</span><div class="v130-albums">${albums.length?albums.map(a=>`<button onclick="releaseDetails('albums',${a.id})"><span>ALBUM</span><strong>${esc(a.title)}</strong><small>${compact(albumStreams(a,true))} lifetime track streams · Cohesion ${a.cohesion??'—'}/100</small></button>`).join(''):'<p class="fine">Release an album and MUSE becomes your project-focused dashboard.</p>'}</div><span class="eyebrow">RECORDS BEING KEPT</span><div class="v130-list">${V130_trackRows('muse')}</div></div>${V130_strategyCard('muse')}</section></section>`}
function V130_ampPanel(){const svc=V130_service('amp'),p=V114_state(),events=(p.events||[]).filter(x=>x.service==='amp').slice(0,8);return `<section class="v130-platform v130-amp"><header><div><span class="eyebrow">AMP · COMMUNITY / UNDERGROUND</span><h2>Earn the co-sign.</h2><p>AMP is the grassroots lane. Reposts, creator attention and early fan activity can let a smaller artist overperform before the mainstream catches up.</p></div><div class="v130-hero-number"><small>REPOSTS</small><strong>${compact(svc.reposts)}</strong><span>${compact(svc.followers)} community followers</span></div></header><div class="v130-metrics"><div><span>Community followers</span><strong>${compact(svc.followers)}</strong></div><div><span>Reposts</span><strong>${compact(svc.reposts)}</strong></div><div><span>This-week plays</span><strong>${compact(svc.currentWeekStreams)}</strong></div><div><span>Monthly listeners</span><strong>${compact(svc.monthlyListeners)}</strong></div></div><section class="v130-two"><div><span class="eyebrow">COMMUNITY FEED</span><div class="v130-feed">${events.length?events.map(e=>`<article><b>W${e.week}</b><span>${esc(e.text)}</span></article>`).join(''):'<article><b>NEW</b><span>No community moments yet. A repost network or community push will show up here.</span></article>'}</div><span class="eyebrow">UNDERGROUND HEAT</span><div class="v130-list">${V130_trackRows('amp')}</div></div>${V130_strategyCard('amp')}</section></section>`}
function V130_worldRegions(svc){const g=String(s.genre||'').toLowerCase(),rep=clamp(V114_num(s.reputation),0,100)/100;let w=[.30,.13,.22,.13,.18,.04];if(g.includes('latin'))w=[.20,.31,.17,.10,.18,.04];if(g.includes('afro'))w=[.18,.10,.18,.31,.19,.04];if(g.includes('k-pop'))w=[.18,.08,.17,.08,.45,.04];if(g.includes('country'))w=[.48,.08,.17,.07,.16,.04];w=w.map((x,i)=>x*(i===2||i===4?1+rep*.12:1));const sum=w.reduce((a,b)=>a+b,0);return ['North America','Latin America','Europe','Africa','Asia-Pacific','Oceania'].map((name,i)=>({name,share:w[i]/sum,listeners:Math.round(V114_num(svc.monthlyListeners)*w[i]/sum)}))}
function V130_worldMap(regions){const pts=[[105,75],[125,145],[245,72],[265,130],[385,100],[430,175]];return `<svg class="v130-world-map" viewBox="0 0 520 230" role="img" aria-label="WORLDWAVE regional audience map"><path d="M35 46l89-25 55 31-29 45-51 15-24 51-34-24 18-45zM197 48l73-24 57 31-16 43-37 15-21 74-37-24 11-48-29-27zM333 51l100-13 53 39-31 45-45-5-24 31-58-20-18-40zM432 156l48 9-5 33-39 12-26-19z" fill="currentColor" opacity=".12" stroke="currentColor" stroke-width="2"/>${regions.map((r,i)=>`<g transform="translate(${pts[i][0]} ${pts[i][1]})"><circle r="${10+Math.round(r.share*34)}" opacity=".18"></circle><circle r="6"></circle><text y="${i%2?28:-18}" text-anchor="middle">${esc(r.name)}</text><text y="${i%2?42:-4}" text-anchor="middle" class="pct">${Math.round(r.share*100)}%</text></g>`).join('')}</svg>`}
function V130_worldwavePanel(){const svc=V130_service('worldwave'),regions=V130_worldRegions(svc);return `<section class="v130-platform v130-worldwave"><header><div><span class="eyebrow">WORLDWAVE · GLOBAL / RADIO</span><h2>See where the world wants you.</h2><p>WORLDWAVE turns global crossover into something actionable: regional audience share, radio traction and touring-market potential.</p></div><div class="v130-hero-number"><small>RADIO SPINS</small><strong>${compact(svc.radioSpins)}</strong><span>${compact(svc.monthlyListeners)} global monthly listeners</span></div></header><div class="v130-metrics"><div><span>Global listeners</span><strong>${compact(svc.monthlyListeners)}</strong></div><div><span>Radio spins</span><strong>${compact(svc.radioSpins)}</strong></div><div><span>Followers</span><strong>${compact(svc.followers)}</strong></div><div><span>This-week streams</span><strong>${compact(svc.currentWeekStreams)}</strong></div></div><section class="v130-two"><div><span class="eyebrow">GLOBAL AUDIENCE MAP</span>${V130_worldMap(regions)}<div class="v130-regions">${regions.map(r=>`<div><span>${esc(r.name)}</span><strong>${compact(r.listeners)}</strong><small>${Math.round(r.share*100)}%</small></div>`).join('')}</div><span class="eyebrow">GLOBAL ROTATION</span><div class="v130-list">${V130_trackRows('worldwave')}</div></div>${V130_strategyCard('worldwave')}</section></section>`}
function V130_platformPanel(id){if(id==='vybe')return V130_vybePanel();if(id==='muse')return V130_musePanel();if(id==='amp')return V130_ampPanel();if(id==='worldwave')return V130_worldwavePanel();return ''}
V114_platformPanel=V130_platformPanel;

/* Certification plaques: the certification math stays authoritative; only the award presentation changes. */
function V130_plaquePalette(tier){return tier==='diamond'?{metal:'#d9fbff',edge:'#7ddbe8',disc:'#eaffff',ink:'#10232b',accent:'#9cf5ff'}:tier==='multi'?{metal:'#e5e7eb',edge:'#9ca3af',disc:'#f7f7f8',ink:'#171717',accent:'#c9ced6'}:tier==='platinum'?{metal:'#cbd5e1',edge:'#7c899b',disc:'#eef3f8',ink:'#14202c',accent:'#dce6ef'}:tier==='gold'?{metal:'#d6aa42',edge:'#8e6419',disc:'#f2cf67',ink:'#2c210c',accent:'#ffe497'}:{metal:'#30343b',edge:'#555c67',disc:'#1d2127',ink:'#f4f4f5',accent:'#777f8c'}}
function V130_plaqueArt(item,kind,small=false){const units=certificationUnits(item,kind),c=certificationInfo(units),p=V130_plaquePalette(c.tier),id=`plaque-${kind}-${item.id}-${c.tier}`.replace(/[^a-zA-Z0-9-]/g,''),cert=c.tier!=='none',multi=Math.max(1,Math.floor(units/1e6));return `<div class="v130-plaque v130-plaque-${c.tier} ${small?'small':''}" role="img" aria-label="${esc(c.label)} plaque for ${esc(item.title)}"><svg viewBox="0 0 420 270" aria-hidden="true"><defs><linearGradient id="${id}-frame" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${p.edge}"/><stop offset=".24" stop-color="${p.metal}"/><stop offset=".55" stop-color="${p.edge}"/><stop offset=".78" stop-color="${p.metal}"/><stop offset="1" stop-color="${p.edge}"/></linearGradient><radialGradient id="${id}-disc"><stop offset="0" stop-color="#111"/><stop offset=".12" stop-color="${p.disc}"/><stop offset=".48" stop-color="${p.edge}"/><stop offset=".8" stop-color="${p.disc}"/><stop offset="1" stop-color="${p.edge}"/></radialGradient></defs><rect x="8" y="8" width="404" height="254" rx="10" fill="#080b10" stroke="url(#${id}-frame)" stroke-width="12"/><rect x="26" y="26" width="368" height="218" rx="5" fill="#11161d" stroke="${p.edge}" stroke-opacity=".45"/><circle cx="130" cy="128" r="76" fill="url(#${id}-disc)" stroke="${p.metal}" stroke-width="3"/><circle cx="130" cy="128" r="22" fill="#11161d" stroke="${p.accent}" stroke-width="3"/><circle cx="130" cy="128" r="4" fill="${p.accent}"/>${c.tier==='diamond'?`<g transform="translate(292 85)"><polygon points="0,40 35,0 70,40 35,92" fill="${p.accent}" opacity=".95"/><path d="M0 40h70M35 0 20 40l15 52 15-52zM0 40l35 52 35-52" fill="none" stroke="#fff" stroke-opacity=".85" stroke-width="2"/></g>`:c.tier==='multi'?`<g opacity=".7">${Array.from({length:Math.min(4,multi-1)},(_,i)=>`<circle cx="${292+i*12}" cy="78" r="30" fill="none" stroke="${p.metal}" stroke-width="6"/>`).join('')}</g>`:''}<text x="230" y="154" fill="${p.metal}" font-size="24" font-weight="800">${cert?esc(c.label.toUpperCase()):'CERTIFICATION'}</text><text x="230" y="181" fill="#fff" font-size="17" font-weight="700">${esc(String(item.title).slice(0,24))}</text><text x="230" y="205" fill="#9aa5b1" font-size="12">${kind==='songs'?'SINGLE':'ALBUM'} · ${fmt(units)} UNITS</text>${cert?`<text x="230" y="225" fill="${p.accent}" font-size="11">ENCORE CAREER AWARD</text>`:`<text x="230" y="225" fill="#71717a" font-size="11">BUILDING TOWARD GOLD</text>`}</svg></div>`}
certificationCard=function(item,kind){const units=certificationUnits(item,kind),c=certificationInfo(units),remaining=Math.max(0,c.next-units);return `<section class="card certification-card v130-cert-card"><div class="sectionhead"><span class="eyebrow">${kind==='songs'?'Song':'Album'} plaque</span>${certBadge(item,kind)}</div>${V130_plaqueArt(item,kind)}<button class="release-link" onclick="releaseDetails('${kind}',${item.id})">${esc(item.title)}</button><p><strong>${fmt(units)}</strong> equivalent units · ${compact(kind==='albums'?albumStreams(item,true):item.total)} streams</p><div class="v130-cert-next"><span>${c.tier==='none'?'First target':'Next award'}</span><strong>${remaining?fmt(remaining)+' units away':'Milestone reached'}</strong><small>${esc(certificationInfo(c.next).label)}</small></div>${item.certification?`<p class="fine">${item.certification.recovered?'Current award recovered from saved totals':'Current award earned Week '+item.certification.week}</p>`:''}</section>`}
function V130_plaqueWall(){const rows=[...(s.songs||[]).filter(x=>x.released).map(item=>({kind:'songs',item,units:certificationUnits(item,'songs')})),...(s.albums||[]).map(item=>({kind:'albums',item,units:certificationUnits(item,'albums')}))].filter(x=>x.units>=500000).sort((a,b)=>b.units-a.units).slice(0,4);return `<section class="af-section-v095 v130-plaque-wall"><div class="af-section-title-v095"><span>05</span><div><small>THE PLAQUE WALL</small><h2>Your career hardware should look like hardware.</h2></div></div>${rows.length?`<div class="v130-plaque-grid">${rows.map(x=>`<button onclick="careerTab='Certifications';go('Career')">${V130_plaqueArt(x.item,x.kind,true)}<strong>${esc(x.item.title)}</strong><small>${esc(certificationInfo(x.units).label)}</small></button>`).join('')}</div>`:'<div class="af-empty-v095">Your first Gold, Platinum or Diamond plaque will be displayed here.</div>'}<div class="af-inline-actions-v095"><button class="secondary" onclick="careerTab='Certifications';go('Career')">Open full plaque gallery</button></div></section>`}
const V130_artistFileBase=artistFilePage;
artistFilePage=function(){const html=V130_artistFileBase();return html.replace('<footer class="af-footer-v095">',V130_plaqueWall()+'<footer class="af-footer-v095">')};

/* Studio: keep the simulation depth, remove the front-door questionnaire. */
function V130_featureCandidates(){return (s.world||[]).filter(a=>a&&a.relation>-40&&typeof accessible==='function'&&accessible(a)&&typeof quote==='function'&&s.cash>=quote(a)).sort((a,b)=>(b.relation-a.relation)||(b.fans-a.fans)).slice(0,16)}
V092_unifiedSongForm=function(){const idea=ensureStudioIdeaSchema(),features=V130_featureCandidates();return `<section class="card studio-active studio-v130-simple"><div class="studio-tape-label"><span>SESSION 01</span><small>WRITE THE RECORD</small></div><h2>Start your next record</h2><p class="v130-simple-note">Three decisions. The deeper production and career systems still work underneath.</p><form class="form studio-v130-form" onsubmit="newSong(event)"><label><span>Song</span>${nameInput('songtitle','song',idea.title||'','Name your next record')}</label><label><span>Features</span><select name="feature"><option value="">Solo — no feature</option>${features.map(a=>`<option value="${a.id}">${esc(a.name)} · ${quote(a)?money(quote(a)):'Free'} · ${relationship(a)}</option>`).join('')}</select><small>${features.length?'Choose one now. You can still add more collaborators later from the artist directory.':'No bookable feature fits your current relationships/budget. Start solo and add one later.'}</small></label><label><span>Mood</span><select name="mood">${directions.map(x=>`<option value="${esc(x.id)}" ${x.id===(idea.mood||directions[0].id)?'selected':''}>${esc(x.name||x.id)}</option>`).join('')}</select></label><input type="hidden" name="package" value="0"><input type="hidden" name="brief" value="story"><button class="primary">Start writing · 10 energy</button></form></section>`}
