function V134_num(v){const n=Number(v);return Number.isFinite(n)?n:0}
function V134_pct(v,d=0){return `${(V134_num(v)*100).toFixed(d)}%`}
function V134_replaceWeek(list,entry,limit=52){list=Array.isArray(list)?list:[];const i=list.findIndex(x=>Number(x.week)===Number(entry.week));if(i>=0)list[i]=entry;else list.push(entry);list.sort((a,b)=>a.week-b.week);return list.slice(-limit)}
function V134_service(id){const svc=typeof V130_service==='function'?V130_service(id):V114_state().services[id];svc.v2=svc.v2&&typeof svc.v2==='object'?svc.v2:{history:[],current:{},regions:{},countries:[],undergroundChart:[],projects:[]};svc.v2.history=Array.isArray(svc.v2.history)?svc.v2.history:[];return svc}
function V134_trackState(track,id){const ts=V114_trackRow(s,track).services[id];ts.v2=ts.v2&&typeof ts.v2==='object'?ts.v2:{history:[],current:{}};ts.v2.history=Array.isArray(ts.v2.history)?ts.v2.history:[];return ts}
function V134_albumTracks(album){const raw=Array.isArray(album?.tracks)?album.tracks:Array.isArray(album?.songs)?album.songs:Array.isArray(album?.songIds)?album.songIds:[];return raw.map(x=>typeof x==='object'?x.id:x).map(id=>(s.songs||[]).find(t=>Number(t.id)===Number(id))).filter(Boolean)}
function V134_weighted(rows,key,weight='streams'){const total=rows.reduce((n,x)=>n+Math.max(0,V134_num(x[weight])),0);return total?rows.reduce((n,x)=>n+V134_num(x[key])*Math.max(0,V134_num(x[weight])),0)/total:rows.length?rows.reduce((n,x)=>n+V134_num(x[key]),0)/rows.length:0}
