  if(id==='vybe'){current={...current,saveRate:V134_weighted(rows.map(x=>({...x.sig,streams:V134_num(x.stats.thisWeek)})),'saveRate'),skipRate:V134_weighted(rows.map(x=>({...x.sig,streams:V134_num(x.stats.thisWeek)})),'skipRate'),repeatRate:V134_weighted(rows.map(x=>({...x.sig,streams:V134_num(x.stats.thisWeek)})),'repeatRate'),algorithmShare:V134_weighted(rows.map(x=>({...x.sig,streams:V134_num(x.stats.thisWeek)})),'algorithmShare')};}
