function V134_settleFrame(state=s){const v=V114_state(state).video;v.v2=v.v2&&typeof v.v2==='object'?v.v2:{history:[],current:{},awards:[]};v.v2.history=Array.isArray(v.v2.history)?v.v2.history:[];v.v2.awards=Array.isArray(v.v2.awards)?v.v2.awards:[];const active=[];for(const video of v.videos){video.v2=video.v2&&typeof video.v2==='object'?video.v2:{history:[]};video.v2.history=Array.isArray(video.v2.history)?video.v2.history:[];const views=Math.max(0,V134_num(video.thisWeekViews)),concept=V134_VIDEO_CONCEPTS[video.concept]||V134_VIDEO_CONCEPTS.performance,director=V134_VIDEO_DIRECTORS[video.director]||V134_VIDEO_DIRECTORS.self,track=(state.songs||[]).find(x=>Number(x.id)===Number(video.songId)),q=clamp(V134_num(track?.quality||55),0,100),likeRate=clamp(.035+q*.00032+director.quality*.10,.025,.11),commentRate=clamp(.003+q*.00005+director.quality*.012,.002,.018),completionRate=clamp(.42+q*.0031+(concept.retention-1)*.55+director.quality*.30,.35,.92),likes=Math.round(views*likeRate),comments=Math.round(views*commentRate),trendScore=clamp(Math.log10(1+views)*10+completionRate*34+likeRate*120+(video.week===state.week?8:0),0,100),entry={week:state.week,views,likes,comments,completionRate,trendScore};video.v2.current=entry;video.v2.history=V134_replaceWeek(video.v2.history,entry,26);active.push({video,entry});const award=V134_frameAward(video);if(award&&!v.v2.awards.some(x=>x.videoId===video.id&&x.id===award.id)){v.v2.awards.push({...award,videoId:video.id,songId:video.songId,week:state.week});V114_addEvent(V114_state(state),{type:'video-award',songId:video.songId,text:`${video.title||track?.title||'A FRAME visual'} earned ${award.name}.`})}}
 active.sort((a,b)=>b.entry.trendScore-a.entry.trendScore);active.forEach((x,i)=>x.video.v2.trendingRank=x.entry.views>0?i+1:null);const totalViews=active.reduce((n,x)=>n+x.entry.views,0),current={week:state.week,views:totalViews,likes:active.reduce((n,x)=>n+x.entry.likes,0),comments:active.reduce((n,x)=>n+x.entry.comments,0),completionRate:V134_weighted(active.map(x=>({...x.entry,streams:x.entry.views})),'completionRate'),topTrend:active[0]?.video?.id||null};v.v2.current=current;v.v2.history=V134_replaceWeek(v.v2.history,current,52);v.v2.awards=v.v2.awards.slice(-60);return current}
