function V134_runPlatformMove(id,moveId,songId){const move=V134_PLATFORM_MOVES[id]?.find(x=>x.id===moveId),svc=V134_service(id),track=(s.songs||[]).find(x=>Number(x.id)===Number(songId)&&x.released);if(!move||!track)return false;if(svc.strategy?.lastActionWeek===s.week){toast?.(`${V114_AUDIO_PLATFORMS[id].name} already has a strategy move this week.`);return false}if(!spend(move.energy,move.cost))return false;V114_place(V114_state(),id,track,move.placement,move.lift,move.weeks);track.platformLiftNext=clamp(V134_num(track.platformLiftNext)+move.lift,0,.25);svc.strategy=svc.strategy||{history:[]};svc.strategy.history=Array.isArray(svc.strategy.history)?svc.strategy.history:[];svc.strategy.lastActionWeek=s.week;svc.strategy.focusSongId=track.id;svc.strategy.history.unshift({week:s.week,songId:track.id,title:track.title,action:move.name,move:move.id,lift:move.lift,cost:move.cost});svc.strategy.history=svc.strategy.history.slice(0,32);if(id==='vybe'&&move.id==='save')svc.saves=Math.round(V134_num(svc.saves)+Math.max(1,V134_num(svc.currentWeekStreams)*.012));if(id==='muse'&&move.id==='editorial')svc.editorialAdds=V134_num(svc.editorialAdds)+1;if(id==='amp')svc.reposts=V134_num(svc.reposts)+Math.max(1,Math.round(Math.sqrt(Math.max(1,V134_num(svc.currentWeekStreams)))/5));if(id==='worldwave')svc.radioSpins=V134_num(svc.radioSpins)+Math.max(1,Math.round(Math.sqrt(Math.max(1,V134_num(svc.currentWeekStreams)))/3));V114_addEvent(V114_state(),{type:'strategy',service:id,songId:track.id,text:`${move.name}: ${track.title} on ${V114_AUDIO_PLATFORMS[id].name}.`});queueSave?.();render();toast?.(`${move.name} launched for ${track.title}.`);return true}
function V134_strategyBoard(id){const svc=V134_service(id),used=svc.strategy?.lastActionWeek===s.week,tracks=(s.songs||[]).filter(x=>x.released);return `<aside class="v134-strategy"><span class="eyebrow">THIS WEEK’S PLATFORM MOVE</span><h3>${esc(V114_AUDIO_PLATFORMS[id].name)} strategy desk</h3><p>Choose one move per service each week. Moves influence future discovery and behavior; they never add fake current-week streams.</p>${tracks.length?`<label>Focus record<select id="v134-focus-${id}">${V130_trackOptions(id)}</select></label><div class="v134-moves">${V134_PLATFORM_MOVES[id].map(m=>`<button ${used?'disabled':''} onclick="V134_runPlatformMove('${id}','${m.id}',Number(document.getElementById('v134-focus-${id}').value))"><strong>${esc(m.name)}</strong><small>⚡ ${m.energy}${m.cost?' · '+money(m.cost):' · Free'}</small><span>${esc(m.detail)}</span></button>`).join('')}</div>`:'<p class="fine">Release a song before using platform strategy.</p>'}${svc.strategy?.history?.[0]?`<small>Last move: Week ${svc.strategy.history[0].week} · ${esc(svc.strategy.history[0].action)} · ${esc(svc.strategy.history[0].title)}</small>`:''}</aside>`}
function V134_metric(label,value,note=''){return `<div><span>${esc(label)}</span><strong>${esc(String(value))}</strong>${note?`<small>${esc(note)}</small>`:''}</div>`}
function V134_trackRows(id,metricFn,limit=7){const rows=V114_topTracks(id,limit);return rows.length?rows.map((x,i)=>{const sig=x.stats.v2?.current||{};return `<button class="v134-track-row" onclick="releaseDetails('songs',${x.row.songId})"><b>${String(i+1).padStart(2,'0')}</b><span><strong>${esc(x.row.title)}</strong><small>${compact(x.stats.thisWeek)} this week · ${esc(metricFn(sig,x))}</small></span><em>${Math.round(V134_num(sig.score))}</em></button>`}).join(''):'<p class="fine">No platform activity yet.</p>'}
function V134_vybePanel(){const svc=V134_service('vybe'),c=svc.v2.current||{};return `<section class="v134-platform v134-vybe"><header><div><span class="eyebrow">VYBE · ALGORITHM / MOMENTUM</span><h2>Attention is easy. Retention is the game.</h2><p>VYBE now separates saves, skips, repeat listening and algorithmic discovery. Big streams with weak engagement can cool off fast.</p></div><div class="v134-score"><small>ALGORITHM HEALTH</small><strong>${Math.round(V134_num(c.score))}</strong><span>/100</span></div></header><div class="v134-metrics">${V134_metric('Weekly streams',compact(svc.currentWeekStreams))}${V134_metric('Save rate',V134_pct(c.saveRate,1))}${V134_metric('Skip rate',V134_pct(c.skipRate,1))}${V134_metric('Repeat rate',V134_pct(c.repeatRate,1))}${V134_metric('Algorithmic share',V134_pct(c.algorithmShare,1))}${V134_metric('Monthly listeners',compact(svc.monthlyListeners))}</div><div class="v134-grid"><section><span class="eyebrow">ALGORITHM BOARD</span><div class="v134-track-list">${V134_trackRows('vybe',sig=>`Save ${V134_pct(sig.saveRate,1)} · Skip ${V134_pct(sig.skipRate,1)} · Repeat ${V134_pct(sig.repeatRate,1)}`)}</div></section>${V134_strategyBoard('vybe')}</div></section>`}
function V134_musePanel(){const svc=V134_service('muse'),c=svc.v2.current||{},projects=svc.v2.projects||[];return `<section class="v134-platform v134-muse"><header><div><span class="eyebrow">MUSE · ALBUM / LIBRARY</span><h2>Make a project people finish.</h2><p>MUSE now values album completion, library retention, repeat listening and deep-cut consumption—not just the biggest single.</p></div><div class="v134-score"><small>PROJECT HEALTH</small><strong>${Math.round(V134_num(c.score))}</strong><span>/100</span></div></header><div class="v134-metrics">${V134_metric('Completion',V134_pct(c.completionRate,1))}${V134_metric('Library rate',V134_pct(c.libraryRate,1))}${V134_metric('Repeat rate',V134_pct(c.repeatRate,1))}${V134_metric('Deep-cut share',V134_pct(c.deepCutShare,1))}${V134_metric('Library adds',compact(svc.libraryAdds))}${V134_metric('Editorial support',compact(svc.editorialAdds))}</div><div class="v134-grid"><section><span class="eyebrow">ALBUM SHELF · LISTENING QUALITY</span><div class="v134-projects">${projects.length?projects.slice(0,6).map(x=>`<button onclick="releaseDetails('albums',${x.id})"><div><strong>${esc(x.title)}</strong><small>${compact(x.streams)} MUSE streams this week</small></div><b>${Math.round(x.score)}</b><span>Completion ${V134_pct(x.completion,0)} · Deep cuts ${V134_pct(x.deepCutShare,0)}</span></button>`).join(''):'<p class="fine">Release an album to unlock project-level listening analytics.</p>'}</div></section>${V134_strategyBoard('muse')}</div></section>`}
function V134_ampPanel(){const svc=V134_service('amp'),c=svc.v2.current||{},chart=svc.v2.undergroundChart||[],events=(V114_state().events||[]).filter(x=>x.service==='amp'||x.type==='video-award').slice(0,7);return `<section class="v134-platform v134-amp"><header><div><span class="eyebrow">AMP · COMMUNITY / UNDERGROUND</span><h2>Culture can move before the mainstream does.</h2><p>AMP tracks repost behavior, comments, creator co-signs and community heat. Strong underground response can spill into future discovery elsewhere.</p></div><div class="v134-score"><small>COMMUNITY HEAT</small><strong>${Math.round(V134_num(c.communityHeat))}</strong><span>/100</span></div></header><div class="v134-metrics">${V134_metric('Weekly plays',compact(svc.currentWeekStreams))}${V134_metric('Weekly reposts',compact(c.reposts))}${V134_metric('Weekly comments',compact(c.comments))}${V134_metric('Creator co-signs',compact(c.cosigns))}${V134_metric('Career co-signs',compact(svc.v2.creatorCosigns))}${V134_metric('Community followers',compact(svc.followers))}</div><div class="v134-grid"><section><span class="eyebrow">UNDERGROUND 20</span><div class="v134-underground">${chart.length?chart.slice(0,10).map((x,i)=>`<button onclick="releaseDetails('songs',${x.songId})"><b>#${i+1}</b><span><strong>${esc(x.title)}</strong><small>${compact(x.streams)} plays · Heat ${Math.round(x.heat)}</small></span></button>`).join(''):'<p class="fine">The underground chart forms from your AMP activity.</p>'}</div>${events.length?`<span class="eyebrow">COMMUNITY FEED</span><div class="v134-feed">${events.map(x=>`<p><b>W${x.week}</b> ${esc(x.text)}</p>`).join('')}</div>`:''}</section>${V134_strategyBoard('amp')}</div></section>`}
function V134_regionMap(regions){return V130_worldMap(regions.map(x=>({name:x.name,share:x.share,listeners:x.listeners})))}
function V134_worldwavePanel(){const svc=V134_service('worldwave'),c=svc.v2.current||{},regions=Object.values(svc.v2.regions||{}).sort((a,b)=>b.listeners-a.listeners),countries=(svc.v2.countries||[]).slice(0,10);return `<section class="v134-platform v134-worldwave"><header><div><span class="eyebrow">WORLDWAVE · GLOBAL / RADIO</span><h2>Turn international listening into market decisions.</h2><p>WORLDWAVE now attributes its existing listener total across regions and countries, tracks regional momentum, and feeds touring demand without creating a second audience.</p></div><div class="v134-score"><small>CROSSOVER HEALTH</small><strong>${Math.round(V134_num(c.score))}</strong><span>/100</span></div></header><div class="v134-metrics">${V134_metric('Global listeners',compact(svc.monthlyListeners))}${V134_metric('Radio spins',compact(svc.radioSpins))}${V134_metric('Crossover',V134_pct(c.crossover,0))}${V134_metric('Radio fit',V134_pct(c.radioFit,0))}${V134_metric('Top region',regions[0]?.name||'—')}${V134_metric('Followers',compact(svc.followers))}</div><div class="v134-grid"><section><span class="eyebrow">GLOBAL AUDIENCE MAP</span>${regions.length?V134_regionMap(regions):V130_worldMap(V130_worldRegions(svc))}<div class="v134-regions">${regions.map(r=>`<div><span>${esc(r.name)}</span><strong>${compact(r.listeners)}</strong><small>${Math.round(r.share*100)}% · ${r.growth>=0?'+':''}${r.growth.toFixed(1)}%</small></div>`).join('')}</div><span class="eyebrow">TOP COUNTRIES · LISTENER ATTRIBUTION</span><div class="v134-countries">${countries.map((x,i)=>`<div><b>${i+1}</b><span>${esc(x.name)}</span><strong>${compact(x.listeners)}</strong><small>${V134_pct(x.share,1)}</small></div>`).join('')}</div></section>${V134_strategyBoard('worldwave')}</div></section>`}
function V134_platformPanel(id){if(id==='vybe')return V134_vybePanel();if(id==='muse')return V134_musePanel();if(id==='amp')return V134_ampPanel();if(id==='worldwave')return V134_worldwavePanel();return ''}
V114_platformPanel=V134_platformPanel;

function V134_framePage(){const p=V114_state(),v=p.video,v2=v.v2||{},c=v2.current||{},videos=[...(v.videos||[])].sort((a,b)=>V134_num(b.v2?.current?.trendScore)-V134_num(a.v2?.current?.trendScore)||b.week-a.week);return `<section class="v134-platform v134-frame"><header><div><span class="eyebrow">FRAME · VIDEO / VISUAL CULTURE</span><h2>A visual can become its own career moment.</h2><p>FRAME now tracks completion, likes, comments, trending rank, directors, concepts and visual milestones while keeping video revenue separate from audio streams.</p></div><div class="v134-score"><small>THIS WEEK’S VIEWS</small><strong>${compact(v.currentWeekViews||0)}</strong><span>views</span></div></header><div class="v134-metrics">${V134_metric('Subscribers',compact(v.subscribers))}${V134_metric('Completion',V134_pct(c.completionRate,1))}${V134_metric('Likes',compact(c.likes))}${V134_metric('Comments',compact(c.comments))}${V134_metric('Creator revenue',money(v.lifetimeRevenue))}${V134_metric('Visual awards',String((v2.awards||[]).length))}</div><div class="v134-frame-actions"><button class="primary" ${(s.songs||[]).some(x=>x.released)?'':'disabled'} onclick="V114_openVideoStudio()">Plan a video</button><span>Concept + director + format + budget shape the visual. Nothing guarantees virality.</span></div><div class="v134-video-list">${videos.length?videos.map(x=>{const song=(s.songs||[]).find(y=>Number(y.id)===Number(x.songId)),sig=x.v2?.current||{},concept=V134_VIDEO_CONCEPTS[x.concept]||V134_VIDEO_CONCEPTS.performance,director=V134_VIDEO_DIRECTORS[x.director]||V134_VIDEO_DIRECTORS.self;return `<article><div class="v134-video-rank"><b>${x.v2?.trendingRank?'#'+x.v2.trendingRank:'—'}</b><small>TRENDING</small></div><div><span>${esc(V114_VIDEO_FORMATS[x.format]?.name||'Video')} · ${esc(concept.name)}</span><strong>${esc(song?.title||x.title||'Catalog video')}</strong><small>${esc(director.name)} · Released Week ${x.week} · ${money(x.totalCost||x.budget)}</small></div><div><b>${compact(x.thisWeekViews||0)}</b><small>views</small><b>${V134_pct(sig.completionRate,0)}</b><small>completion</small><b>${compact(sig.likes||0)}</b><small>likes</small></div></article>`}).join(''):'<p class="fine">No videos yet. Build the first visual era here.</p>'}</div>${(v2.awards||[]).length?`<section class="v134-frame-awards"><span class="eyebrow">FRAME AWARDS</span>${v2.awards.slice(-8).reverse().map(a=>`<div><strong>${esc(a.name)}</strong><span>Week ${a.week} · ${compact(a.views)} lifetime views</span></div>`).join('')}</section>`:''}</section>`}
V114_videoPage=V134_framePage;

V114_openVideoStudio=function(){const released=(s.songs||[]).filter(x=>x.released);if(!released.length){toast?.('Release a song before planning a video.');return}modal(`<span class="eyebrow">FRAME · VIDEO STUDIO 2.0</span><h2>Build the visual campaign.</h2><form class="form" onsubmit="V114_reviewVideo(event)"><label>Song<select name="song">${released.slice().sort((a,b)=>(b.streams||0)-(a.streams||0)).map(x=>`<option value="${x.id}">${esc(x.title)} · ${compact(x.streams||0)} current streams</option>`).join('')}</select></label><label>Format<select name="format">${Object.values(V114_VIDEO_FORMATS).map(x=>`<option value="${x.id}">${esc(x.name)} · minimum ${money(x.minimum)} · ${x.energy} energy</option>`).join('')}</select></label><label>Concept<select name="concept">${Object.entries(V134_VIDEO_CONCEPTS).map(([id,x])=>`<option value="${id}">${esc(x.name)}</option>`).join('')}</select></label><label>Director<select name="director">${Object.entries(V134_VIDEO_DIRECTORS).map(([id,x])=>`<option value="${id}">${esc(x.name)} · ${x.fee?money(x.fee):'No fee'}</option>`).join('')}</select></label><label>Production budget<input name="budget" type="number" min="1500" max="50000000" step="500" value="60000" required></label><p class="fine">Director fee is added to production budget. Completion and trend potential come from the song, concept, director and spend—not cash alone.</p><button class="primary">Review production</button></form>`)};
V114_reviewVideo=function(event){event.preventDefault();const f=new FormData(event.target),track=(s.songs||[]).find(x=>Number(x.id)===Number(f.get('song'))&&x.released),format=V114_VIDEO_FORMATS[String(f.get('format'))],conceptId=String(f.get('concept')||'performance'),directorId=String(f.get('director')||'self'),concept=V134_VIDEO_CONCEPTS[conceptId],director=V134_VIDEO_DIRECTORS[directorId],budget=Math.max(0,Math.round(Number(f.get('budget'))||0));if(!track||!format||!concept||!director)return;if(budget<format.minimum){toast?.(format.name+' needs at least '+money(format.minimum)+'.');return}const factor=V114_videoBudgetFactor({format:format.id,budget}),base=Math.max(120,Math.max(V134_num(track.streams)*.36,V134_num(s.fans)*.055)),projected=Math.round(base*format.reach*factor*concept.reach*(1+director.reach)),low=Math.round(projected*.65),high=Math.round(projected*1.35),totalCost=cents(budget+director.fee),quality=clamp(.84+V134_num(track.quality||50)/420+concept.quality+director.quality,.82,1.35);V114_pendingVideo={songId:track.id,title:track.title,format:format.id,budget,productionBudget:budget,totalCost,energy:format.energy,quality,concept:conceptId,director:directorId};modal(`<span class="eyebrow">FRAME · PRODUCTION REVIEW</span><h2>${esc(format.name)} · ${esc(track.title)}</h2>${profileRows([['Concept',concept.name],['Director',director.name],['Production budget',money(budget)],['Director fee',money(director.fee)],['Total cost',money(totalCost)],['Energy',format.energy],['Projected first-week views',compact(low)+' – '+compact(high)],['Completion profile',concept.retention>1.08?'High':concept.retention>1?'Strong':'Standard']])}<p>${esc(concept.detail)} ${esc(director.detail)}</p><div class="controls"><button class="primary" onclick="V114_publishVideo()">Fund & publish</button><button class="secondary" onclick="V114_openVideoStudio()">Change plan</button></div>`)};
V114_publishVideo=function(){const plan=V114_pendingVideo;if(!plan)return false;const cost=V134_num(plan.totalCost||plan.budget);if(s.cash<cost){toast?.('You need '+money(cost)+' in spendable cash.');return false}if(!spend(plan.energy))return false;migrateFinance?.();if(!s.finance.week||typeof s.finance.week!=='object')s.finance.week={wages:0,live:0,expenses:0};changeCash(-cost);s.finance.week.expenses=cents(V134_num(s.finance.week.expenses)+cost);moneyEvent?.('FRAME video production · '+plan.title,-cost);const v=V114_state().video;v.videos.push({id:v.nextId++,songId:plan.songId,title:plan.title,format:plan.format,budget:plan.productionBudget||plan.budget,totalCost:cost,quality:plan.quality,concept:plan.concept||'performance',director:plan.director||'self',week:s.week,thisWeekViews:0,lifetimeViews:0,lifetimeRevenue:0});v.videos=v.videos.slice(-60);V114_addEvent(V114_state(),{type:'video',songId:plan.songId,text:`${V114_VIDEO_FORMATS[plan.format].name} for ${plan.title} premiered on FRAME.`});V114_pendingVideo=null;$('modal')?.close?.();queueSave?.();render();toast?.('Video published. Performance resolves at week close.');return true};

function V134_overview(){const p=V114_state(),vy=V134_service('vybe').v2.current||{},mu=V134_service('muse').v2.current||{},am=V134_service('amp').v2.current||{},ww=V134_service('worldwave').v2.current||{},fr=p.video.v2?.current||{};return `<section class="v134-overview"><header><div><span class="eyebrow">MUSIC PLATFORM ECOSYSTEM 1.0 → PLATFORMS 2.0</span><h2>Five services. Five different careers inside one career.</h2><p>Every service reads the same authoritative music differently. Streams are allocated once; saves, completion, reposts, radio and visual behavior decide what happens next.</p></div><div><small>COMBINED PLATFORM FOLLOWING</small><strong>${compact(V114_totalFollowers())}</strong><span>audio followers + FRAME subscribers</span></div></header><div class="v134-overview-grid"><button onclick="V114_setTab('vybe')"><span>VYBE</span><strong>${Math.round(V134_num(vy.score))}/100</strong><small>Algorithm health · Save ${V134_pct(vy.saveRate,0)}</small></button><button onclick="V114_setTab('muse')"><span>MUSE</span><strong>${Math.round(V134_num(mu.score))}/100</strong><small>Project health · Completion ${V134_pct(mu.completionRate,0)}</small></button><button onclick="V114_setTab('amp')"><span>AMP</span><strong>${Math.round(V134_num(am.communityHeat))}/100</strong><small>Community heat · ${compact(am.cosigns||0)} co-signs this week</small></button><button onclick="V114_setTab('worldwave')"><span>WORLDWAVE</span><strong>${Math.round(V134_num(ww.score))}/100</strong><small>Crossover health · ${compact(p.services.worldwave.radioSpins)} radio spins</small></button><button onclick="V114_setTab('frame')"><span>FRAME</span><strong>${compact(fr.views||0)}</strong><small>weekly views · ${V134_pct(fr.completionRate,0)} completion</small></button></div><section class="v134-loop"><span class="eyebrow">THE CROSS-PLATFORM LOOP</span><div><article><b>01</b><strong>Release demand creates streams.</strong><p>ENCORE still computes one authoritative stream total.</p></article><article><b>02</b><strong>Platforms explain the behavior.</strong><p>Listeners save, skip, finish albums, repost, tune in by region and watch visuals.</p></article><article><b>03</b><strong>Behavior shapes the next week.</strong><p>Strong signals create bounded discovery lift rather than duplicate plays.</p></article><article><b>04</b><strong>Charts and Touring read the signals.</strong><p>Platform heat now gives context to chart runs and WORLDWAVE informs live demand.</p></article></div></section></section>`}
V114_overview=V134_overview;

function V134_trackPlatformSummary(track){const parts=V114_PLATFORM_IDS.map(id=>{const sig=V134_trackState(track,id).v2.current||{};return {id,name:V114_AUDIO_PLATFORMS[id].name,score:V134_num(sig.score)}}).sort((a,b)=>b.score-a.score);return parts}
function V134_chartBadges(kind,item){if(kind==='albums'){const p=(V134_service('muse').v2.projects||[]).find(x=>Number(x.id)===Number(item.id));return p?`<span class="v134-chart-badges"><i>MUSE ${Math.round(p.score)}</i><i>${V134_pct(p.completion,0)} complete</i></span>`:''}const rows=V134_trackPlatformSummary(item).filter(x=>x.score>0).slice(0,2);const video=V114_state().video.videos.filter(v=>Number(v.songId)===Number(item.id)).sort((a,b)=>V134_num(b.v2?.current?.trendScore)-V134_num(a.v2?.current?.trendScore))[0];return rows.length||video?`<span class="v134-chart-badges">${rows.map(x=>`<i>${esc(x.name)} ${Math.round(x.score)}</i>`).join('')}${video?.v2?.trendingRank?`<i>FRAME #${video.v2.trendingRank}</i>`:''}</span>`:''}
if(typeof V133_chartRow==='function'){const V134_chartRowBase=V133_chartRow;V133_chartRow=function(kind,x,metric,ready){let html=V134_chartRowBase(kind,x,metric,ready);if(!x.you)return html;const item=chartOwner(kind,x.id),badges=item?V134_chartBadges(kind,item):'';return badges?html.replace('</em></span><span class="v133-path">',`</em>${badges}</span><span class="v133-path">`):html}}

function V134_cityWorldRegion(city){return 'North America'}
function V134_worldwaveTourSignal(city){const svc=V134_service('worldwave'),region=svc.v2.regions?.[V134_cityWorldRegion(city)];if(!region||!V134_num(svc.monthlyListeners))return {region:'North America',strength:50,multiplier:1,promoterBonus:0,listeners:0,growth:0};const radio=Math.min(18,Math.log10(1+V134_num(svc.radioSpins))*3.1),strength=clamp(region.share*100*.58+region.momentum*.34+radio,0,100),multiplier=clamp(.94+strength*.0021,.94,1.15),promoterBonus=Math.round(Math.max(0,strength-45)*.11);return {region:region.name,strength,multiplier,promoterBonus,listeners:region.listeners,growth:region.growth}}
if(typeof V100_promoterConfidence==='function'){const V134_promoterBase=V100_promoterConfidence;V100_promoterConfidence=function(r){const base=V134_promoterBase(r),signal=V134_worldwaveTourSignal(r.city);return Math.round(clamp(base+signal.promoterBonus,0,100))}}
if(typeof tourStopEstimate==='function'){const V134_tourEstimateBase=tourStopEstimate;tourStopEstimate=function(r,route=tourRoute()){const n=V134_tourEstimateBase(r,route),signal=V134_worldwaveTourSignal(r.city);if(signal.multiplier!==1&&n.tickets<n.capacity){const demand=Math.max(0,n.tickets*signal.multiplier),tiers=tourTicketInventory(r,demand),tickets=tiers.standard+tiers.premium,gross=cents(tiers.standard*tiers.standardPrice+tiers.premium*tiers.premiumPrice);n.tiers=tiers;n.tickets=tickets;n.gross=gross;n.averagePrice=tickets?gross/tickets:r.price;n.variable=cents(gross*.18);n.cost=cents(n.fixed+n.variable);n.net=cents(gross-n.cost)}n.worldwave=signal;return n}}
if(typeof V100_venueForecast==='function'){const V134_forecastBase=V100_venueForecast;V100_venueForecast=function(r,route=tourRoute()){const n=tourStopEstimate(r,route),html=V134_forecastBase(r,route),signal=n.worldwave||V134_worldwaveTourSignal(r.city);return html.replace('</section>',`<div class="v134-tour-signal"><span>WORLDWAVE ${esc(signal.region)}</span><strong>${Math.round(signal.strength)}/100</strong><small>${compact(signal.listeners)} listeners · ${signal.growth>=0?'+':''}${signal.growth.toFixed(1)}% regional growth · ${signal.multiplier>=1?'+':''}${Math.round((signal.multiplier-1)*100)}% live-demand effect</small></div></section>`)}}

const V134_CERT_MILESTONES=[{label:'Gold',units:500000,tier:'gold'},{label:'Platinum',units:1000000,tier:'platinum'},{label:'Diamond',units:10000000,tier:'diamond'},{label:'Onyx',units:100000000,tier:'onyx'},{label:'Obsidian',units:250000000,tier:'obsidian'},{label:'Eternal',units:500000000,tier:'eternal'}];
function V134_plaqueMark(c,p,multi){if(c.tier==='diamond')return `<g transform="translate(302 72)"><polygon points="0,34 28,0 56,34 28,76" fill="${p.accent}"/><path d="M0 34h56M28 0 16 34l12 42 12-42z" fill="none" stroke="#fff" stroke-opacity=".8" stroke-width="2"/></g>`;if(c.tier==='onyx')return `<g transform="translate(304 102)"><circle r="34" fill="#090b0e" stroke="${p.metal}" stroke-width="5"/><path d="M-20 0 0-24 22 0 0 26Z" fill="${p.accent}" opacity=".72"/></g>`;if(c.tier==='obsidian')return `<g transform="translate(304 102)"><path d="M0-42 30-8 18 38-18 38-31-9Z" fill="${p.disc}" stroke="${p.accent}" stroke-width="5"/><path d="M0-42 0 38M-31-9 30-8" stroke="${p.metal}" stroke-opacity=".75"/></g>`;if(c.tier==='eternal')return `<g transform="translate(304 102)">${Array.from({length:12},(_,i)=>`<path d="M0-48 5-30-5-30Z" fill="${p.accent}" transform="rotate(${i*30})"/>`).join('')}<circle r="28" fill="${p.disc}" stroke="${p.metal}" stroke-width="5"/><circle r="10" fill="${p.accent}"/></g>`;if(c.tier==='multi')return `<g opacity=".75">${Array.from({length:Math.min(4,Math.max(1,multi-1))},(_,i)=>`<circle cx="${278+i*16}" cy="80" r="26" fill="none" stroke="${p.metal}" stroke-width="5"/>`).join('')}</g>`;return ''}
function V134_plaqueArt(item,kind,small=false){const units=certificationUnits(item,kind),c=certificationInfo(units),p=V130_plaquePalette(c.tier),id=`v134-${kind}-${item.id}-${c.tier}`.replace(/[^a-zA-Z0-9-]/g,''),multi=Math.max(1,Math.floor(units/1e6)),title=String(item.title||'Untitled').slice(0,22);return `<div class="v130-plaque v134-plaque v130-plaque-${c.tier} ${small?'small':''}" role="img" aria-label="${esc(c.label)} plaque for ${esc(item.title)}"><svg viewBox="0 0 420 270" aria-hidden="true"><defs><linearGradient id="${id}-frame" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${p.edge}"/><stop offset=".22" stop-color="${p.metal}"/><stop offset=".52" stop-color="${p.edge}"/><stop offset=".78" stop-color="${p.metal}"/><stop offset="1" stop-color="${p.edge}"/></linearGradient><radialGradient id="${id}-disc"><stop offset="0" stop-color="#0b0e12"/><stop offset=".15" stop-color="${p.disc}"/><stop offset=".52" stop-color="${p.edge}"/><stop offset=".82" stop-color="${p.disc}"/><stop offset="1" stop-color="${p.edge}"/></radialGradient></defs><rect x="8" y="8" width="404" height="254" rx="10" fill="#080b10" stroke="url(#${id}-frame)" stroke-width="12"/><rect x="26" y="26" width="368" height="218" rx="5" fill="#11161d" stroke="${p.edge}" stroke-opacity=".5"/><circle cx="120" cy="130" r="74" fill="url(#${id}-disc)" stroke="${p.metal}" stroke-width="3"/><circle cx="120" cy="130" r="21" fill="#11161d" stroke="${p.accent}" stroke-width="3"/><circle cx="120" cy="130" r="4" fill="${p.accent}"/>${V134_plaqueMark(c,p,multi)}<text x="220" y="158" fill="${p.metal}" font-size="${c.label.length>14?18:21}" font-weight="800">${esc(c.label.toUpperCase())}</text><text x="220" y="183" fill="#fff" font-size="15" font-weight="700">${esc(title)}</text><text x="220" y="205" fill="#9aa5b1" font-size="11">${kind==='songs'?'SINGLE':'ALBUM'} · ${fmt(units)} UNITS</text><text x="220" y="226" fill="${p.accent}" font-size="10">ENCORE CAREER AWARD</text></svg></div>`}
V130_plaqueArt=V134_plaqueArt;
function V134_awardSteps(item,kind){const units=certificationUnits(item,kind),current=certificationInfo(units),recorded=Array.isArray(item.certification?.history)?item.certification.history:[],steps=[...V134_CERT_MILESTONES];if(current.tier==='multi')steps.splice(2,0,{label:current.label,units:current.milestone,tier:'multi'});return steps.map(step=>{const hit=recorded.find(x=>String(x.label)===step.label),reached=units>=step.units;return {...step,reached,week:hit?.week??(item.certification?.label===step.label?item.certification.week:null),tracked:!!hit||item.certification?.label===step.label}})}
function V134_awardTimeline(item,kind){return `<div class="v134-award-timeline">${V134_awardSteps(item,kind).map(x=>`<div class="${x.reached?'reached':'locked'}"><i></i><span>${esc(x.label)}</span><strong>${compact(x.units)} units</strong><small>${x.reached?(x.week?`Earned Week ${x.week}`:x.tracked?'Earned during tracked career':'Reached before award-history tracking'):'Locked'}</small></div>`).join('')}</div>`}
certificationCard=function(item,kind){const units=certificationUnits(item,kind),c=certificationInfo(units),remaining=Math.max(0,c.next-units);return `<section class="card certification-card v130-cert-card v134-cert-card"><div class="sectionhead"><div><span class="eyebrow">${kind==='songs'?'SINGLE':'ALBUM'} · TROPHY ROOM</span><h2>${esc(item.title)}</h2></div>${certBadge(item,kind)}</div><div class="v134-cert-stage">${V134_plaqueArt(item,kind)}<aside><span>CURRENT HARDWARE</span><strong>${esc(c.label)}</strong><p>${fmt(units)} equivalent units · ${compact(kind==='albums'?albumStreams(item,true):item.total)} lifetime streams.</p><button class="release-link" onclick="releaseDetails('${kind}',${item.id})">Open release file →</button></aside></div><div class="v134-cert-progress"><span>${remaining?'NEXT AWARD':'HIGHEST NAMED TIER'}</span><strong>${remaining?fmt(remaining)+' units away':'Eternal reached'}</strong><small>${remaining?esc(certificationInfo(c.next).label):'The rarest ENCORE certification tier.'}</small></div>${V134_awardTimeline(item,kind)}</section>`};

/* Living Platforms 2.0 compatibility bridge.
   Preserve established UI markers and normalize platform-row song ids so strategy
   controls always target a real released song. */
V130_trackOptions=function(id){
 const rows=V114_topTracks(id,20),released=(s.songs||[]).filter(x=>x.released),seen=new Set(),options=[];
 for(const x of rows){
  const songId=Number(x.row?.songId??x.row?.id),track=released.find(t=>Number(t.id)===songId);if(!track||seen.has(songId))continue;
  seen.add(songId);options.push(`<option value="${songId}">${esc(track.title)} · ${compact(x.stats?.thisWeek||track.streams||0)} this week</option>`)
 }
 for(const track of released){const songId=Number(track.id);if(seen.has(songId))continue;seen.add(songId);options.push(`<option value="${songId}">${esc(track.title)} · ${compact(track.streams||0)} this week</option>`);if(options.length>=30)break}
 return options.slice(0,30).join('')
};
const V134_platformPanelCompatBase=V114_platformPanel;
V114_platformPanel=function(id){
 let html=V134_platformPanelCompatBase(id);
 if(id==='vybe')html=html.replace('ALGORITHM BOARD','ALGORITHM PULSE · ENGAGEMENT BOARD');
 if(id==='amp'&&!html.includes('COMMUNITY FEED'))html=html.replace('UNDERGROUND 20','UNDERGROUND 20 · COMMUNITY FEED');
 return html
};

